window.SPLK_BANK={"meta":{"built":"2026-08-05","unique":200,"served":259,"mockEligible":192,"authored":94,"excludesUdemy":false},"sections":[{"grp":"1","id":"1.0","title":"Using Transforming Commands for Visualizations","short":"Transforming commands","weight":5},{"grp":"2","id":"2.0","title":"Filtering and Formatting Results","short":"Filtering and formatting","weight":10},{"grp":"3","id":"3.0","title":"Correlating Events","short":"Correlating events","weight":15},{"grp":"4","id":"4.0","title":"Creating and Managing Fields","short":"Field extractions","weight":10},{"grp":"5","id":"5.0","title":"Creating Field Aliases and Calculated Fields","short":"Aliases and calculated fields","weight":10},{"grp":"6","id":"6.0","title":"Creating Tags and Event Types","short":"Tags and event types","weight":10},{"grp":"7","id":"7.0","title":"Creating and Using Macros","short":"Macros","weight":10},{"grp":"8","id":"8.0","title":"Creating and Using Workflow Actions","short":"Workflow actions","weight":10},{"grp":"9","id":"9.0","title":"Creating Data Models","short":"Data models and pivot","weight":10},{"grp":"10","id":"10.0","title":"Using the Common Information Model (CIM) Add-On","short":"CIM","weight":10}],"tests":[{"id":"authored-01","title":"Guide questions 1.0","questionIds":["sg-01-01","sg-01-02","sg-01-03","sg-01-04","sg-01-05"],"authored":true},{"id":"authored-02","title":"Guide questions 2.0","questionIds":["sg-02-01","sg-02-02","sg-02-03","sg-02-04","sg-02-05","sg-02-06","sg-02-07","sg-02-08","sg-02-09"],"authored":true},{"id":"authored-03","title":"Guide questions 3.0","questionIds":["sg-03-01","sg-03-02","sg-03-03","sg-03-04","sg-03-05","sg-03-06","sg-03-07","sg-03-08","sg-03-09","sg-03-10","sg-03-11","sg-03-12","sg-03-13","sg-03-14"],"authored":true},{"id":"authored-04","title":"Guide questions 4.0","questionIds":["sg-04-01","sg-04-02","sg-04-03","sg-04-04","sg-04-05","sg-04-06","sg-04-07","sg-04-08","sg-04-09"],"authored":true},{"id":"authored-05","title":"Guide questions 5.0","questionIds":["sg-05-01","sg-05-02","sg-05-03","sg-05-04","sg-05-05","sg-05-06","sg-05-07","sg-05-08","sg-05-09"],"authored":true},{"id":"authored-06","title":"Guide questions 6.0","questionIds":["sg-06-01","sg-06-02","sg-06-03","sg-06-04","sg-06-05","sg-06-06","sg-06-07","sg-06-08","sg-06-09","sg-06-10"],"authored":true},{"id":"authored-07","title":"Guide questions 7.0","questionIds":["sg-07-01","sg-07-02","sg-07-03","sg-07-04","sg-07-05","sg-07-06","sg-07-07","sg-07-08","sg-07-09","sg-07-10"],"authored":true},{"id":"authored-08","title":"Guide questions 8.0","questionIds":["sg-08-01","sg-08-02","sg-08-03","sg-08-04","sg-08-05","sg-08-06","sg-08-07","sg-08-08","sg-08-09"],"authored":true},{"id":"authored-09","title":"Guide questions 9.0","questionIds":["sg-09-01","sg-09-02","sg-09-03","sg-09-04","sg-09-05","sg-09-06","sg-09-07","sg-09-08","sg-09-09","sg-09-10"],"authored":true},{"id":"authored-10","title":"Guide questions 10.0","questionIds":["sg-10-01","sg-10-02","sg-10-03","sg-10-04","sg-10-05","sg-10-06","sg-10-07","sg-10-08","sg-10-09"],"authored":true},{"id":"test-1","title":"Practice Test 1","questionIds":["t1-q1","t1-q2","t1-q3","t1-q4","t1-q5","t1-q6","t1-q7","t1-q8","t1-q9","t1-q10","t1-q11","t1-q12","t1-q13","t1-q14","t1-q15","t1-q16","t1-q17","t1-q18","t1-q19","t1-q20","t1-q21","t1-q22","t1-q23","t1-q24","t1-q25"],"authored":false},{"id":"test-2","title":"Practice Test 2","questionIds":["t2-q1","t2-q2","t2-q3","t2-q4","t2-q5","t2-q6","t2-q7","t2-q8","t2-q9","t2-q10","t2-q11","t2-q12","t2-q13","t2-q14","t2-q15","t2-q16","t2-q17","t2-q18","t2-q19","t2-q20","t2-q21","t2-q22","t2-q23","t2-q24","t2-q25"],"authored":false},{"id":"test-3","title":"Practice Test 3","questionIds":["t3-q1","t3-q2","t3-q3","t3-q4","t3-q5","t3-q6","t3-q7","t3-q8","t3-q9","t3-q10","t3-q11","t3-q12","t3-q13","t3-q14","t3-q15","t3-q16","t3-q17","t3-q18","t3-q19","t3-q20","t3-q21","t3-q22","t3-q23","t3-q24","t3-q25"],"authored":false},{"id":"test-4","title":"Practice Test 4","questionIds":["t4-q1","t4-q2","t4-q3","t4-q4","t4-q5","t4-q6","t4-q7","t4-q8","t4-q9","t4-q10","t4-q11","t4-q12","t4-q13","t4-q14","t4-q15","t4-q16","t4-q17","t4-q18","t4-q19","t4-q20","t4-q21","t4-q22","t4-q23","t4-q24","t4-q25"],"authored":false},{"id":"test-final","title":"Final Practice Test","questionIds":["tfinal-q1","tfinal-q2","tfinal-q3","tfinal-q4","tfinal-q5","tfinal-q6","t1-q3","t1-q4","t1-q11","t1-q12","t1-q19","t1-q20","t1-q24","t1-q25","t2-q19","t2-q22","t2-q23","t3-q11","t3-q16","t3-q17","t3-q25","t4-q1","t4-q3","t4-q4","t4-q9","t4-q10","t4-q11","t4-q12","t4-q17","t4-q18","t4-q23","t4-q24","t2-q11","t2-q12","t1-q9","t1-q10","t2-q3","t2-q4","t2-q9","t2-q10","t2-q14","t2-q15","t2-q21","t3-q7","t3-q8","t2-q5","t2-q6","t1-q14","t1-q15","t1-q1","t1-q2","t2-q20","t3-q5","t3-q6","t3-q12","t2-q16","t2-q17","t2-q25","t3-q1","t3-q18","t4-q13","t1-q17","t1-q18","t3-q2","t3-q3"],"authored":false}],"traps":{"T-01-01":{"belief":"`limit=10` caps the results table at ten rows.","fact":"On `chart` the default is `top 10` and it limits the number of columns, and `limit` is only valid when a column-split is specified. On `timechart` the default is `top10` distinct split-by values; row count is governed by `span` or `bins`."},"T-01-02":{"belief":"`timechart count BY host, status` produces a nested chart.","fact":"`timechart` allows only one BY clause. `_time` is already the row-split, so the single BY field is the column-split. `chart count BY host status` is legal because `chart` has two slots."},"T-01-03":{"belief":"`chart count OVER host BY status` and `chart count OVER status BY host` give the same table.","fact":"The field after `OVER` is the row-split and becomes the first column and the X-axis; the field after `BY` is the column-split. Swapping them transposes the table. `chart count BY host status` equals `chart count OVER host BY status`."},"T-01-04":{"belief":"`useother=f` removes the `NULL` column.","fact":"`usenull` controls the series for events missing the split-by field, labelled by `nullstr` (default `NULL`). `useother` controls the series for values excluded by `limit` or the where-clause, labelled by `otherstr` (default `OTHER`). Both default to true on `chart` and `timechart`."},"T-01-05":{"belief":"`bins` defaults to 100 everywhere.","fact":"`chart` bin options default to `bins=300`; `timechart` bin options default to `bins=100`. Both set a maximum, not a target, so you can get far fewer bins."},"T-01-06":{"belief":"Specifying both `bins` and `span` narrows the result twice, or errors.","fact":"If you specify both, `span` is used and `bins` is ignored."},"T-01-07":{"belief":"`top 5 host` shows an `OTHER` row for the remaining hosts.","fact":"`useother` defaults to `false` on `top`, so no `OTHER` row appears unless you ask. On `chart` and `timechart` it defaults to `true`."},"T-01-09":{"belief":"`chart cont=false partial=false` is valid.","fact":"`partial` (default true) and `fixedrange` (default true) exist only on `timechart`. `cont` exists on both and defaults to true on both."},"T-01-10":{"belief":"`stats ... BY a b` and `chart ... BY a b` return the same table with different formatting.","fact":"With `stats`, each row is one unique combination and both group-by fields stay as columns. With `chart`, the first BY field becomes rows and the second becomes columns, so the second field's values become column headers and its name disappears."},"T-01-11":{"belief":"`chart sum(A) BY A span=log2` bins field A and sums it.","fact":"With `chart` and `timechart` you cannot use the same field in a function and as the row-split or split-by field. The documented workaround is `eval A1=A` then `chart sum(A) BY A1 span=log2`."},"T-01-12":{"belief":"`timechart count BY categoryId span=1d` sets a daily time bucket.","fact":"Specify `bins` and `span` before the split-by field. Placed after it, Splunk assumes you are binning the split-by field, not the time axis. Write `timechart span=1d count BY categoryId`."},"T-01-14":{"belief":"`table` is transforming, so `table host status` is enough to render any visualization.","fact":"`table` is listed as transforming and is exactly right for a scatter chart because it fixes column order to marker, X, Y. But it aggregates nothing: a pie chart needs an aggregation producing two columns, and the docs warn that `eval` or `fields` can change result structure so that column and bar charts cannot render."},"T-01-17":{"belief":"`limit=0` suppresses the series entirely.","fact":"On `chart`, `limit=0` returns all results. On `timechart` it means all distinct values, no series filtering. On `top` and `rare` it returns all values up to `maxresultrows`, default maximum 50,000."},"T-01-21":{"belief":"`chart count BY vendor_action, user` works because `chart` supports two BY clauses, so `timechart count BY host, status` should work for the same reason.","fact":"the documented syntax is one BY clause taking a row-split and a column-split, `BY <row-split> <column-split>`, comma optional. `timechart` has one BY clause too; it just accepts a single field in it, because `_time` already holds the row-split. Count fields, not clauses."},"T-01-22":{"belief":"`chart sales BY product_name` reports the `sales` field split by product.","fact":"the docs state you must specify a statistical function when you use the `chart` command, so the argument must be a stats-agg-term, a sparkline-agg-term, or a parenthesised eval expression. The working form is `chart sum(price) AS sales BY product_name`. Bare field names belong to `table` and `fields`, which aggregate n."},"T-02-01":{"belief":"`index=web clientip=ipaddress` finds events where the two fields hold the same value.","fact":"`search` expects a field compared to a literal and reads `ipaddress` as the string `ipaddress`. Use `where clientip=ipaddress`, and for the negative either `where fieldA!=fieldB` or `where NOT fieldA=fieldB`."},"T-02-02":{"belief":"AND always binds tighter than OR.","fact":"`search` evaluates OR before AND, so `host=\"www1\" AND status=200 OR action=\"addtocart\"` runs as `host=\"www1\" AND (status=200 OR action=\"addtocart\")`. `eval` and `where` evaluate AND before OR, giving `(host=\"www1\" AND status=200) OR action=\"addtocart\"`. `search` also has no XOR; `eval` and `where` do."},"T-02-03":{"belief":"`NOT status=404` and `status!=404` return the same events.","fact":"`status!=404` returns only events that have a `status` field with a different value, dropping events with no `status`. `NOT status=404` returns everything except the matches, including events with no `status`. Corollary: `NOT field=*` returns events where the field is null, and `field!=*` never returns anything."},"T-02-04":{"belief":"SPL is either all case sensitive or all not.","fact":"For `search`, field names are case sensitive, field values are not, and searches are case-insensitive unless wrapped in `CASE()`. `eval` and `where` are case sensitive throughout, and `like()` matches case-sensitively."},"T-02-05":{"belief":"`coalesce(X,Y)` behaves like `if()`, testing X and returning Y.","fact":"`coalesce(<values>)` takes one or more arguments and returns the first that is not NULL. No test expression, no branches. `if(<predicate>,<true_value>,<false_value>)` is the conditional and takes exactly three arguments. This is the Apress Table 2-16 error verbatim."},"T-02-06":{"belief":"`null()` takes arguments and behaves like `nullif()`.","fact":"`null()` takes no arguments and returns NULL, clearing a field when assigned. `nullif(<field1>,<field2>)` takes two fields and returns NULL when they are equal, otherwise `<field1>`. The second Apress Table 2-16 error."},"T-02-07":{"belief":"A value matching no `case` condition falls through to the last value listed.","fact":"`case` returns NULL when no condition is TRUE. The documented default idiom is a final `true(), \"<default>\"` pair. The mirror is `validate`, which returns the value for the first FALSE condition and defaults to NULL when all are TRUE."},"T-02-08":{"belief":"`eval matched = isnull(user)` puts true or false into `matched`.","fact":"The result of an eval expression cannot be a Boolean, so this errors. Wrap it in `if()`, `case()` or `validate()`, or convert with `tostring()`. The same restriction hits `in()`, `like()`, `cidrmatch()`, `searchmatch()` and the whole `is*` family under `eval`. Under `where` they are used directly, because `where` wants a Boolean."},"T-02-09":{"belief":"`where useragent=\"Mozilla*\"` filters on a prefix.","fact":"`where` has no asterisk wildcard; `*` is a literal there. Use `like(useragent, \"Mozilla%\")` or `useragent LIKE \"Mozilla%\"`."},"T-02-10":{"belief":"The `IN` operator and the `in()` function are the same thing and both take wildcards.","fact":"`IN` works with `search` and `tstats` and accepts `*`, as in `status IN (40*, 500)`. The `in()` function works with `eval`, `where` and `fieldformat`, requires quoted values, and accepts no wildcards; under `eval` it must be nested in `case`, `if` or `validate`."},"T-02-11":{"belief":"The `fillnull` default value is NULL, an empty string, or N/A.","fact":"The default is `0`. Bare `fillnull` writes `0` into every null cell of every field. `value=` precedes the field list in the syntax."},"T-02-13":{"belief":"`fillnull` and `filldown` both write a constant.","fact":"`fillnull` writes one constant everywhere. `filldown` copies the last non-null value seen above that row and leaves the cell NULL when there is no previous value."},"T-02-15":{"belief":"`fieldformat bytes=tostring(bytes,\"commas\")` then `sort - bytes` sorts on the formatted value, and a later `outputcsv` writes the commas.","fact":"`fieldformat` changes rendering only; later commands and export commands such as `outputcsv` and `outputlookup` see the original value. Use `eval` when the change must persist, and place `fieldformat` last. One expression per `fieldformat` command."},"T-02-17":{"belief":"\"Create a field with an eval expression\" always means the `eval` command.","fact":"The `eval` command creates a field for one search. A calculated field defined in props.conf or through Settings creates it for every search touching that source type, and its result is directly searchable in the base search, which an in-pipeline `eval` result is not."},"T-02-18":{"belief":"`stats count BY host` then `search error` finds rows whose events contained `error`.","fact":"`stats` and `chart` do not pass `_raw` down the pipeline, so a later `search` can only use field-value pairs on the surviving fields. Bare keywords have nothing to match."},"T-02-19":{"belief":"`tostring(x,\"commas\")` preserves all decimals, and any format keyword is accepted.","fact":"Only `\"binary\"`, `\"hex\"`, `\"commas\"` and `\"duration\"` are supported. `\"commas\"` rounds to two decimal places; `\"duration\"` converts seconds to `HH:MM:SS`. A currency symbol is not a format option, so concatenate: `\"$\" . tostring(x,\"commas\")`."},"T-03-01":{"belief":"`maxspan` and `maxpause` have positive defaults such as `30s`, `5m` or `1000`.","fact":"Both default to `-1`, meaning no limit, the constraint deactivated. Only `maxevents` has a positive default, `1000`."},"T-03-03":{"belief":"`duration` is in minutes, or is null for a one-event transaction.","fact":"`duration` is the difference in seconds between the timestamps of the first and last events, and a single-event transaction has `duration=0`. Convert with `eval` for minutes."},"T-03-04":{"belief":"The `_time` of a transaction is the latest event, or the time the transaction closed.","fact":"The transaction takes the time and date fields of the earliest member event."},"T-03-05":{"belief":"Any boundary option closes a transaction, so setting `endswith` should give `closed_txn=1`.","fact":"`closed_txn` is set to `1` only if one of `maxevents`, `maxspan`, `maxpause` or `startswith` is specified. `endswith` is not in that list. If none of the four is given, all transactions are output with `closed_txn=0`."},"T-03-06":{"belief":"`keeporphans=true` marks results with `orphan=1` or reuses `closed_txn=0`.","fact":"Orphan results carry a `_txn_orphan` field with value `1`. The option default is `false`."},"T-03-07":{"belief":"`mvlist=false` suppresses multivalue fields entirely, and `true` is the default.","fact":"The default is `false`, which renders multivalue fields as a set of unique values ordered alphabetically. `mvlist=true` renders them as a list of the original event values in arrival order. You can pass a field list to make only those fields render as lists."},"T-03-09":{"belief":"`stats` and `transaction` are equivalent, or `transaction` wins because it produces fewer results.","fact":"`stats` is a transforming command and performs more efficiently, especially in a distributed environment. `transaction` is a centralized streaming command that only runs on the search head."},"T-03-10":{"belief":"`transaction clientip` then `where count>5` filters to transactions of more than five events.","fact":"`transaction` produces `eventcount`. `count` is what `stats` produces. That filter returns nothing."},"T-03-11":{"belief":"`append` and `transaction` compose freely, so `append [search ...]` then `transaction sessionid` works.","fact":"You cannot use `transaction` after `append`. Use `stats` to group after an append."},"T-03-12":{"belief":"`first()` returns the chronologically earliest value, and `latest()` is its synonym.","fact":"`first()` returns the first seen value in processing order, which is the most recent instance; `last()` returns the oldest instance in processing order. For time order use `earliest()` and `latest()`. Processing order is not necessarily chronological order."},"T-03-13":{"belief":"`values()` and `list()` differ only in name.","fact":"`values()` returns distinct values in lexicographical order with no default cap. `list()` returns every value in event order and returns only the first 100 if a field has more than 100 values."},"T-03-14":{"belief":"`maxevents=-1` means no events are allowed.","fact":"A negative value deactivates the constraint, exactly as for `maxspan` and `maxpause`."},"T-03-15":{"belief":"`startswith` and `endswith` take regular expressions.","fact":"A `<filter-string>` is a search expression, a quoted search expression in parentheses, or `eval(<eval-expression>)` returning a Boolean. Use `eval(match(...))` if you genuinely need a regex."},"T-03-16":{"belief":"`transaction host cookie` means host AND cookie, a strict conjunction.","fact":"Splunk does not necessarily interpret multiple fields as a conjunction or a disjunction. If a transitive relationship exists and the events appear in the right sequence, `transaction` uses it. A result with no `host` value can join a transaction with `host=mylaptop`, while `host=mylaptop` and `host=myserver` can never share one."},"T-03-17":{"belief":"`join` is the general-purpose correlation answer and scales like SQL.","fact":"`join` defaults to `max=1` subsearch result per main result, and the right-side dataset defaults to a maximum of 50,000 rows over a maximum runtime of 60 seconds. The docs recommend `stats` and `transaction` over `join` and `append`."},"T-03-19":{"belief":"Transactions can never exceed 1000 events; that is a product ceiling.","fact":"`1000` is the `maxevents` default, settable per search or per `transactiontypes.conf` stanza, and a negative value removes it. The real ceilings are `maxopentxn` (5000 by default in limits.conf) and `maxopenevents` (100000 by default), and those evict rather than truncate."},"T-03-20":{"belief":"`keepevicted` and `keeporphans` do the same thing.","fact":"`keepevicted=true` outputs transactions left open by memory pressure or a missing close condition, identified by `closed_txn=0`. `keeporphans=true` outputs events that never belonged to any transaction, identified by `_txn_orphan=1`. Both default to `false`."},"T-03-22":{"belief":"the options that shape a group come back as fields.","fact":"`maxspan`, `maxpause`, and `maxevents` are inputs only. The command adds `duration` and `eventcount`, sets `closed_txn`, and creates `_txn_orphan` and `transactiontype` only under the relevant options. No field named `transaction` exists either, so filters shaped like `where transaction=\"REJECT\"` match nothing."},"T-03-24":{"belief":"`streamstats` is a cheaper `stats`.","fact":"`streamstats` adds running aggregates to each event as it passes and returns every event; it never collapses events into a group. The grouping commands are `stats` and `transaction`, recommended by the docs over `join` and `append`."},"T-04-01":{"belief":"After saving an extraction you must reindex, or the field only appears on data ingested from now on.","fact":"The Field Extractor creates a search-time extraction only. It applies retroactively to every already-indexed event of that source type or source, and needs no reindex and no restart."},"T-04-02":{"belief":"A field created by `rex` shows up in the fields sidebar for future searches and can be managed under Settings.","fact":"`rex` is a search command, not a knowledge object. Its fields exist for the duration of that one pipeline and appear nowhere in Settings."},"T-04-03":{"belief":"Every FX extraction ends with Select Fields, Validate, Save.","fact":"Validate exists only on the regular expression path. The delimiter path is Select Sample, Select Method, Rename Fields, Save. Counterexamples are a Validate-step feature and do not exist for delimiter extractions."},"T-04-04":{"belief":"The default permission at the Save step is App, so the extraction is immediately visible to everyone in the app.","fact":"The default is Owner, and the docs say it \"only extracts fields in searches run by the person who created the extraction.\" The three choices are Owner, App, All apps."},"T-04-05":{"belief":"Field values are case sensitive.","fact":"Field names are case sensitive, field values are not. `sourcetype=x` and `SOURCETYPE=x` differ, but `status=Failed` matches `failed`. The exception the exam builds on: `eval` and `where` expressions are case sensitive, so `where action=\"Purchase\"` will not match `purchase`."},"T-04-06":{"belief":"`eventtype` and `tag` are default fields extracted at index time.","fact":"The documented default field list is `host`, `index`, `linecount`, `punct`, `source`, `sourcetype`, `splunk_server`, `timestamp`, plus internal `_raw`, `_time`, `_indextime`, `_cd`, `_bkt`, plus the `date_*` fields. Event types and tags are applied at search time, stages 8 and 9."},"T-04-07":{"belief":"Interesting Fields are the fields Splunk considers important, and the 20 percent threshold controls what gets extracted.","fact":"Interesting Fields lists fields appearing in at least 20 percent of the returned events. It is a display rule for the sidebar only. A field in 5 percent of events is fully extracted and fully searchable, just filed under All Fields."},"T-04-08":{"belief":"`rex` requires a `field=` argument.","fact":"`field` defaults to `_raw`. `erex` uses `fromfield`, which also defaults to `_raw`. `extract` has neither and can only read `_raw`."},"T-04-09":{"belief":"`max_match=0` means no matches, or `max_match` is unlimited by default.","fact":"The default is `1`, and `0` means unlimited. Any value above 1 produces a multivalue field. If your pattern has a capture group that can match repeatedly within itself, only the last capture group is used for the multiple matches."},"T-04-11":{"belief":"You can always back out of a manual regex edit in the FX.","fact":"You can select Back to abandon manual editing \"only if you have not yet tried to preview a regular expression change.\" Once you preview an edited regex, the interactive highlighting workflow for that extraction is gone."},"T-04-12":{"belief":"`extract` takes a `field=` argument like `rex`.","fact":"It does not. `extract` works only on `_raw`. The documented workaround is `rename _raw AS temp uri_query AS _raw`, then `extract`, then `rename _raw AS uri_query temp AS _raw`."},"T-04-13":{"belief":"In the delimiter method you must rename every discovered field.","fact":"You must select and rename at least one field to reach Save, and you do not have to rename them all. Unrenamed fields keep their auto-assigned names `field1`, `field2`, `field3` and so on."},"T-04-14":{"belief":"The FX always writes the same configuration whichever method you choose.","fact":"The regular expression method writes an inline `EXTRACT-<class>` into props.conf with the regex embedded. The delimiter method writes a transforms.conf stanza holding `DELIMS` and `FIELDS` plus a `REPORT-<class>` reference in props.conf. This is why changing permissions on a delimiter extraction needs a manual transforms.conf move."},"T-04-15":{"belief":"Delimiters are mostly used for unstructured data.","fact":"Choose Delimiters when values are cleanly separated by a common character and are consistent across events, \"commonly the case with structured, table-based data such as .csv files or events indexed from a database.\" Choose Regular Expression for unstructured data such as a system log. This is the Apress answer-key error verbatim."},"T-04-16":{"belief":"The Event Actions entry point starts the wizard at Select Sample.","fact":"Opening the FX from Event Actions, Extract Fields on a specific event starts you at Select Method, because the source type and sample event are already determined. Every other entry point starts at Select Sample."},"T-04-18":{"belief":"Sample size does not matter.","fact":"The field extractor is limited to twenty lines on a sample event, so a very long multiline event cannot be fully sampled. Separately, automatic search-time key-value extraction finds only the first 100 obvious `key=value` pairs per event, and `extract` defaults to `limit=50` pairs and `maxchars=10240` characters."},"T-04-19":{"belief":"The delimiter method is for data that has no header row","fact":"the docs describe the delimiters method as designed for structured event data, \"data from files with headers, where all of the fields in the events are separated by a common delimiter, such as a comma or space\". The header row lives in the file, not inside each event, which is why the Rename Fields step gives you `field1`, `field2`, `field3` and makes you name them."},"T-04-21":{"belief":"Selected Fields is Splunk's judgement about which fields matter","fact":"on a fresh search Selected Fields contains exactly `host`, `source`, and `sourcetype`. `index` is a default field on every event, so it clears the 20 percent bar and appears under Interesting Fields, not Selected Fields. All Fields is the dialog you use to promote anything else into the selected list."},"T-04-22":{"belief":"Any delimiter character can be chosen from the delimiter list.","fact":"the Rename Fields step offers four presets, Space, Comma, Tab, and Pipe. Every other delimiter, a colon or a semicolon for instance, has to be typed into the **Other** box. Such delimiters work perfectly well; they are simply not on the button list."},"T-05-01":{"belief":"After aliasing `clientip` to `src_ip`, searching `clientip=*` returns nothing.","fact":"An alias does not replace a field in an event or remove it from an event; it is added alongside. Both names work. The command that actually replaces a name is `rename`, and it only affects the current result set."},"T-05-02":{"belief":"`rename clientip AS src_ip` is the same thing as a field alias.","fact":"`rename` is a search command operating on the result set downstream of all nine search-time operations, dropping the old name, lasting one search. An alias is a knowledge object that runs at step 5, keeps the old name, applies to every search against the scoped host, source or source type, and is subject to app scope and permissions."},"T-05-03":{"belief":"`FIELDALIAS-x = userID AS user loginID AS user` merges both source fields into `user`.","fact":"A field can have multiple aliases, but a single alias can only apply to one field. That configuration is documented as invalid and only one of the two takes effect. The documented answer is `EVAL-user = coalesce(userID, loginID)`."},"T-05-05":{"belief":"Since lookups add fields to events, a calculated field's eval expression can use them.","fact":"Calculated fields are step 6 and lookups are step 7. Calculated fields can reference all types of field extractions; they cannot reference lookups, event types or tags. The docs promise an error message for this violation."},"T-05-06":{"belief":"Define `EVAL-duration_ms`, then alias it to `duration` to give it a CIM name.","fact":"Aliasing is step 5 and calculated fields are step 6. The props.conf spec states you cannot alias a calculated field. Give the calculated field the CIM name in the first place, or use a second calculated field."},"T-05-07":{"belief":"`EVAL-response_time = response_time/1000` followed by `EVAL-bitrate = bytes*1000/response_time` uses the converted seconds value.","fact":"All `EVAL-<fieldname>` configurations within a single props.conf stanza are processed in parallel instead of sequentially, so `bitrate` still divides by the original millisecond value. This produces a plausible wrong number, not a missing field."},"T-05-08":{"belief":"The Eval expression box takes a full eval statement such as `eval kb = round(bytes/1024, 2)`.","fact":"The field name is a separate form field (Name in the UI, `<fieldname>` in `EVAL-<fieldname>`), and the Eval expression box holds the right-hand side only. No leading `eval` keyword, no assignment."},"T-05-09":{"belief":"If `status` is already extracted, `EVAL-status` only fills in the gaps.","fact":"The calculated field overrides the extracted field, even if the eval statement evaluates to null. Preserving the extraction requires `EVAL-field = coalesce(field, <expression>)`, or `coalesce(<expression>, field)` if the extraction should only win when the expression is null."},"T-05-11":{"belief":"The scope choices are host, source and event, or host, source and index.","fact":"Both the alias form and the calculated field form scope to a host, a source, or a source type. Nothing else. This is the same triple every props.conf stanza type maps to. The Apress answer key for question E encodes \"Host, Source, Events\"."},"T-05-14":{"belief":"A newly created alias or calculated field is immediately visible to the whole team.","fact":"The knowledge object is private to you when created; other users cannot see or use it. Sharing to an app or globally is a separate step under Settings, Fields, then Permissions. By default only admin and power roles can share and promote, and a power user can only change permissions for objects they own."},"T-05-16":{"belief":"a field present in two source types needs one alias, or the number needed depends on the index or on the original field names matching.","fact":"each field alias configuration is specific to events belonging to a particular host, source, or source type, so two source types need two alias definitions. Index is not a scope, and the pattern matching syntax is documented for the `host::` and `source::` stanza forms, not for a bare source type stanza."},"T-06-01":{"belief":"Tags attach to events, or to fields.","fact":"A tag attaches to a field-value pair, `<field>=<value>`. You tag `host=web01`, `sourcetype=secure`, `status=404` or `eventtype=failed_login`. The event picks up the tag only because it contains that pair. The commonest distractor pair is \"applied to a field\" versus \"applied to a field-value pair\". Choose the pair."},"T-06-02":{"belief":"The field-scoped tag search is `tag:<field>=<name>`, or `tag.<field>`, or `tag[field]`.","fact":"The form is `tag::<field>=<tagname>`, exactly two colons, no spaces. `tag=<tagname>` with no field scope searches every tagged field-value pair. Both forms accept `*`."},"T-06-03":{"belief":"An event type can contain a pipe as long as the pipe comes last.","fact":"The docs forbid a search that \"includes a pipe operator after a simple search\" and one that \"includes a subsearch\". Position does not rescue it. `sourcetype=access_combined_wcookie status=404 | stats count` is an invalid event type definition regardless."},"T-06-04":{"belief":"An event type can reference a report with `savedsearch`.","fact":"The same restriction list forbids referencing a report with the `savedsearch` command inside an event type definition."},"T-06-05":{"belief":"Priority 10 is the highest priority.","fact":"Priority is an integer 1 through 10 and \"1 is the best Priority and 10 is the worst\". Lower number wins. The docs' example gives `critical_disk_error` priority 3 and `all_system_errors` priority 7, and 3 is the better value."},"T-06-06":{"belief":"Priority only affects sort order.","fact":"Priority does two things: event types with a priority are listed above those without and ordered by their priority value, and only one event type colour displays per event, so the colour of the best-priority match renders. Event types with no priority are ordered alphabetically below those that have one."},"T-06-07":{"belief":"`eventtype` is a single-valued field.","fact":"A single event can match multiple event types, and when it matches two or more, `eventtype` acts as a multivalue field. Splunk orders the values by priority score first, then lexicographically."},"T-06-08":{"belief":"An event type is the same thing as a saved search or a report.","fact":"A report is a saved search you run, on demand or on a schedule, returning a result set. An event type is a classification applied automatically at search time to every matching event; you never run it, you search for the field value it produces. A report may contain pipes, transforming commands and subsearches. An event type may not."},"T-06-09":{"belief":"Tags run before event types, or lookups run after event types.","fact":"The order is field filters, inline extraction, transform-based extraction, automatic key-value extraction, field aliasing, calculated fields, lookups, event types, tags. Tags are last, event types second to last. So a tag can be applied to an event type; an event type can reference a lookup output field; a calculated field cannot reference an event type; a lookup cannot reference an event type or a tag; an event type cannot reference a tag."},"T-06-10":{"belief":"Settings, Tags has one list.","fact":"It has three views: List by field-value pair, List by tag name, and All unique tag objects. Disabling a tag from the List by tag name page disables it across all apps that contain it. The All unique tag objects view exposes the individual tag-name to field-value-pair to app combination for per-object permission edits."},"T-06-11":{"belief":"You define tags for an event type using the `tags` attribute in eventtypes.conf.","fact":"That attribute exists but the spec marks it deprecated and points to tags.conf.spec. Tags on an event type live in tags.conf under a stanza header of the form `[eventtype=<name>]`, exactly like any other field-value pair. This is the CIM pattern."},"T-06-12":{"belief":"Tag names are case sensitive and field names are not.","fact":"Backwards. Field names are case sensitive, field values are not. A tag name is matched as a value of the `tag` pseudo-field, so `tag=WebServer` and `tag=webserver` match the same pairs, while `tag::Host=webserver` and `tag::host=webserver` are different searches."},"T-06-13":{"belief":"Because tags cannot have priority or colour, a statement pairing tags with priority and colour must be entirely false.","fact":"You can set priority and colour on the event type, and you can then tag that event type. Priority and colour are never properties of a tag. The Apress question C is keyed false while the same chapter's worked example does exactly this."},"T-06-14":{"belief":"Tagging `host=web01` renames the host.","fact":"Tagging never changes the underlying field value. It adds a searchable alternate label. This is why tagging is the standard remedy when a host value changed for an input and historical events still carry the old value: tag both values with one tag and search the tag."},"T-06-15":{"belief":"The search term is `tags=<tagname>`, or a bare `tag::<fieldname>` finds everything tagged on that field.","fact":"The term is singular, `tag`, and the scoped form always ends with `=<tagname>`, because the tag name is what you match. Wrong options here are mutations of the two real forms: pluralised, single-coloned, colons after the field name instead of before it, or a field name where the tag name belongs. If no option is exactly `tag=<tagname>` or `tag::<field>=<tagname>`, none of them is right."},"T-07-01":{"belief":"A macro is invoked as `'mymacro'` with quotation marks.","fact":"The delimiter is the backtick, the character sharing a key with the tilde. Single or double quotation marks do not invoke a macro; the text is just a search term. Any option using `'` or `\"` around the macro name is wrong."},"T-07-02":{"belief":"`mymacro(2)` means \"the second form\" or \"use argument 2\".","fact":"Verbatim: \"if your search macro mymacro includes two arguments, name it mymacro(2)\". You store `mymacro(2)` and invoke `` `mymacro(foo,bar)` ``. The stored name carries a count; the invocation carries values."},"T-07-03":{"belief":"You write `$val$, $rate$` in the Arguments field to match the definition.","fact":"Arguments is \"a comma-delimited string of argument names\", written bare as `val, rate`, while the Definition references them as `$val$` and `$rate$`."},"T-07-04":{"belief":"One quoting rule covers both macro references and argument tokens.","fact":"Two opposing rules. \"The Splunk platform does not expand macros when they are inside quoted values\", and separately \"The Splunk platform replaces the $<arg>$ pattern globally in the string, even inside quotation marks.\""},"T-07-05":{"belief":"Returning a string from a validation expression means success, and errormsg is always what the user sees.","fact":"A Boolean validation expression succeeds on true and fails on false or NULL, with errormsg supplying the message. A non-Boolean validation expression succeeds on NULL and fails when a string is returned, and the returned string is itself the message, so errormsg is unused."},"T-07-06":{"belief":"A bad macro argument yields zero events.","fact":"Validation runs before dispatch, so the search does not run at all and the user sees the validation error message."},"T-07-07":{"belief":"Editing macros.conf requires a full restart.","fact":"The Admin Manual page on when to restart lists macros.conf among search-time files whose settings take effect without one; refreshing the endpoints is sufficient. The line in macros.conf.spec reading \"You must restart the Splunk instance to enable configuration changes\" is generic boilerplate copied into every spec file. The Apress guide states the restart claim outright."},"T-07-08":{"belief":"Macro expansion sits among field aliases, calculated fields and lookups and obeys the same precedence reasoning.","fact":"The documented nine-step sequence contains no macro step, because expansion is textual and precedes parsing."},"T-07-09":{"belief":"A macro definition starting with `tstats` or `inputlookup` keeps its leading pipe.","fact":"Remove the leading pipe from the definition and put it in the search in front of the reference, as `` | `mygeneratingmacro` ``."},"T-07-11":{"belief":"`[foobar]` and `[foobar(1)]` are one macro with an optional argument.","fact":"From the spec, \"[foobar], [foobar(1)], [foobar(2)], and so forth\" are not the same macro. Calling `` `foobar(x)` `` when only `[foobar]` exists is an error, not a call with an ignored argument."},"T-07-12":{"belief":"Macro arguments are always positional.","fact":"From macros.conf.example, a two-argument macro \"could be invoked equivalently as `foobar(1,2)` `foobar(foo=1,bar=2)` or `foobar(bar=2,foo=1)`\". The documentation's own example uses the named form, `` `iis_search(fragment=TM)` ``."},"T-07-13":{"belief":"`iseval` makes the macro run an eval command and put a computed value in your results.","fact":"`iseval = true` means \"the 'definition' setting is expected to be an eval expression that returns a string representing the expansion of this macro\", default false. `` `fooeval(10,20)` `` is replaced by the text `10 + 20`, which the surrounding search then has to make sense of."},"T-07-14":{"belief":"A macro created in Search and Reporting is available everywhere.","fact":"A new knowledge object is associated with the app context it was created in, and app-level sharing makes it available only to users of that app. Sharing must be All apps to use it elsewhere, and only admin and power roles can share and promote by default."},"T-07-16":{"belief":"a macro with arguments must also carry a validation expression and an error message.","fact":"the documented procedure marks every step except Name and Definition as \"(Optional)\", Destination app included."},"T-07-17":{"belief":"macros are configured in Settings, then Fields, with the other search-time objects, or under Searches, reports, and alerts because a macro is search text","fact":"\"Select Settings > Advanced Search > Search macros.\""},"T-07-18":{"belief":"a macro has to end the search, or piping after a reference requires the macro to be shared globally.","fact":"a reference behaves like the text it becomes, and the manual's own example pipes into one (`` sourcetype=access_* | `mymacro` ``) with nothing stopping further commands after it. Sharing decides whether the macro resolves, not what may follow it."},"T-08-01":{"belief":"The Action type field offers GET, POST and Search.","fact":"Action type has exactly two values, `link` and `search`. GET and POST are both `link` actions, distinguished by Link method (`link.method = get` or `post`). In workflow_actions.conf, `type` accepts only `link` or `search`; there is no `type = get` and no `type = post`."},"T-08-02":{"belief":"With Open link in left untouched, the link opens in the current window, because that is how ordinary hyperlinks behave.","fact":"`link.target` defaults to `blank`, a new window. The same applies to `search.target`, which the spec says works in the same way as `link.target`."},"T-08-03":{"belief":"A stanza with `type = link` and a `link.uri` but no `link.method` does nothing, or is invalid.","fact":"`link.method` defaults to `get`, so a GET is issued. Only `type` and `label` are required for the object to be considered at all, plus `link.uri` for a link action and `search.search_string` for a search action."},"T-08-04":{"belief":"With \"Apply only to the following fields\" left blank, the action never appears, or appears only on events with no fields.","fact":"`fields` defaults to `*`, which matches all fields, so an unrestricted workflow action appears everywhere. Restriction is opt-in, not opt-out."},"T-08-05":{"belief":"`fields = src_ip, dest_ip` means the action shows when either field is present.","fact":"It is a conjunction. Every field listed must be present on the event before the action is applied. The documented example is explicit: `*, ip_client, ip_server` applies to all fields in the event if `ip_client` and `ip_server` are both present."},"T-08-06":{"belief":"POST arguments are appended to the URI, so a POST is just a GET with extra steps.","fact":"`link.postargs.<int>.key` and `.value` pairs are sent HTTP-form encoded in the request body, not in the query string, so they do not appear in the URL, browser history, or the target's access log query string. `link.postargs` is only available when `link.method = post`; setting post arguments on a GET action does nothing."},"T-08-08":{"belief":"With `search.earliest = -7d` and `search.preserve_timerange = true`, the originating search's range wins because the checkbox is on.","fact":"`search.preserve_timerange` is ignored if either `search.earliest` or `search.latest` is set. The range is the last seven days. To inherit the originating range, set `preserve_timerange = true` and leave both bounds empty."},"T-08-10":{"belief":"The Name is what searchers see in the menu.","fact":"Name is the internal name and becomes the stanza header in workflow_actions.conf. Label is the text drawn in the menu, and Label is the field that accepts `$field$` tokens, which is what lets an entry read `Whois: 87.194.216.51` rather than `Whois: $clientip$`. The frequently repeated claim that workflow action names may not contain spaces is not supported by the documentation: the shipped spec examples include `[Create JIRA issue]` and `[Controller req over time]` [verify]."},"T-08-11":{"belief":"A workflow action is how you add a field to your results, or how you trigger an action automatically when a condition is met.","fact":"A workflow action creates no field, modifies no event, and fires only on a human click in Splunk Web. Automatic responses to conditions are alert actions on a saved search; enrichment at search time is lookups, calculated fields, field aliases and extractions. Only the workflow action is user-initiated from a menu."},"T-08-12":{"belief":"\"Show action in\" defaults to the field menu, since most examples are field-level.","fact":"`display_location` defaults to `both`, so an unconfigured action appears in the event menu and the field menus."},"T-08-13":{"belief":"Workflow actions are global by default because they are configured under Settings.","fact":"A newly created knowledge object is only available to the user who created it until explicitly shared, and by default only admin and power roles can share and promote. The Destination app chosen at creation sets the namespace that sharing then operates within."},"T-08-14":{"belief":"With `search.app` and `search.view` omitted, the secondary search runs in Search and Reporting and the default search view.","fact":"`search.app` defaults to the current app and `search.view` defaults to the current view, meaning wherever the analyst happened to be when they clicked."},"T-08-16":{"belief":"a label is invalid unless it contains a field name surrounded by dollar signs.","fact":"a label can be static or include the value of relevant fields, so tokens are supported and never required. \"Must include a token\" is false; \"can include a token\" is true."},"T-08-17":{"belief":"configuring a workflow action includes choosing a sourcetype.","fact":"there is no sourcetype setting in `workflow_actions.conf` and none on the form. Scope is `fields` and `eventtypes` only. Listing `sourcetype` under `fields` does not help either, since that requires the field to exist and it exists on every event. Build an event type and name it in `eventtypes`."},"T-08-18":{"belief":"POST workflow actions are always encrypted.","fact":"nothing about the POST method encrypts anything; transport security depends entirely on whether `link.uri` is `https`. POST guarantees placement, not confidentiality. The arguments avoid the URL bar, browser history and the target's access log query string, and travel in plaintext over `http` just the same."},"T-09-01":{"belief":"Pivot provides a dataset for the data model.","fact":"The reverse. The data model provides the dataset, and Pivot is the SPL-free interface that consumes it to build a report. Pivot cannot run without a data model. The Apress answer key B states the wrong direction outright."},"T-09-02":{"belief":"A child dataset does not inherit from its parent.","fact":"A child dataset inherits all constraints and all fields from every ancestor, then adds its own. Inheritance is cumulative and each level down returns strictly fewer events. The Apress answer key E marks this false."},"T-09-03":{"belief":"The CIM data models ship with acceleration enabled.","fact":"\"All data models included in the CIM add-on have data model acceleration turned off by default.\" You enable it per model on the CIM Setup page by selecting the model and checking Accelerate, which writes `acceleration = 1` for that model. The Apress answer key F states the opposite."},"T-09-04":{"belief":"Acceleration is a property of the whole data model and applies to every dataset in it.","fact":"Acceleration requires at least one root event hierarchy, or one root search hierarchy that uses only streaming commands. Root search datasets built on transforming searches cannot be accelerated, and root transaction datasets and their children do not benefit."},"T-09-05":{"belief":"You add auto-extracted fields wherever you need them.","fact":"Only root datasets can add auto-extracted fields; child datasets inherit them. Eval expression, lookup, regular expression and Geo IP fields can be added to any dataset."},"T-09-06":{"belief":"Required is a documentation hint or a Pivot form validation.","fact":"Required filters out any event that does not have the field, acting as another constraint on top of the formal constraints. Marking a sparse field Required shrinks your dataset without warning."},"T-09-07":{"belief":"A hidden field is removed from the dataset or from search results.","fact":"A hidden field is only suppressed for Pivot users defining a report. The field still exists in the dataset and is still reachable from SPL."},"T-09-08":{"belief":"A root event dataset constraint can contain a pipe and a command such as `stats count`.","fact":"Constraints \"look like the first part of a search, before pipe characters and additional search commands are added\". If you need a pipe you need a root search dataset, and you give up acceleration if that search is transforming."},"T-09-09":{"belief":"Both the Dataset Name and the Dataset ID can be renamed later.","fact":"Dataset Name accepts any character except asterisks and can be changed. Dataset ID accepts only alphanumerics, underscores and hyphens, cannot contain spaces, and cannot be edited after the dataset is saved."},"T-09-10":{"belief":"`tstats` and `from` use the same separator between model and dataset.","fact":"`tstats` uses `FROM datamodel=<model>.<root_dataset>` with an equals sign. `from` uses `from datamodel:<model>.<dataset>` with a colon. Options that swap the two are the standard distractor."},"T-09-11":{"belief":"`tstats` reads only summaries, or `summariesonly=true` is the default.","fact":"`summariesonly` defaults to `false`, and by default `tstats` runs over accelerated and unaccelerated data models alike. Setting it true restricts results to summarized data, which is faster and may be incomplete outside the Summary Range."},"T-09-12":{"belief":"`datamodel M D search` returns every field the dataset defines.","fact":"`strict_fields` defaults to `true`, returning only the default fields and the fields used in the dataset constraints. Set `strict_fields=false` to get all defined fields."},"T-09-13":{"belief":"Using Pivot on an unaccelerated model builds a summary you keep.","fact":"Ad hoc acceleration summaries live in the search head dispatch directory and are deleted when you leave the Pivot Editor or switch to a different dataset. Only persistent acceleration writes shared summaries to the indexers."},"T-09-14":{"belief":"Any user can accelerate their own data model.","fact":"You cannot accelerate data models that are private; the model must be shared at app level or globally, and the user needs a role with the `accelerate_datamodel` capability. By default only admin and power roles can create data models at all."},"T-09-15":{"belief":"A macro is just text substitution, so it is safe in any constraint.","fact":"Child dataset constraints cannot include search macros, and searches referencing child datasets whose constraints contain macros will fail."},"T-09-16":{"belief":"Geo IP output fields behave like any other calculated field and can be set Optional.","fact":"Geo IP fields are added as Required fields and their Type values are predetermined; you cannot change either. They also need an existing field of Type `ipv4` positioned above them."},"T-09-17":{"belief":"Field definition order is cosmetic.","fact":"Fields are processed in descending order from the top of the list to the bottom, so an eval expression that reads another calculated field must sit below it or it evaluates to null."},"T-09-18":{"belief":"You can open any search in Pivot.","fact":"The Pivot button on the Statistics or Visualization tab is available for non-transforming searches. When you save the resulting table or chart, the data model created behind it is private and can only be seen by its creator until an admin or power user shares it."},"T-09-19":{"belief":"An accelerated data model is frozen; you must build a new one to change it.","fact":"\"After you accelerate a data model, you cannot edit it. To make changes to an accelerated data model, you must turn off its acceleration.\" It is uneditable while acceleration is on, but the remedy is to toggle acceleration off, edit, then re-enable, which discards and rebuilds the summaries."},"T-09-22":{"belief":"a child of an event, search or transaction dataset is not one of the data model dataset types, because a data model has only three.","fact":"The correct fact is that three is the count of root types. The docs count four dataset types overall, event, search, transaction and child, so a stem asking what a data model is composed of should include children."},"T-10-01":{"belief":"The CIM normalizes data at index time, or changes how events are stored.","fact":"The CIM is a search-time schema, schema-on-the-fly, and it \"leaves the raw machine data intact\". Installing the add-on reindexes nothing and modifies no indexed event."},"T-10-02":{"belief":"CIM data models are accelerated out of the box, so installing the add-on immediately speeds up searches.","fact":"Acceleration is disabled by default for every CIM data model, and you enable it per model on the CIM Setup page. A `tstats summariesonly=t` search against a stock CIM model returns zero rows. This is the Apress answer key F error."},"T-10-03":{"belief":"Populating the CIM field names is sufficient for compliance.","fact":"Tags are the constraint that admits events into an event dataset. Correct field names without the required tag put the events nowhere. Compliance requires both the tags and the populated required fields."},"T-10-04":{"belief":"The default Indexes allowlist is empty, so the model searches no indexes until you configure one.","fact":"By default each data model searches all indexes. Leaving it that way is a performance problem, not a functional one. The old term \"index whitelist\" is the same setting."},"T-10-05":{"belief":"The CIM add-on is installed on indexers, forwarders, or all tiers.","fact":"Search heads only, because the add-on contains only search-time knowledge objects."},"T-10-06":{"belief":"\"Compute Inventory\" is a current CIM data model name.","fact":"The model is named Inventory in current CIM. \"Compute Inventory\" is the legacy documentation slug for that same page. The same trap works with Application State and Change Analysis, both deprecated in add-on version 4.12.0 and replaced by Endpoint and Change respectively."},"T-10-07":{"belief":"`datamodel Web Web search | table action, status` is a working validation search.","fact":"`datamodel ... search` returns fields under their fully qualified dotted names, so the columns are `Web.action` and `Web.status`. The `flat` mode is what strips the prefix. The plain `table action` returns an empty column."},"T-10-08":{"belief":"You can create a field alias for a lookup output field or for a tag.","fact":"Field aliases are applied after key-value field extraction but before calculated fields, lookups, event types and tags. You cannot alias a calculated field, an event type, a tag, or a lookup-added field."},"T-10-09":{"belief":"`datamodelsimple` is a core SPL command, and `datamodel` is something the CIM add-on installs.","fact":"`datamodel`, `tstats`, `pivot` and `from` are core SPL. `datamodelsimple` is the custom command shipped inside `Splunk_SA_CIM` and does not exist without the add-on."},"T-10-10":{"belief":"CIM expected values are enforced, so an event with `action=denied` in the Authentication model is rejected.","fact":"Expected values are \"not exhaustive or exclusive\" and nothing rejects an out-of-spec value. The consequence is silent: Enterprise Security content looking for `action=failure` simply will not match."},"T-10-11":{"belief":"A Windows service being stopped belongs to the Application State model.","fact":"Application State is deprecated. Endpoint's Services dataset, tagged `service` and `report`, is the current answer. Endpoint superseded Application State in 4.12.0."},"T-10-13":{"belief":"Clone a CIM data model before extending it, to keep the original for record keeping.","fact":"The docs state that cloning the data model and keeping the original is not considered a best practice. Add the custom field to the model itself, or better, avoid extending at all if a field mapping will do."},"T-10-14":{"belief":"The CIM Add-on and the CIM Add-on Builder are the same thing.","fact":"The Splunk Common Information Model Add-on (app 1621, `Splunk_SA_CIM`) supplies the models. The Splunk Add-on Builder is a separate app whose \"Map to data model\" step helps generate mapping knowledge objects for a new sourcetype, and it requires the CIM add-on to map to CIM models. Only the first is on the blueprint."},"T-10-15":{"belief":"`cim_summary` is the index the add-on uses.","fact":"`cim_summary` is deprecated and has been removed. The index that matters now is `cim_modactions`, which supports common action model alerting and auditing."},"T-10-19":{"belief":"A question asks which knowledge objects the CIM uses to normalize data and offers search macros or workflow actions.","fact":"the documented set is field aliases, field extractions, and lookups, alongside the event types and tags that admit events to a dataset, plus calculated fields for derived values. The shipped macros report acceleration status and filter data out of models, so \"the add-on includes macros\" is true while \"macros normalize ."},"T-CIM-02":{"belief":"`action=denied` or `action=deny` is correct for a Network Traffic firewall event.","fact":"Network Traffic prescribes `allowed`, `blocked` and `teardown`. Splunk does not reject `denied`, it just never matches ES content. Same trap with `action=failed` instead of `failure` in Authentication."},"T-CIM-03":{"belief":"`action=teardown` or `action=deferred` is valid on an Intrusion Detection event.","fact":"Intrusion Detection allows only `allowed` and `blocked`. `teardown` belongs to Network Traffic and `deferred` to Malware_Attacks."},"T-CIM-08":{"belief":"An event missing a required field is excluded from the data model.","fact":"Tags decide membership, fields do not. The event sits in the dataset with a null column and disappears only from searches that use that field. Nothing warns."},"T-CIM-12":{"belief":"The Indexes allowlist must be set before a CIM model returns data, or new indexes join it automatically.","fact":"The default is all indexes, so the allowlist is purely a performance control, and new indexes must be added by hand."},"T-CIM-15":{"belief":"A DHCP lease or VPN connection belongs to Network Traffic.","fact":"Network Sessions covers DHCP (`network`,`session`,`dhcp`) and VPN (`network`,`session`,`vpn`). A VPN tunnel's payload flows are Network Traffic; the tunnel establishment is Network Sessions."},"T-CIM-16":{"belief":"`bytes` is unrelated to `bytes_in` and `bytes_out`.","fact":"All three are required in Web and recommended in Network Traffic, and CIM expects `bytes` to be the sum. `EVAL-bytes = bytes_in + bytes_out` is the normal way to satisfy it."},"T-KO-01":{"belief":"The sequence is extraction, alias, calculated field, lookup, event type, tag, full stop.","fact":"The 10.4 docs list nine operations. Field filters is number 1, and field extraction is three separate operations: inline `EXTRACT-` at 2, transform-based `REPORT-` at 3, automatic key-value via `KV_MODE` at 4. The six-step version is items 2 through 9 collapsed."},"T-KO-02":{"belief":"Calculated fields are evaluated before field aliases, because eval feels more primitive.","fact":"Field aliasing is stage 5 and calculated fields are stage 6. \"Calculated fields come after field aliasing but before lookups.\" A calculated field can use an alias; an alias cannot use a calculated field."},"T-KO-03":{"belief":"`FIELDALIAS-x = my_eval_field AS foo` produces `foo`.","fact":"The source field does not exist at stage 5, so nothing is aliased. Worse, since 7.2.4, if the alias field already exists on the event and the source field does not, the alias field is removed from the event."},"T-KO-04":{"belief":"`EVAL-margin = price - cost` works when `price` comes from an automatic lookup.","fact":"Lookups are stage 7 and calculated fields are stage 6, so `price` is null when the eval runs. Calculated fields cannot reference lookups, event types or tags."},"T-KO-06":{"belief":"Tags are only for raw extracted fields, so they cannot apply to event types.","fact":"Tags run last and can be applied to any field-value pair including `eventtype`, whether the field came from index time, search time, an event type, a lookup or a calculated field. Tagging event types is the standard CIM normalization pattern, and the Splunk Web event type form has a Tag(s) field."},"T-KO-09":{"belief":"`LOOKUP-a` outputs `dept`, so `LOOKUP-b` can key on `dept`.","fact":"\"Splunk software does not support nested automatic lookups.\" Both configurations belong to the same stage. Chain them explicitly with the `lookup` command in SPL, where pipeline order is yours."},"T-KO-10":{"belief":"`FIELDALIAS-a = clientip AS ip` then `FIELDALIAS-b = ip AS src` gives you `src`.","fact":"Aliases are one operation, processed in lexicographical order by class name, and chaining is not a documented capability. When two alias configurations write the same destination field the lexicographically last one wins. The documented way to build a field from several sources is a calculated field using `coalesce`, `mvappend` or `mvdedup`."}},"questions":[{"id":"t1-q1","type":"single","stem":"Which of the following actions can the eval command perform?","options":[{"id":"A","text":"Remove fields from results.","correct":false,"why":"The eval command in Splunk is not used to remove fields from results. Its primary function is to create new fields or modify existing fields based on calculations or transformations."},{"id":"B","text":"Create or replace an existing field.","correct":true,"why":"The eval command in Splunk is used to create new fields or replace existing fields in search results. It allows users to perform calculations, transformations, and conditional logic to generate new fields based on existing data."},{"id":"C","text":"Group transactions by one or more fields.","correct":false,"why":"Grouping transactions by one or more fields is typically done using the transaction command in Splunk, not the eval command. The eval command is more focused on manipulating field values rather than grouping transactions."},{"id":"D","text":"Save SPL commands to be reused in other searches.","correct":false,"why":"Saving SPL commands to be reused in other searches is not a functionality of the eval command. This task is typically accomplished by saving searches or creating macros in Splunk for easier reuse of complex search queries."}],"answer":["B"],"explanation":"The eval command calculates an expression and puts the resulting value into a search results field. If the field name that you specify does not match a field in the output, a new field is added to the search results. [ Creating a field] If the field name that you specify matches a field name that already exists in the search results, the results of the eval expression overwrite the values in that field. [Replacing a field]","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-17"],"read":["topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"agree","note":"The eval Description section is the answer verbatim: a field name that does not already exist is added, one that does exist is overwritten. Two nuances worth carrying into the exam. First, eval cannot assign a Boolean, so a bare like() or in() has to sit inside case(), if() or validate(). Second, option A is not quite as dead as the course explanation implies: `eval field=null()` clears a field value, since the docs say \"Setting a field value to NULL clears the field value\". Removing fields is still the job of `fields -`, so B remains the only defensible answer on a single-answer item.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/eval","title":"eval command (SPL Search Reference 10.4)","note":"Description: \"If the field name that you specify does not match a field in the output, a new field is added\"; if it matches, \"the results of the eval expression overwrite the values in that field.\" Usage adds that booleans cannot be assigned to fields.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions (SPL Search Reference 10.4)","note":"null(): \"Setting a field value to NULL clears the field value\", the one sense in which eval can make a field disappear.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q2","type":"single","stem":"When can a pipe follow a macro?","options":[{"id":"A","text":"A pipe may always follow a macro.","correct":true,"why":"A pipe can always follow a macro in Splunk. This allows users to further manipulate and analyze data output from the macro using additional commands in the search pipeline."},{"id":"B","text":"The current user must own the macro.","correct":false,"why":"Ownership of the macro by the current user is not a requirement for a pipe to follow a macro. Users can use macros created by other users as long as they have access to them."},{"id":"C","text":"The macro must be defined in the current app.","correct":false,"why":"The macro does not necessarily have to be defined in the current app for a pipe to follow it. Macros can be defined in any app accessible to the user and can be used in searches across different apps."},{"id":"D","text":"Only when sharing is set to global for the macro.","correct":false,"why":"Setting the sharing of a macro to global is not a prerequisite for a pipe to follow a macro. Pipes can be used with macros regardless of their sharing settings."}],"answer":["A"],"explanation":"Using a basic macro - Pipe to more commands, or precede with a search string.","sec":"7.2","secTitle":"Create and use a basic macro","grp":"7","traps":["T-07-09","T-07-14"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"imprecise","note":"The keyed answer is right for what the question tests: a macro reference is textual substitution inside a pipeline, so more commands can be piped after it (the docs' own example is sourcetype=access_* | `mymacro`). The distractors are not simply false as written. A macro is only usable from an app context where it is visible, so option C is closer to true than the course admits: an object shared at app level is invisible outside that app and has to be promoted to All apps first. The separate rule worth memorising is the mirror image of this question: if the DEFINITION begins with a generating command (search, from, metadata, inputlookup, pivot, tstats), the leading pipe is removed from the definition and written before the backtick in the search. Also, a backtick sequence inside a quoted value is not a macro reference at all and is never expanded.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros","title":"Use search macros in searches (Knowledge Manager Manual 10.4)","note":"Insert search macros into search strings: backticks around the macro name, example sourcetype=access_* | `mymacro`. Also: macros inside quoted values are not expanded, and a macro that expands to a generating command needs a pipe BEFORE the backtick.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf (Configuration File Reference 10.4)","note":"Stanza notes: 'Macros can be used in the search language by enclosing the macro name and any argument list in backtick marks' and 'The Splunk platform does not expand macros when they are inside quoted values'.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/manage-knowledge-object-permissions","title":"Manage knowledge object permissions (Knowledge Manager Manual 10.4)","note":"App-level sharing confines an object to one app context; promoting it to global makes it usable 'no matter what app context they happen to be in'. This is why option C is not purely false.","primary":false}],"difficulty":"medium","issues":["Option C's explanation claims macros 'can be defined in any app accessible to the user and can be used in searches across different apps'. That is only true for globally shared (All apps) macros. A macro shared at app level is visible only in that app context, and the Manage knowledge object permissions page states that users of other apps 'have no idea it exists' until the object is promoted to global availability.","Option B's explanation says ownership is not a requirement, which is true, but it omits the real requirement: the user needs read permission on the macro and must be in an app context where the macro is visible."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q3","type":"multi","stem":"Data models are composed of one or more of which of the following datasets? (Choose all that apply.)","options":[{"id":"A","text":"Events datasets","correct":true,"why":"Events datasets are one of the core components of data models in Splunk. They represent individual log events or data points that are indexed and stored in Splunk for analysis and visualization within the data model structure."},{"id":"B","text":"Search datasets","correct":true,"why":"Search datasets are another essential component of data models in Splunk. They are created based on search queries and represent the results of those queries that are used to populate the data model for analysis and reporting purposes."},{"id":"C","text":"Transaction datasets","correct":true,"why":"Transaction datasets are also a key element of data models in Splunk. They are used to group related events together based on specific criteria, allowing users to analyze and visualize the data as transactions within the data model."},{"id":"D","text":"Any child of event, transaction, and search datasets","correct":true,"why":"Any child of event, transaction, and search datasets is not a valid component of data models in Splunk. Data models are specifically composed of events, search, and transaction datasets, and any other type of dataset does not fall under the standard structure of Splunk data models."}],"answer":["A","B","C","D"],"explanation":"Data Model Dataset Types - A data model can consist of 3 types of datasets • Events • Searches • Transactions","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-02"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"wrong","note":"The course keys only the three root dataset types, but the stem asks what data models are composed of, and the docs answer that with four types. About data models: \"Datasets break down into four types. These types are: Event datasets, search datasets, transaction datasets, and child datasets.\" The Pivot Manual repeats the same list: \"There are four dataset types\", ending with \"Child datasets can be added to any dataset.\" Option D is therefore true, not a distractor. Three is the number of ROOT dataset types, which is a different question.","courseKey":["A","B","C"],"corrected":["A","B","C","D"],"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"Datasets section: \"Datasets break down into four types. These types are: Event datasets, search datasets, transaction datasets, and child datasets.\" Root datasets section names event, search and transaction as the top-level types.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"\"About datasets, briefly\" independently states \"There are four dataset types\" and lists event, transaction, search, and child datasets.","primary":false}],"difficulty":"easy","issues":["Option D's explanation says a child of an event, transaction, or search dataset \"is not a valid component of data models\" and that \"any other type of dataset does not fall under the standard structure\". Both the Knowledge Manager Manual and the Pivot Manual list child datasets as one of the four data model dataset types, so child datasets are a valid component.","The overall explanation's \"A data model can consist of 3 types of datasets\" counts only the root dataset types. The docs count four dataset types overall (event, search, transaction, child) and describe the first three as \"collectively referred to as root datasets\"."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q4","type":"multi","stem":"When using the Field Extractor (FX), which of the following delimiters will work? (Choose all that apply.)","options":[{"id":"A","text":"Tabs","correct":true,"why":"Tabs can be used as delimiters in the Field Extractor (FX) to separate fields in the data. This allows users to extract specific fields based on the tab-separated values in the data."},{"id":"B","text":"Pipes","correct":true,"why":"Pipes can be used as delimiters in the Field Extractor (FX) to separate fields in the data. This allows users to extract specific fields based on the pipe-separated values in the data."},{"id":"C","text":"Colons","correct":true,"why":"Colons can be used as delimiters in the Field Extractor (FX) to separate fields in the data. This allows users to extract specific fields based on the colon-separated values in the data."},{"id":"D","text":"Spaces","correct":true,"why":"Spaces can be used as delimiters in the Field Extractor (FX) to separate fields in the data. This allows users to extract specific fields based on the space-separated values in the data."}],"answer":["A","B","C","D"],"explanation":"Use FX to extract fields that are static and that you use often in searches. Extract fields from events using regex or delimiter. • Delimiter - Use this option when your event contains structured data like a .csv file - The data doesn’t have headers and the fields must be separated by delimiters (spaces, commas, pipes, tabs, or other characters)","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-15"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"imprecise","note":"The key is right, all four work, but the four preset Delimiter buttons in the Rename Fields step are Space, Comma, Tab and Pipe only. A colon works solely through the Other box, where you type the character or characters yourself. Because every option is keyed correct the question carries no discriminating information. Near-duplicate of t1-q13, which swaps Colons for Commas.","courseKey":["A","B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-rename-fields-step","title":"Field Extractor: Rename Fields step (Knowledge Manager 10.4)","note":"\"If you select Space, Comma, Tab, or Pipe, the field extractor breaks the event up into fields based on that delimiter... If the delimiter is not one of those four options, select Other, and enter the delimiter character or characters in the provided field.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-select-method-step","title":"Field Extractor: Select Method step (Knowledge Manager 10.4)","note":"Choose Delimiters when fields are \"cleanly separated by a common delimiter, such as a space, a comma, or a pipe character\" and are consistent across events.","primary":false}],"difficulty":"easy","issues":["The explanation says the delimiters method is for data that \"doesn't have headers\". The 10.4 docs say the opposite: \"The delimiters method is designed for structured event data: data from files with headers, where all of the fields in the events are separated by a common delimiter, such as a comma or space.\" What actually survives is that the header row is not part of each event, which is why the Rename Fields step hands you field1, field2, field3 and makes you rename at least one field by hand.","The explanation implies any of spaces, commas, pipes and tabs is equally on offer as a listed choice, which is true, but the docs are explicit that anything else, including a colon, requires selecting Other and typing the delimiter."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q5","type":"single","stem":"Which group of users would most likely use pivots?","options":[{"id":"A","text":"Users","correct":true,"why":"Users are the group of individuals who would most likely use pivots in Splunk. Pivots allow users to easily visualize and analyze data in different ways, enabling them to gain insights and make data-driven decisions without the need for complex queries or coding skills."},{"id":"B","text":"Architects","correct":false,"why":"Architects typically focus on designing and implementing the overall structure and architecture of a system. While they may use pivots for high-level data analysis, their primary role is not centered around day-to-day data exploration and visualization tasks that pivots are designed for."},{"id":"C","text":"Administrators","correct":false,"why":"Administrators in Splunk are responsible for managing and maintaining the Splunk environment, ensuring data availability, security, and performance. While they may use pivots for troubleshooting or monitoring purposes, their primary focus is on system administration rather than data analysis using pivots."},{"id":"D","text":"Knowledge Managers","correct":false,"why":"Knowledge Managers are responsible for organizing and managing knowledge assets within an organization. While they may use pivots to analyze and extract insights from data, their primary role is more focused on knowledge management rather than utilizing pivots for data exploration and visualization."}],"answer":["A"],"explanation":"Users wilL use the pivot. Knowladge managers will create them","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-01"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"agree","note":"The division to remember is that the knowledge manager builds the data model and a user consumes it through Pivot without writing SPL. Introduction to Pivot: \"The Pivot tool lets you report on a specific data set without the Splunk Search Processing Language (SPL)\" and \"Data models and their datasets are designed by the knowledge managers in your organization.\" About data models adds \"Data models enable users of Pivot to create compelling reports and dashboards without designing the searches that generate them.\"","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"Opening paragraphs: Pivot reports without SPL, and knowledge managers design the data models and datasets that Pivot users consume.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"\"Splunk knowledge managers design and maintain data models\", while Pivot users select a model and dataset to report on.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q6","type":"single","stem":"When multiple event types with different color values are assigned to the same event, what determines the color displayed for the event?","options":[{"id":"A","text":"Rank","correct":false,"why":"Rank is not typically used to determine the color displayed for an event in Splunk. It is more commonly used for sorting or filtering events based on relevance or importance."},{"id":"B","text":"Weight","correct":false,"why":"Weight is not a factor in determining the color displayed for an event in Splunk. It is usually used in statistical calculations or machine learning algorithms to assign importance to different data points."},{"id":"C","text":"Priority","correct":true,"why":"Priority is the correct factor that determines the color displayed for an event in Splunk when multiple event types with different color values are assigned to the same event. Events with higher priority values will be displayed with the corresponding color assigned to them."},{"id":"D","text":"Precedence","correct":false,"why":"Precedence is not the determining factor for the color displayed for an event in Splunk. Precedence typically refers to the order in which rules or configurations are applied, rather than the color assignment for events."}],"answer":["C"],"explanation":"Priority determines the order of the event type listing in the expanded event. Priority determines which event type color displays for an event","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-05","T-06-06"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"imprecise","note":"Priority is right and the overall explanation is almost verbatim from the docs: \"Priority determines the order of the event type listing in the expanded event. It also determines which color displays for the event type if two or more of the event types matching the event have a defined Color value.\" The per-option explanation attached to C is backwards. Priority is an integer 1 through 10 where \"1 is the highest, and 10 is the lowest\" (eventtypes.conf syntax table), and About event type priorities says the color shown is the one belonging to \"the event type with the best Priority value\", so the LOWER number wins. Learn the answer, discard that sentence. Colour itself is a separate setting with a fixed palette (none, et_blue, et_green, et_magenta, et_orange, et_purple, et_red, et_sky, et_teal, et_yellow).","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-type-priorities","title":"About event type priorities (Knowledge Manager 10.4)","note":"\"When an event matches multiple event types, the Color for the event type with the best Priority value is displayed\", and event types with a Priority are listed above those without.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/configure-event-types-in-eventtypes.conf","title":"Configure event types in eventtypes.conf (Knowledge Manager 10.4)","note":"Event type syntax table: priority = <integer>, \"1 is the highest, and 10 is the lowest\"; color takes one of ten et_* values.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/define-event-types-in-splunk-web","title":"Define event types in Splunk Web (Knowledge Manager 10.4)","note":"Add an event type in Settings: \"Priority determines the order of the event type listing in the expanded event. It also determines which color displays for the event type if two or more of the event types matching the event have a defined Color value.\"","primary":false}],"difficulty":"medium","issues":["Option C's explanation says \"Events with higher priority values will be displayed with the corresponding color assigned to them.\" That is backwards. eventtypes.conf documents priority as \"Specifies the order in which matching event types are displayed for an event. 1 is the highest, and 10 is the lowest\", and Splunk Web says \"1 is the best Priority and 10 is the worst\", so the event type with the LOWEST priority number supplies the colour.","Options A and B are dismissed with invented Splunk behaviour: \"Rank ... is more commonly used for sorting or filtering events based on relevance or importance\" and \"Weight ... is usually used in statistical calculations or machine learning algorithms\". Neither Rank nor Weight is an event type setting at all. The only settings in an eventtypes.conf stanza are disabled, search, description, priority and color."],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q7","type":"single","stem":"There are several ways to access the field extractor. Which option automatically identifies the data type, source type, and sample event?","options":[{"id":"A","text":"Event Actions > Extract Fields","correct":true,"why":""},{"id":"B","text":"Fields sidebar > Extract New Fields","correct":false,"why":""},{"id":"C","text":"Settings > Field Extractions > New Field Extraction","correct":false,"why":""},{"id":"D","text":"Settings > Field Extractions > Open Field Extractor","correct":false,"why":""}],"answer":["A"],"explanation":"Access the field extractor from a specific event Use this method to select an event in your search results, and create a field extraction that: • Extracts one or more fields found in that event. • Is tied to the source type of that event. When you use this method to access the field extractor, the field extractor runs against the set of events returned by the search that you have run. 1. Run a search that returns events. 2. Find an event that you want to extract fields from, and click the arrow symbol to the left of the timestamp to open it. 3. Click Event Actions, and select Extract Fields. (A) Note: The field extractor starts you at the Select Method step, in a new browser tab. You have already defined the source type and sample event.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-16","T-04-03"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"agree","note":"The discriminating fact is that this entry point skips Select Sample and starts you at Select Method, in a new browser tab, because the source type and sample event are already defined. Every other listed entry point (fields sidebar Extract New Fields, All Fields dialog Extract new fields, Settings Open field extractor, Home page, after Add Data) starts at Select Sample. Option C is not an FX entry point at all: New Field Extraction on the Field Extractions page is a configuration form for props.conf, not the graphical extractor. The stem's phrase \"data type\" is not Splunk terminology; the docs say only that the source type and sample event are already defined.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/build-field-extractions-with-the-field-extractor","title":"Build field extractions with the field extractor (Knowledge Manager 10.4)","note":"\"Access the field extractor from a specific event\": Event Actions > Extract Fields. \"The field extractor starts you at the Select Method step, in a new browser tab. You have already defined the source type and sample event.\" All other entry points start at Select Sample.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q8","type":"single","stem":"Which of the following statements would help a user choose between the transaction and stats commands?","options":[{"id":"A","text":"stats can only group events using IP addresses.","correct":false,"why":"This statement is incorrect. The stats command can group events based on various fields, not just IP addresses. It provides flexibility in grouping events based on different criteria."},{"id":"B","text":"The transaction command is faster and more efficient.","correct":false,"why":""},{"id":"C","text":"There is a 1000 event limitation with the transaction command.","correct":true,"why":"This statement is correct. The transaction command has a limitation of processing up to 1000 events at a time. If the dataset exceeds this limit, the transaction command may not provide accurate results."},{"id":"D","text":"Use stats when the events need to be viewed as a single correlated event.","correct":false,"why":""}],"answer":["C"],"explanation":"transaction vs. stats • When you have a choice, use stats—it’s faster and more efficient, especially in large Splunk environments • Only use transaction when you: – Need to see events correlated together – Must define event grouping based on start/end values or segment on time • Use stats when you: – Want to see the results of a calculation – Can group events based on a field value (e.g., by src_ip) • By default, there’s a limit of 1,000 events per transaction – No such limit applies to stats – Admins can change limit by configuring max_events_per_bucket in limits.conf","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-19","T-03-09"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"imprecise","note":"The keyed answer is right and the 1,000 figure is real, but it is the default of the transaction command's own maxevents option, not a product ceiling: raise maxevents, or set it negative to deactivate the constraint entirely. Option B is the mirror-image trap, since the docs say stats performs more efficiently, especially in a distributed environment, and option D reverses the rule (seeing events correlated as one event is exactly what transaction is for). The named admin override in the course text is bogus, see explanationIssues and T-03-19.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"Txn definition options: maxevents Default: 1000, \"This constraint is deactivated if the value is negative.\" Memory control options list maxopentxn and maxopenevents, whose defaults are \"read from the transactions stanza in the limits.conf file\".","primary":true},{"url":"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/limits.conf","title":"limits.conf (Admin Manual 10.4)","note":"[transactions] stanza contains only maxopentxn (Default: 5000) and maxopenevents (Default: 100000). max_events_per_bucket is in the [search] stanza and applies to timeline buckets when status_buckets>0.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Using stats instead of transaction: \"In other cases, it's usually better to use the stats command, which performs more efficiently, especially in a distributed environment.\"","primary":false}],"difficulty":"medium","issues":["\"Admins can change limit by configuring max_events_per_bucket in limits.conf\" is a conflation. The setting does exist, but it sits in the [search] stanza of limits.conf where it limits the number of events retrieved for each timeline bucket for searches with status_buckets>0 (Default: 1000 in code). It has nothing to do with the transaction command. The per-transaction 1,000 ceiling is the transaction command's maxevents option (Default: 1000, deactivated if the value is negative). The limits.conf settings that actually bound transaction processing are in the [transactions] stanza: maxopentxn (Default: 5000) and maxopenevents (Default: 100000), both of which can also be passed as memory control options on the command itself.","\"There is a 1000 event limitation with the transaction command\" (option C text and the matching option explanation) states the default as if it were absolute. It is the default value of maxevents and is user-changeable per search, so the accurate phrasing is \"by default there is a limit of 1,000 events per transaction\", which the overallExplanation itself gets right two lines later."],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q9","type":"single","stem":"By default, how is acceleration configured in the Splunk Common Information Model (CIM) add-on?","options":[{"id":"A","text":"Turned off.","correct":true,"why":"By default, acceleration is turned off in the Splunk Common Information Model (CIM) add-on. This means that data models and datasets are not pre-built for faster search performance unless explicitly enabled by the user."},{"id":"B","text":"Turned on.","correct":false,"why":""},{"id":"C","text":"Determined automatically based on the sourcetype.","correct":false,"why":""},{"id":"D","text":"Determined automatically based on the data source.","correct":false,"why":""}],"answer":["A"],"explanation":"The data models included in the CIM add-on are configured with data model acceleration turned off.","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-02","T-09-03"],"read":["topics/10-cim.md#syntax-and-options","reference/cim-data-models.md"],"verdict":"agree","note":"Documentation is explicit twice over: \"By default, the data model acceleration for all models included in the Splunk Common Information Model Add-on are disabled\" (Accelerate CIM data models) and \"All data models included in the CIM add-on have data model acceleration turned off by default\" (Set up the CIM Add-on). You turn it on per model on the CIM Setup page (Apps > Manage Apps > Set up on the Splunk Common Information Model row). Options C and D are inventions: nothing about acceleration is decided from sourcetype or data source. The one real exception is that Enterprise Security and the App for PCI Compliance auto-accelerate some CIM models through a Data Model Acceleration Enforcement modular input, but that is those apps acting, not the CIM add-on default. Worth knowing that the Apress study guide in this repo keys the same fact the opposite way while its own body text agrees with this answer. See source-notes/apress-errata.md.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/accelerate-cim-data-models","title":"Accelerate CIM data models (Common Information Model 8.6)","note":"Enable data model acceleration section: \"By default, the data model acceleration for all models included in the Splunk Common Information Model Add-on are disabled.\"","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/set-up-the-splunk-common-information-model-add-on","title":"Set up the Splunk Common Information Model Add-on (CIM 8.6)","note":"Accelerating CIM data models section repeats it: \"All data models included in the CIM add-on have data model acceleration turned off by default.\" Also documents the CIM Setup page where you enable it.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q10","type":"multi","stem":"Which of the following statements describe the Common Information Model (CIM)? (Choose all that apply.)","options":[{"id":"A","text":"CIM is a methodology for normalizing data.","correct":true,"why":"The Common Information Model (CIM) is indeed a methodology for normalizing data. It provides a common framework for organizing and standardizing data from different sources, making it easier to analyze and correlate information."},{"id":"B","text":"CIM can correlate data from different sources.","correct":true,"why":"CIM is designed to correlate data from various sources by providing a standardized way to represent and structure data. This correlation helps in identifying relationships and patterns across different datasets for more comprehensive analysis."},{"id":"C","text":"The Knowledge Manager uses the CIM to create knowledge objects.","correct":true,"why":"The Knowledge Manager in Splunk utilizes the Common Information Model (CIM) to create knowledge objects such as data models, field extractions, and event types. By using CIM, the Knowledge Manager can ensure consistency and interoperability in managing data."},{"id":"D","text":"CIM is an app that can coexist with other apps on a single Splunk deployment.","correct":true,"why":""}],"answer":["A","B","C","D"],"explanation":"• The Splunk Common Information Model (CIM) provides a methodology to normalize data. • Leverage the CIM when creating field extractions, field aliases,event types, and tags to ensure: – Multiple apps can co-exist on a single Splunk deployment – Object permissions can be set to global for the use of multiple apps – Easier and more efficient correlation of data from different sources and source types • The Common Information Model Add-on is based on the idea that you can break down most log files into two components: - fields - event category tags With these two components, a knowledge manager can normalize log files at search time so that they follow a similar schema.","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-01","T-10-03","T-10-14"],"read":["topics/10-cim.md#what-it-is"],"verdict":"imprecise","note":"All four are keyed correct, so the item discriminates nothing, and two of the four are loose. Option D calls the CIM \"an app\": the docs consistently say the CIM \"is implemented as an add-on\" (Splunk_SA_CIM), and the course point the option is derived from is that normalizing with the CIM lets multiple apps co-exist on one deployment, not that the CIM itself co-exists. Option C is course-slide phrasing, not doc phrasing. A and B are straight from the overview: the CIM is \"a shared semantic model\" that \"helps you to normalize your data to match a common standard, using the same field names and event tags for equivalent events from different sources or vendors\", after which you \"develop reports, correlation searches, and dashboards to present a unified view of a data domain\". The fact the exam actually tests is that CIM is a search-time schema (\"schema-on-the-fly\") that leaves the raw machine data intact.","courseKey":["A","B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/overview-of-the-splunk-common-information-model","title":"Overview of the Splunk Common Information Model (CIM 8.6)","note":"Definition sentence, \"implemented as an add-on\", the schema-on-the-fly statement, and the $SPLUNK_HOME/etc/apps/Splunk_SA_CIM/default/data/models path for the shipped models.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/understand-and-use-the-common-information-model-add-on","title":"Understand and use the Common Information Model Add-on (Knowledge Manager Manual 10.4)","note":"Source of the two-components framing quoted in the explanation: fields plus event category tags, with which \"a knowledge manager can normalize log files at search time so that they follow a similar schema\".","primary":false},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/approaches-to-using-the-cim","title":"Approaches to using the CIM (CIM 8.6)","note":"The three or four documented uses: normalize, validate, generate reports and dashboards, build a custom alert action on the common action model.","primary":false}],"difficulty":"easy","issues":["Option C's explanation says the Knowledge Manager uses the CIM \"to create knowledge objects such as data models, field extractions, and event types\". The CIM data models are not created by the knowledge manager, they ship with the add-on as JSON in $SPLUNK_HOME/etc/apps/Splunk_SA_CIM/default/data/models. The knowledge manager creates tags, event types, field aliases, field extractions and lookups to map data INTO those shipped models."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q11","type":"single","stem":"Which of the following knowledge objects represents the output of an eval expression?","options":[{"id":"A","text":"Eval fields","correct":false,"why":""},{"id":"B","text":"Calculated fields","correct":true,"why":""},{"id":"C","text":"Field extractions","correct":false,"why":""},{"id":"D","text":"Calculated lookups","correct":false,"why":""}],"answer":["B"],"explanation":"Calculated fields enable you to define fields with eval expressions. Calculated fields are fields added to events at search time that perform calculations with the values of two or more fields already present in those events. Use calculated fields as a shortcut for performing repetitive, long, or complex transformations using the eval command.","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-02-17","T-05-08"],"read":["topics/05-aliases-and-calculated-fields.md#what-it-is"],"verdict":"agree","note":"Settled verbatim by the docs: \"Calculated fields enable you to define fields with eval expressions.\" One caveat for revision: the docs' own opening sentence says a calculated field performs calculations \"with the values of two or more fields\", which the course quotes, but the same manual's example EVAL-x = x * 2 uses a single field and the props.conf page says the eval statement \"is as flexible as it is for the eval search command\", so do not memorise \"two or more\" as a rule.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Manager Manual 10.4)","note":"\"Calculated fields enable you to define fields with eval expressions. When writing a search, you can cut out the eval expression and reference the field like any other extracted field.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/configure-calculated-fields-with-props.conf","title":"Configure calculated fields with props.conf (Knowledge Manager Manual 10.4)","note":"EVAL-<field_name> = <eval statement>; \"<eval_statement> is as flexible as it is for the eval search command. It can be evaluated to any value type, including multivals, boolean, or null.\"","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q12","type":"single","stem":"What do events in a transaction have in common?","options":[{"id":"A","text":"All events in a transaction must have the same timestamp.","correct":false,"why":""},{"id":"B","text":"All events in a transaction must have the same sourcetype.","correct":false,"why":""},{"id":"C","text":"All events in a transaction must have the exact same set of fields.","correct":false,"why":""},{"id":"D","text":"All events in a transaction must be related by one or more fields.","correct":true,"why":""}],"answer":["D"],"explanation":"• A transaction is a group of conceptually-related events that spans time. A transaction type is a transaction that has been configured in transactiontypes.conf and saved as a field. • The transaction command creates a single event from a group of events – The events must share the same value in a specified field • Transactions can include: -Different events from the same source and the same host. -Different events from different sources from the same host. -Similar events from different hosts and different sources.","sec":"3.2","secTitle":"Group events using fields","grp":"3","traps":["T-03-16"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"agree","note":"The docs kill A, B and C in one sentence: transactions can include different events from the same source and host, different events from different sources on the same host, and similar events from different hosts and different sources. Two nuances worth carrying even though they do not change the answer. The field-list is optional in the syntax, so a transaction defined purely by startswith or endswith has no shared field at all, and an event that is simply missing the field can still join a transaction with events that have it (only a different value excludes it).","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/identify-and-group-events-into-transactions","title":"Identify and group events into transactions (Search Manual 10.4)","note":"[field-list]: \"each event must have the same field(s) to be considered part of the same transaction. Events with common field names and different values will not be grouped.\" Also the list of what transactions can include across hosts, sources and sourcetypes, which is the source of the course's own explanation text.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Definition: \"A transaction is any group of conceptually-related events that spans time.\" A transaction type is a configured transaction saved as a field, defined in transactiontypes.conf.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q13","type":"multi","stem":"Which delimiters can the Field Extractor (FX) detect? (Choose all that apply.)","options":[{"id":"A","text":"Tabs","correct":true,"why":""},{"id":"B","text":"Pipes","correct":true,"why":""},{"id":"C","text":"Spaces","correct":true,"why":""},{"id":"D","text":"Commas","correct":true,"why":""}],"answer":["A","B","C","D"],"explanation":"Use FX to extract fields that are static and that you use often in searches. Extract fields from events using regex or delimiter. • Delimiter - Use this option when your event contains structured data like a .csv file - The data doesn’t have headers and the fields must be separated by delimiters (spaces, commas, pipes, tabs, or other characters)","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-15"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"imprecise","note":"All four here are the actual preset Delimiter buttons in the Rename Fields step: Space, Comma, Tab, Pipe. So the key is right and, with every option correct, the question does not discriminate. Near-duplicate of t1-q4, which swaps Colons for Commas; a colon also works, but only through Other.","courseKey":["A","B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-rename-fields-step","title":"Field Extractor: Rename Fields step (Knowledge Manager 10.4)","note":"Space, Comma, Tab and Pipe are the named delimiter options; Other covers any additional character or character combination.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/build-field-extractions-with-the-field-extractor","title":"Build field extractions with the field extractor (Knowledge Manager 10.4)","note":"Overview table: the Rename Fields step is the delimiters-only step where you identify the delimiter and rename the fields it finds.","primary":false}],"difficulty":"easy","issues":["The explanation says the delimiters method is for data that \"doesn't have headers\". The 10.4 docs describe it as designed for \"data from files with headers, where all of the fields in the events are separated by a common delimiter\". The defensible version is that the header row is not carried inside each event, which is why the extractor names the fields field1, field2, field3 for you to rename."],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q14","type":"single","stem":"A data model consists of which three types of datasets?","options":[{"id":"A","text":"Constraint, field, value.","correct":false,"why":""},{"id":"B","text":"Events, searches, transactions.","correct":true,"why":""},{"id":"C","text":"Field extraction, regex, delimited.","correct":false,"why":""},{"id":"D","text":"Transaction, session ID, metadata.","correct":false,"why":""}],"answer":["B"],"explanation":"Data Model Dataset Types - A data model can consist of 3 types of datasets • Events • Searches • Transactions","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-08"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"imprecise","note":"Key stands: every other option is nonsense, and events, searches and transactions are the three types the docs name for ROOT datasets. The stem's \"three types of datasets\" is loose, though. About data models says datasets break down into FOUR types, the fourth being child datasets. Read this question as \"three types of root dataset\" and it is exact.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"Root datasets section: \"The top-level event, search, and transaction datasets in data models are collectively referred to as root datasets.\" The Datasets section counts four dataset types including child datasets.","primary":true}],"difficulty":"easy","issues":["\"A data model can consist of 3 types of datasets\" is the count of root dataset types only. Both the Knowledge Manager Manual and the Pivot Manual state there are four data model dataset types: event, search, transaction, and child."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q15","type":"single","stem":"Where are the results of eval commands stored?","options":[{"id":"A","text":"In a field.","correct":true,"why":""},{"id":"B","text":"In an index.","correct":false,"why":""},{"id":"C","text":"In a KV Store.","correct":false,"why":""},{"id":"D","text":"In a database.","correct":false,"why":""}],"answer":["A"],"explanation":"The eval command calculates an expression and puts the resulting value into a search results field. You must specify a field name for the results that are returned from your eval command expression. You can specify a name for a new field or for an existing field. Note: If the field name that you specify matches an existing field name, the values in the existing field are replaced by the results of the eval expression.","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-17"],"read":["topics/02-filtering-and-formatting.md#result-contract"],"verdict":"agree","note":"eval results live in a search results field and nowhere else. Nothing is written to an index, a KV Store collection or a database: the field exists only for the duration of the search pipeline, which is why an eval field vanishes unless a later command such as table, stats or collect keeps it. The docs require a destination field name, and if that name already exists its values are replaced.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/eval","title":"eval command (SPL Search Reference 10.4)","note":"Usage, General: \"You must specify a field name for the results that are returned from your eval command expression\", plus the CAUTION that an existing field name is overwritten.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q16","type":"multi","stem":"Which of the following statements describe calculated fields? (Choose all that apply.)","options":[{"id":"A","text":"Calculated fields can be used in the search bar.","correct":true,"why":"Once defined, calculated fields behave like regular fields and can be used in searches."},{"id":"B","text":"Calculated fields can be based on an extracted field.","correct":true,"why":"Calculated fields are often built using existing extracted fields (e.g., eval total=price*quantity where price and quantity are extracted fields)."},{"id":"C","text":"Calculated fields can only be applied to host and sourcetype.","correct":false,"why":"They can be applied to host, source, or sourcetype, but not limited to just host and sourcetype."},{"id":"D","text":"Calculated fields are shortcuts for performing calculations using the eval command.","correct":true,"why":"Calculated fields are essentially saved eval expressions that run at search time."}],"answer":["A","B","D"],"explanation":"Calculated Field • Shortcut for performing repetitive, long, or complex transformations using the eval command • Must be based on an extracted field • After you have created a calculated field, you can use it in a search like any other extracted field","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-08","T-05-11","T-05-09"],"read":["topics/05-aliases-and-calculated-fields.md#syntax-and-options"],"verdict":"imprecise","note":"The keyed set is right. The scope choices are host, source and sourcetype, which is what makes option C false: the sequence page states \"Each calculated field configuration is specific to events belonging to a particular host, source, or source type\", and props.conf gives the three stanza forms as <sourcetype>, host::<host> and source::<source>. That triple is itself a tested fact, and the Apress book keys it wrongly as host, source and events. Option A is confirmed by the props.conf example, which rewrites the search as `source=eqs7day-M1.csv Description=Deep` once the calculated field exists. Downgraded to imprecise only because of the \"must be based on an extracted field\" line in the explanation.","courseKey":["A","B","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/configure-calculated-fields-with-props.conf","title":"Configure calculated fields with props.conf (Knowledge Manager Manual 10.4)","note":"Stanza forms section: <stanza> can be <source type>, host::<host>, or source::<source>. Example section shows the calculated field being searched on directly, which settles option A.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Manager Manual 10.4)","note":"\"Use calculated fields as a shortcut for performing repetitive, long, or complex transformations using the eval command\" and the Restrictions section listing what a calculated field may reference.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Manager Manual 10.4)","note":"Calculated fields section: \"Each calculated field configuration is specific to events belonging to a particular host, source, or source type.\"","primary":false}],"difficulty":"medium","issues":["\"Must be based on an extracted field\" is too narrow. The docs say \"Calculated fields can reference all types of field extractions. They can't reference lookups, event types, or tags\", and because field aliasing is stage 5 and calculated fields stage 6, an eval expression may also reference a field alias. It need not reference an extracted field at all: the eval statement is as flexible as the eval command and can return a constant. The real rule is directional, not a requirement to use an extracted field."],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q17","type":"single","stem":"Calculated fields can be based on which of the following?","options":[{"id":"A","text":"Tags","correct":false,"why":"Tags are labels applied to field values or event types and are not used in calculations for eval-based calculated fields."},{"id":"B","text":"Extracted fields","correct":true,"why":"Calculated fields are most commonly based on fields that have already been extracted at index time or search time. For example, eval total=price*quantity relies on price and quantity being extracted fields."},{"id":"C","text":"Output fields for a lookup","correct":false,"why":"Calculated fields are not directly based on lookup outputs. While you can use a lookup in a search, calculated fields themselves are created using eval, not from dynamic lookup results."},{"id":"D","text":"Fields generated from a search string","correct":false,"why":"Calculated fields are evaluated at search time but are not defined within search strings. They are saved knowledge objects defined in settings (like props.conf or via Splunk Web)."}],"answer":["B"],"explanation":"Calculated Field • Shortcut for performing repetitive, long, or complex transformations using the eval command • Must be based on an extracted field • After you have created a calculated field, you can use it in a search like any other extracted field","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-05","T-KO-04","T-10-08"],"read":["reference/knowledge-object-precedence.md","topics/05-aliases-and-calculated-fields.md#decision-rules"],"verdict":"imprecise","note":"The key is right and this is a search-time precedence question wearing a different hat, which makes it one of the highest-yield ideas on the exam. Calculated fields run at stage 6, lookups at 7, event types at 8, tags at 9, so a calculated field can see extractions and aliases and can never see a lookup output, an event type or a tag. The docs state it flatly: \"Calculated fields can reference all types of field extractions. They can't reference lookups, event types, or tags.\" Marked imprecise because option C's explanation gives the wrong reason.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Manager Manual 10.4)","note":"Restrictions section: \"Calculated fields can reference all types of field extractions. They can't reference lookups, event types, or tags.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Manager Manual 10.4)","note":"The nine-operation table plus the worked example explaining why a calculated field can use extracted fields but never lookup fields.","primary":false}],"difficulty":"hard","issues":["Option C's explanation says lookups are excluded because \"calculated fields themselves are created using eval, not from dynamic lookup results\". That is not the reason. The reason is ordering: the sequence page says \"make sure an eval expression for a calculated field never includes fields that are added through a lookup operation. Splunk software always performs calculated field operations ahead of lookup operations... You will get an error message if your calculated field eval expression includes fields that are added through lookups.\"","The overall explanation's \"Must be based on an extracted field\" is too narrow. A calculated field may also reference a field alias, since aliasing is stage 5 and calculated fields stage 6, and the eval statement can be as flexible as the eval command."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q18","type":"single","stem":"When should transaction be used?","options":[{"id":"A","text":"Only in a large distributed Splunk environment.","correct":false,"why":""},{"id":"B","text":"When calculating results from one or more fields.","correct":false,"why":""},{"id":"C","text":"When event grouping is based on start/end values.","correct":true,"why":""},{"id":"D","text":"When grouping events results in over 1000 events in each group.","correct":false,"why":""}],"answer":["C"],"explanation":"transaction vs. stats • When you have a choice, use stats—it’s faster and more efficient, especially in large Splunk environments • Only use transaction when you: – Need to see events correlated together – Must define event grouping based on start/end values or segment on time • Use stats when you: – Want to see the results of a calculation – Can group events based on a field value (e.g., by src_ip) • By default, there’s a limit of 1,000 events per transaction – No such limit applies to stats – Admins can change limit by configuring max_events_per_bucket in limits.conf","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-09"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"imprecise","note":"Keyed answer C is correct and doc-backed: startswith and endswith have no stats equivalent, and the docs state outright that when an id is reused and each unit ends with a marker such as \"END\", \"the only solution is to use this transaction search\". Option D is the instructive trap and it inverts the real rule, since a group exceeding 1,000 events is a reason to avoid transaction, not a reason to reach for it. The verdict is imprecise only because this question carries the same bogus max_events_per_bucket claim in its overallExplanation as t1-q8.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Using stats instead of transaction names the two cases where transaction is most useful: when a unique id alone cannot separate two transactions (so time spans, pauses or begin/end messages are needed), and when you want the combined raw text. Otherwise stats \"performs more efficiently, especially in a distributed environment\".","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"startswith and endswith mark the beginning and end of a transaction; maxevents Default: 1000. Usage confirms transaction is a centralized streaming command.","primary":false},{"url":"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/limits.conf","title":"limits.conf (Admin Manual 10.4)","note":"[transactions] holds only maxopentxn and maxopenevents; max_events_per_bucket belongs to [search] and governs timeline buckets.","primary":false}],"difficulty":"medium","issues":["\"Admins can change limit by configuring max_events_per_bucket in limits.conf\" is a conflation. The setting does exist, but it sits in the [search] stanza of limits.conf where it limits the number of events retrieved for each timeline bucket for searches with status_buckets>0 (Default: 1000 in code). It has nothing to do with the transaction command. The per-transaction 1,000 ceiling is the transaction command's maxevents option (Default: 1000, deactivated if the value is negative). The limits.conf settings that actually bound transaction processing are in the [transactions] stanza: maxopentxn (Default: 5000) and maxopenevents (Default: 100000)."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q19","type":"single","stem":"When performing a regular expression (regex) field extraction using the Field Extractor (FX), what happens when the require option is used?","options":[{"id":"A","text":"The regex can no longer be edited.","correct":false,"why":""},{"id":"B","text":"The field being extracted will be required for all future events.","correct":false,"why":""},{"id":"C","text":"The events without the required field will not display in searches.","correct":false,"why":""},{"id":"D","text":"Only events with the required string will be included in the extraction.","correct":true,"why":""}],"answer":["D"],"explanation":"Require option – only events with the highlighted string are included in the extraction.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-18","T-04-11"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"agree","note":"Require narrows which events the extraction itself matches, not what anyone's search returns. The docs say required text \"behaves like a search filter. It is a string of text that must be present in the event for Splunk software to match it with the extraction\", which is exactly why option C is the attractive wrong answer. Two limits worth memorising: only one required-text string per field extraction, and you cannot apply Require to text you have already highlighted as a field value (or the reverse). Option A is false because Show Regular Expression > Edit the Regular Expression remains available.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-select-fields-step","title":"Field Extractor: Select Fields step (Knowledge Manager 10.4)","note":"\"Identify required text to create extractions that match specific event patterns\": required text behaves like a search filter and must be present for the extraction to match; highlight the text, select Require, then Add Required Text. Lists the one-string-per-extraction and no-overlap limits.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/build-field-extractions-with-the-field-extractor","title":"Build field extractions with the field extractor (Knowledge Manager 10.4)","note":"Step overview: in Select Fields you can optionally \"Identify required text to focus the field extraction on events that contain this text\", regular expression method only.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q20","type":"single","stem":"When using | timechart by host, which field is represented in the x-axis?","options":[{"id":"A","text":"date","correct":false,"why":""},{"id":"B","text":"host","correct":false,"why":""},{"id":"C","text":"time","correct":false,"why":""},{"id":"D","text":"_time","correct":true,"why":""}],"answer":["D"],"explanation":"A timechart is a statistical aggregation applied to a field to produce a chart, with time used as the X-axis • timechart command performs statistical aggregations against time. • Plots and trends data over time. • _time is always the x-axis","sec":"1.2","secTitle":"Use the timechart command","grp":"1","traps":["T-01-12"],"read":["topics/01-transforming-commands.md#result-contract"],"verdict":"agree","note":"Docs are explicit: \"A timechart is a statistical aggregation applied to a field to produce a chart, with time used as the X-axis\", and every worked example in the topic shows `_time` as the first column of the results table. The `_time` x-axis is guaranteed and is exactly why timechart accepts only one BY clause: the split-by becomes the columns because the rows are already spoken for. Option C is the trap, the field is `_time`, not `time`.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/timechart","title":"timechart command (Search Reference 10.4)","note":"Description: time is the X-axis, each distinct split-by value becomes a series. Results tables in the examples show _time as the first column.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (Search Reference 10.4)","note":"Usage, X-axis section: \"Unlike the timechart command which generates a chart with the _time field as the x-axis, the chart command produces a table with an arbitrary field as the x-axis.\"","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q21","type":"single","stem":"Which of the following is the correct way to use the datamodel command to search fields in the Web data model within the Web dataset?","options":[{"id":"A","text":"| datamodel Web Web search | fields Web*","correct":true,"why":""},{"id":"B","text":"| search datamodel Web Web | fields Web*","correct":false,"why":""},{"id":"C","text":"| datamodel Web Web fields | search Web*","correct":false,"why":""},{"id":"D","text":"datamodel=Web | search Web | fields Web*","correct":false,"why":""}],"answer":["A"],"explanation":"Syntax: | datamodel [data model name] [dataset name] [search mode {search, flat, accelerate_search}]","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-10-07","T-09-12","T-09-10"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"imprecise","note":"Option A is right. The Search Reference gives the syntax as | datamodel [<data model name>] [<dataset name>] [<data model search mode>] and states \"The datamodel command is a generating command and should be the first command in the search. Generating commands use a leading pipe character\", which alone eliminates option D. Do not confuse this with the other two syntaxes: tstats ... FROM datamodel=Model.Dataset uses a dot, and | from datamodel:Model.Dataset uses a colon. Note the mode name in the course's syntax line is misspelled, see below.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/datamodel","title":"datamodel command (Search Reference 10.4)","note":"Syntax and \"Data model search mode options\": positional order is data model name, dataset name, search mode; modes are search, flat, acceleration_search and their _string variants. Usage confirms it is a generating command that must lead with a pipe.","primary":true}],"difficulty":"hard","issues":["The syntax line names the third positional argument \"accelerate_search\". The documented mode name is acceleration_search.","The list of search modes is incomplete. datamodel accepts six modes: three result modes (search, flat, acceleration_search) and three string modes (search_string, flat_string, acceleration_search_string). It also accepts strict_fields, allow_old_summaries and summariesonly as named arguments."],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q22","type":"multi","stem":"Which of the following statements describe the command below? (Choose all that apply.)\n\nsourcetype=access_combined | transaction JSESSIONID","options":[{"id":"A","text":"An additional field named maxspan is created.","correct":false,"why":""},{"id":"B","text":"An additional field named duration is created.","correct":true,"why":""},{"id":"C","text":"An additional field named eventcount is created.","correct":true,"why":""},{"id":"D","text":"Events with the same JSESSIONID will be grouped together into a single event.","correct":true,"why":""}],"answer":["B","C","D"],"explanation":"• The transaction command creates a single event from a group of events – The events must share the same value in a specified field (D) • The transaction command produces additional fields, such as: – duration – the difference between the timestamps for the first and last event in the transaction (B) – eventcount – the number of events in the transaction (C)","sec":"3.4","secTitle":"Search with transactions","grp":"3","traps":["T-03-03","T-03-01"],"read":["topics/03-correlating-events.md#result-contract"],"verdict":"agree","note":"Option A is the good distractor: maxspan is an input option you supply, never an output field. The Search Reference says transaction \"adds two fields to the raw events, duration and eventcount\", duration being the difference between the timestamps of the first and last events in seconds and eventcount the number of events. Two more fields turn up in real output that the docs describe elsewhere on the same page: closed_txn (0 for evicted, 1 for closed) and _txn_orphan=1 on passthrough results when keeporphans=true. A bare `transaction JSESSIONID` with no other option leaves closed_txn=0 on every result, because closed_txn is only set to 1 when maxevents, maxspan, maxpause or startswith is specified.","courseKey":["B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"Description: \"the transaction command adds two fields to the raw events, duration and eventcount\". keepevicted describes closed_txn and the four options that set it to 1; keeporphans describes _txn_orphan.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/identify-and-group-events-into-transactions","title":"Identify and group events into transactions (Search Manual 10.4)","note":"Transaction search options: transactions consist of the raw text of each event, the shared event types and the field values, plus duration and (when invoked by name from transactiontypes.conf) transactiontype.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-1"],"authored":false},{"id":"t1-q23","type":"single","stem":"Which of the following searches will return events containing a tag named Privileged?","options":[{"id":"A","text":"tag=Priv","correct":false,"why":""},{"id":"B","text":"tag=Priv*","correct":true,"why":""},{"id":"C","text":"tag=priv*","correct":false,"why":""},{"id":"D","text":"tag=privileged","correct":false,"why":""}],"answer":["B"],"explanation":"• Tags are case sensitive • To search for a tag associated with a value:- tag= Ex: tag=privileged • To search for a tag using a partial field value:– Use (*) wildcard tagname in this example has been taken as \"privileged\".","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-12","T-06-02"],"read":["topics/06-tags-and-event-types.md#traps"],"verdict":"disputed","note":"Option B is correct under any reading: `tag=Priv*` matches a tag named Privileged whether or not tag names are case sensitive, and the wildcard is documented (\"You can use the asterisk (*) wildcard when you search keywords and field values, including for eventtypes and tags\"). Option A is false regardless, since `tag=Priv` has no wildcard and does not match Privileged. The dispute is whether C (`tag=priv*`) and D (`tag=privileged`) ALSO match. That turns entirely on tag-name case sensitivity, which the Splunk 10.4 documentation never states: neither About tags and aliases nor Tag field-value pairs in Search says anything about case, in either direction. If tag names are not case sensitive the question has three correct answers and no single key. Note too that the explanation contradicts the stem: the stem names the tag Privileged, the explanation says the tag name \"has been taken as privileged\".","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in Search (Knowledge Manager 10.4)","note":"Search for tagged field values: `tag=<tagname>` and `tag::<field>=<tagname>`; \"Use wildcards to search for tags\" documents the asterisk, e.g. `tag::eventtype=IP-*`. No statement about case anywhere on the page.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/about-tags-and-aliases","title":"About tags and aliases (Knowledge Manager 10.4)","note":"Full tag concept page, example `tag=router tag=SF NOT (tag=Building1)`. Fetched and read in full: it does not mention case sensitivity of tag names.","primary":false}],"difficulty":"hard","issues":["\"Tags are case sensitive\" is not supported by the 10.4 documentation. The tags pages (About tags and aliases, Tag field-value pairs in Search, Define and manage tags in Settings) contain no statement about case in either direction. Treat the claim as unverified until you test it.","The explanation says the tag name \"has been taken as privileged\" (lowercase) while the stem names the tag Privileged (capital P). Under the case-sensitive rule the explanation itself asserts, that swap would change which options are correct."],"block":"disputed","tests":["test-1"],"authored":false},{"id":"t1-q24","type":"single","stem":"What is required for a macro to accept three arguments?","options":[{"id":"A","text":"The macro's name ends with (3).","correct":true,"why":""},{"id":"B","text":"The macro's name starts with (3).","correct":false,"why":""},{"id":"C","text":"The macro's argument count setting is 3 or more.","correct":false,"why":""},{"id":"D","text":"Nothing, all macros can accept any number of arguments.","correct":false,"why":""}],"answer":["A"],"explanation":"Adding Arguments • Include the number of arguments in parentheses after the macro name Ex:- monthly_sales(3) • Within the search definition, use $arg$ - currency=$currency$ - symbol=$symbol$ - rate=$rate$ • In the Arguments field, enter the name of the argument(s) • Provide one or more variables of the macro at search time","sec":"7.3","secTitle":"Define arguments and variables for a macro","grp":"7","traps":["T-07-02","T-07-11","T-07-03"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"agree","note":"Docs step: 'If your search macro includes an argument, append the number of arguments to the name. For example, if your search macro mymacro includes two arguments, name it mymacro(2).' The number in the name is a COUNT, not an index or a version. macros.conf makes the consequence explicit: macros can be overloaded, and [foobar], [foobar(1)] and [foobar(2)] 'are not the same macro'. Option C is a plausible invention: there is no argument-count setting, only args, which is the comma-separated list of argument NAMES, and it is ignored if the stanza name says the macro takes none. Related and also tested: the Arguments field holds bare names with no dollar signs, while the definition references them as $name$.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Manager Manual 10.4)","note":"Naming step: append the number of arguments to the macro name, mymacro(2) for two arguments.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf (Configuration File Reference 10.4)","note":"[<STANZA_NAME>]: stanza name is the macro name appended with '(<numargs>)'; overloaded stanzas with different argument counts are different macros. args is a list of names, not a count.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t1-q25","type":"single","stem":"Which workflow action method can be used when the action type is set to link?","options":[{"id":"A","text":"GET","correct":true,"why":""},{"id":"B","text":"PUT","correct":false,"why":""},{"id":"C","text":"Search","correct":false,"why":""},{"id":"D","text":"UPDATE","correct":false,"why":""}],"answer":["A"],"explanation":"GET and POST action both can use Link. Note: There's no POST within the listed possible answers. So the answer is GET","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-01","T-08-06"],"read":["topics/08-workflow-actions.md#decision-rules"],"verdict":"imprecise","note":"GET is right, and the conf spec settles it: link.method accepts only \"get\" or \"post\", default \"get\". The question is loose because POST, the other valid link method, is not offered, so the answer is reached by elimination rather than by knowing the pair. Keep the two levels straight, because this is exactly the confusion the exam exploits: Action type has two values, link and search. Link method has two values, get and post. Search is a type, never a method, which makes option C a category error rather than a near miss. PUT and UPDATE are not accepted values of any workflow action setting.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"Link type section: \"link.method = <string> ... Accepts: \"get\" or \"post\". Default: \"get\".\" No other verb is accepted.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"\"There are three kinds of workflow actions that you can set up\": GET, POST and Search. Search is a kind of action, not a link method.","primary":false}],"difficulty":"medium","issues":["\"GET and POST action both can use Link\" inverts the relationship. GET and POST are not action types that use link; they are the only two values of the link.method setting, which exists only when type = link. The correct statement is that a link action is issued as either a GET or a POST, chosen by Link method."],"block":null,"tests":["test-1","test-final"],"authored":false},{"id":"t2-q1","type":"multi","stem":"Which of the following statements about tags is true? (Choose all that apply.)","options":[{"id":"A","text":"Tags are case-insensitive.","correct":false,"why":""},{"id":"B","text":"Tags are based on field/value pairs.","correct":true,"why":""},{"id":"C","text":"Tags categorize events based on a search.","correct":false,"why":""},{"id":"D","text":"Tags are designed to make data more understandable.","correct":true,"why":""}],"answer":["B","D"],"explanation":"Tags • A knowledge object that enables you to search for events that contain particular field values • Tags are like labels that you create for related field/value pairs • Tags make your data more understandable and less ambiguous • You can create one or more tags for any field/value combination • Tags are case sensitive","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-01","T-06-12"],"read":["topics/06-tags-and-event-types.md#traps"],"verdict":"disputed","note":"B and D are solid. \"Tags enable you to assign names to specific field and value combinations, including event type, host, source, or source type\" and \"You can apply tags to any field/value pair in an event\" give B; the whole purpose stated on the page, tracking abstract field values like IP addresses or ID numbers by giving them descriptive names, gives D. C is a good distractor because categorizing events based on a search string is what an EVENT TYPE does. The problem is A. Keying \"Tags are case-insensitive\" as false asserts that tag names are case sensitive, and the 10.4 tags pages never state this either way. Same unsourced claim as t1-q23 and t4-q3. If tag names are not case sensitive, A is also correct and the question has three answers.","courseKey":["B","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/about-tags-and-aliases","title":"About tags and aliases (Knowledge Manager 10.4)","note":"Tags assign names to field and value combinations; used to track abstract field values and to group several field values under one searchable name. Tags come last in the search-time operations sequence.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in Search (Knowledge Manager 10.4)","note":"\"You can tag any field-value pair directly from the results of a search\", which is option B stated operationally. No case-sensitivity statement.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-types","title":"About event types (Knowledge Manager 10.4)","note":"Settles option C: categorizing events with a saved search string is the event type mechanism, not the tag mechanism.","primary":false}],"difficulty":"medium","issues":["\"Tags are case sensitive\" is not in the 10.4 documentation. About tags and aliases, Tag field-value pairs in Search and Define and manage tags in Settings say nothing about case. The only ordering statement on the page is unrelated: \"The Splunk software applies tags to field/value pairs in events in ASCII sort order.\""],"block":"disputed","tests":["test-2"],"authored":false},{"id":"t2-q2","type":"multi","stem":"Which of the following statements about macros is true? (Choose all that apply.)","options":[{"id":"A","text":"Arguments are defined at execution time.","correct":false,"why":""},{"id":"B","text":"Arguments are defined when the macro is created.","correct":true,"why":""},{"id":"C","text":"Argument values are used to resolve the search string at execution time.","correct":true,"why":""},{"id":"D","text":"Argument values are used to resolve the search string when the macro is created.","correct":false,"why":""}],"answer":["B","C"],"explanation":"Macros Allows you to define one or more arguments within search segment – Pass argument values to macro at execution time within $ ($arg$) – Macro uses values to resolve search string - Arguments are defined during creation","sec":"7.3","secTitle":"Define arguments and variables for a macro","grp":"7","traps":["T-07-03","T-07-12"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"agree","note":"The distinction is argument NAMES versus argument VALUES. Names are declared in the Arguments field (macros.conf args, a comma-separated list of names) when the macro is created, which kills option A. Values are supplied in the backtick invocation at search time and substituted into the $name$ tokens when the macro expands, which kills option D. Read the course's shorthand 'Pass argument values to macro at execution time within $ ($arg$)' carefully: the dollar signs live only in the DEFINITION. At execution you write `mymacro(value1,value2)`, with the values comma-separated inside the backticks and no dollar signs.","courseKey":["B","C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Manager Manual 10.4)","note":"Arguments are entered at creation time as a comma-delimited string of argument names; the definition references them as tokens with dollar signs, for example $arg1$. Validation checks 'the argument values used to invoke the search macro', which are supplied at invocation.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf (Configuration File Reference 10.4)","note":"args = a comma-separated list of argument names (declared with the macro); definition = 'The string that the macro will expand to, with the argument substitutions made', and invocation is `foobar(arg1,arg2)`.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2"],"authored":false},{"id":"t2-q3","type":"multi","stem":"Information needed to create a GET workflow action includes which of the following? (Choose all that apply.)","options":[{"id":"A","text":"A name for the workflow action.","correct":true,"why":""},{"id":"B","text":"A URI where the user will be directed at search time.","correct":true,"why":""},{"id":"C","text":"A label that will appear in the Event Action menu at search time.","correct":true,"why":""},{"id":"D","text":"A name for the URI where the user will be directed at search time.","correct":false,"why":""}],"answer":["A","B","C"],"explanation":"Creating a GET Workflow Action Settings > Fields > Workflow actions > New Workflow Action 1. Select the app 2. Name the workflow action with no spaces or special characters (A) 3. Define the label, which will appear in the Event Action menu (C) 4. Determine if your workflow action applies to a field or event type 5. From the Show action in dropdown list, select Event menu 6. From Action type dropdown list, select link 7. Enter the URI of where the user will be directed (B) 8. Specify if the link should open in a New window or Current window 9. Select the Link method of get 10. Save","sec":"8.2","secTitle":"Create a GET workflow action","grp":"8","traps":["T-08-10"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"imprecise","note":"All three keyed options are documented requirements. \"If you're creating a new workflow action, you need to give it a Name and identify its Destination app\" covers A, label is required for every type (\"If not set, the Splunk platform skips this workflow action\"), and link.uri is marked \"Required\" in the spec. Option D is word salad: the URI is not given a name. Name and Label are two different fields and the exam leans on that, since Name is the internal object name that becomes the stanza header while Label is the text a searcher actually sees and it accepts $field$ tokens. Destination app is a fourth requirement that this question does not offer. Verdict is imprecise only because of the false naming rule in the explanation.","courseKey":["A","B","C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-get-workflow-action","title":"Set up a GET workflow action (Knowledge Manager Manual 10.4)","note":"\"Define a Label for the action\" and \"In URI provide a URI for the location of the external resource\" are steps 3 and 7 of the documented procedure.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"Define workflow actions using Splunk Web: \"you need to give it a Name and identify its Destination app\", which is the source for option A.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"type and label are listed under \"General required settings\"; link.uri carries an explicit \"* Required\" line. The example stanzas show names containing spaces.","primary":false}],"difficulty":"easy","issues":["\"Name the workflow action with no spaces or special characters\" is not a Splunk rule and no documentation states it. The workflow_actions.conf.example file shipped with Splunk 10.4 defines the stanzas [Create JIRA issue] and [Controller req over time], both containing spaces, so spaces are permitted in a workflow action name."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q4","type":"multi","stem":"Which of the following can be used with the eval command tostring function? (Choose all that apply.)","options":[{"id":"A","text":"\"hex\"","correct":true,"why":""},{"id":"B","text":"\"commas\"","correct":true,"why":""},{"id":"C","text":"\"decimal\"","correct":false,"why":""},{"id":"D","text":"\"duration\"","correct":true,"why":""}],"answer":["A","B","D"],"explanation":"• tostring converts a numeric field value to a string tostring(field,\"option\") • Options: – \"commas\": applies commas – \"duration\": formats the number as \"hh:mm:ss\" – \"hex\": formats the number in hexadecimal","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-19"],"read":["reference/eval-functions.md","topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"imprecise","note":"The key is right: \"decimal\" is not a tostring format, and hex, commas and duration all are. The course explanation is out of date though. The 10.4 format table lists FOUR keywords, not three: \"binary\" (number to its binary representation, for example tostring(9,\"binary\") returns 1001), \"hex\", \"commas\" (rounds to two decimal places when the number has a decimal) and \"duration\" (seconds to HH:MM:SS). If the exam offers \"binary\" as a choice it is correct. Also note the docs' own warning, which is the link to t2-q5: values converted with tostring \"might not sort as expected because they are converted to ASCII\", so use fieldformat with tostring when you only want the display changed. Only integers from 0 to 2^53-1 are accepted, and the format argument is ignored unless the value is a number.","courseKey":["A","B","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/conversion-functions","title":"Conversion functions, tostring (SPL Search Reference 10.4)","note":"tostring(<value>,<format>) format table: \"binary\", \"hex\", \"commas\", \"duration\". No \"decimal\". Also carries the ASCII-sorting warning and the fieldformat recommendation.","primary":true}],"difficulty":"medium","issues":["The explanation presents \"commas\", \"duration\" and \"hex\" as the complete option list. The 10.4 Conversion functions table documents a fourth format, \"binary\", which converts a number to its binary representation. The exhaustive framing is wrong; the three listed are correct."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q5","type":"single","stem":"A user wants to convert numeric field values to strings and also to sort on those values. Which command should be used first, the eval or the sort?","options":[{"id":"A","text":"It doesn't matter whether eval or sort is used first.","correct":false,"why":""},{"id":"B","text":"Convert the numeric to a string with eval first, then sort.","correct":false,"why":""},{"id":"C","text":"Use sort first, then convert the numeric to a string with eval.","correct":true,"why":""},{"id":"D","text":"You cannot use the sort command and the eval command on the same field.","correct":false,"why":""}],"answer":["C"],"explanation":"Formatting and Sorting Values • eval with added characters converts numeric field values to strings • To order numerically, first sort, then use eval Ex- index=web sourcetype=access_combined price=* | stats values(price) as price by product_name | sort -price | eval price = \"$\".price","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-15"],"read":["topics/02-filtering-and-formatting.md#decision-rules"],"verdict":"agree","note":"Sort while the values are still numeric, then format. The Conversion functions page states it outright: values produced by tostring with eval \"might not sort as expected because they are converted to ASCII\", and recommends fieldformat with tostring instead. The sort page explains why: sort auto-detects the collation, using numeric order for numeric fields and lexicographical order otherwise, and lexicographically 10, 9, 70, 100 come out as 10, 100, 70, 9. Prefixing a currency symbol, as in `eval price = \"$\".price`, makes every value start with punctuation, so any later sort is lexicographical. The alternative the course never mentions is fieldformat, which changes only the displayed value and leaves the underlying number sortable no matter the command order.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/conversion-functions","title":"Conversion functions, tostring (SPL Search Reference 10.4)","note":"Usage: tostring values under eval \"might not sort as expected because they are converted to ASCII. Use the fieldformat command with the tostring function to format the displayed values.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/sort","title":"sort command (SPL Search Reference 10.4)","note":"Usage: sort auto-detects numeric, IP or lexicographical collation, and the Lexicographical order section gives 10, 9, 70, 100 sorting as 10, 100, 70, 9.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q6","type":"multi","stem":"Which Knowledge Object does the Splunk Common Information Model (CIM) use to normalize data, in addition to field aliases, event types, and tags?","options":[{"id":"A","text":"Macros","correct":false,"why":""},{"id":"B","text":"Lookups","correct":true,"why":""},{"id":"C","text":"Workflow actions","correct":false,"why":""},{"id":"D","text":"Field extractions","correct":true,"why":""}],"answer":["B","D"],"explanation":"Make your fields CIM-compliant: Normalize your data for each of these fields using a combination of field aliases, field extractions, and lookups. ref: https://docs.splunk.com/Documentation/CIM/4.6.0/User/UsetheCIMtonormalizedataatsearchtime","sec":"10.3","secTitle":"Use the CIM Add-On to normalize data","grp":"10","traps":["T-10-03"],"read":["topics/10-cim.md#syntax-and-options","reference/cim-data-models.md"],"verdict":"imprecise","note":"The two keyed answers are exactly right: step 5 of Use the CIM to normalize data at search time says \"Normalize your data for each of these fields using a combination of field aliases, field extractions, and lookups\", and sub-steps b, c, d are aliases, then extractions, then lookups, in that order. The imprecision is the stem, which says \"Which Knowledge Object\" in the singular and gives no \"choose all that apply\" while marking two options. Option A is a fair distractor in context (macros do not normalize fields) but do not carry away the idea that the add-on ships no macros: it does. The 8.6 docs name `cim_datamodelinfo` and the CIM Filter macros (for example `cim_filter_known_scanners`), which live in the CIM Filters section of $SPLUNK_HOME/etc/apps/Splunk_SA_CIM/default/macros.conf. Note that the earlier claim in this guide about a shipped `cim_<model>_indexes` macro set is not supported by the 8.6 docs: index constraint is now the per-model Indexes allowlist on the CIM Setup page (datamodels.conf), not a macro.","courseKey":["B","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-to-normalize-data-at-search-time","title":"Use the CIM to normalize data at search time (CIM 8.6)","note":"Step 5: \"Normalize your data for each of these fields using a combination of field aliases, field extractions, and lookups.\" Sub-steps b/c/d give the alias, extraction, lookup order; step 3 covers the CIM-compliant event tags the stem already grants.","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-filters-to-exclude-data","title":"Use the CIM Filters to exclude data (CIM 8.6)","note":"Proof that the add-on does ship search macros: the CIM Filter macros \"are available by default and located in the CIM Filters section of the $SPLUNK_HOME/etc/apps/Splunk_SA_CIM/default/macros.conf file\". They exclude data, they do not normalize it, which is why option A is keyed false here.","primary":false}],"difficulty":"hard","issues":["The explanation cites CIM 4.6.0 (docs.splunk.com/Documentation/CIM/4.6.0/User/UsetheCIMtonormalizedataatsearchtime). Current CIM is 8.6 and the equivalent page is help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-to-normalize-data-at-search-time. The old link redirects rather than 404s, but the content it points at is many major versions behind."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q7","type":"multi","stem":"Which of the following statements describe data model acceleration? (Choose all that apply.)","options":[{"id":"A","text":"Root events cannot be accelerated.","correct":false,"why":""},{"id":"B","text":"Accelerated data models cannot be edited.","correct":true,"why":""},{"id":"C","text":"Private data models cannot be accelerated.","correct":true,"why":""},{"id":"D","text":"You must have administrative permissions or the accelerate_datamodel capability to accelerate a data model.","correct":true,"why":""}],"answer":["B","C","D"],"explanation":"Data Model Acceleration • Uses automatically created summaries to speed completion times for pivots • Only root events can be accelerated. If there are multiple root events, only the first root event is accelerated. • Private data models cannot be accelerated • Accelerated data models cannot be edited • You must have administrative permissions or the accelerate_datamodel capability to accelerate a data model","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-09-04","T-09-14","T-09-13"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"imprecise","note":"The three keyed answers are all documented. Manage data models: \"After you accelerate a data model, you cannot edit it\" (B); Accelerate data models: \"You can only accelerate data models that you have shared to all users of an app or shared globally ... You cannot accelerate data models that are private\" (C); the acceleration prerequisite is \"A role with the accelerate_datamodel capability, such as the admin role\" (D). Option A is false: root event datasets are exactly what CAN be accelerated. The overall explanation, however, adds two claims the docs do not support, see below.","courseKey":["B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-data-summaries-to-accelerate-searches/accelerate-data-models","title":"Accelerate data models (Knowledge Manager Manual 10.4)","note":"\"Data model acceleration limitations\" gives the root event / streaming root search rule; the same page states private data models cannot be accelerated.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/manage-data-models","title":"Manage data models (Knowledge Manager Manual 10.4)","note":"\"Enable data model acceleration\" caveats: an accelerated model cannot be edited, acceleration applies only to root event and streaming root search datasets and their children, and the prerequisite is the accelerate_datamodel capability.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"\"Dataset types and data model acceleration\": a model needs at least one root event dataset or one streaming-only root search dataset, and \"Data models can contain a mixture of accelerated and unaccelerated datasets.\"","primary":false}],"difficulty":"medium","issues":["\"Only root events can be accelerated\" is incomplete. Accelerate data models: \"Datasets can be accelerated only if they contain at least one root event hierarchy or one root search hierarchy that only includes streaming commands.\" Child datasets of those roots are accelerated too. What is never accelerated is root transaction datasets and root search datasets that use nonstreaming commands.","\"If there are multiple root events, only the first root event is accelerated\" appears nowhere in the 10.4 docs and is contradicted by the capacity-planning section of Accelerate data models, which explains that for a model with multiple root objects the Size on Disk metric under-reports \"because it accounts for only one root object\" while the actual summary covers the whole model. Do not memorise the first-root-only sentence."],"block":null,"tests":["test-2"],"authored":false},{"id":"t2-q8","type":"single","stem":"How does a user display a chart in stack mode?","options":[{"id":"A","text":"By using the stack command.","correct":false,"why":""},{"id":"B","text":"By turning on the Use Trellis Layout option.","correct":false,"why":""},{"id":"C","text":"By changing Stack Mode in the Format menu.","correct":true,"why":""},{"id":"D","text":"You cannot display a chart in stack mode, only a timechart.","correct":false,"why":""}],"answer":["C"],"explanation":"","sec":null,"secTitle":null,"grp":null,"traps":["T-01-14"],"read":["topics/01-transforming-commands.md#result-contract"],"verdict":"agree","note":"Off blueprint, but the key is confirmed. The column and bar chart docs say \"To show multiple series in a bar or column chart, use the Format menu to configure stacking and multi-series mode\" and list three Stack options: Unstacked, Stacked, Stacked 100%. Section 1.0 covers the chart and timechart COMMANDS, not the visualization Format menu, and there is no dashboards or visualizations section on SPLK-1002. Worth thirty seconds only: stacking is a formatting option applied after the search, there is no `stack` command, D is false because column, bar and area charts all stack, and Trellis splits one visualization into small multiples rather than stacking series.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/create-dashboards-and-reports/simple-xml-dashboards/10.4/charts/column-and-bar-charts","title":"Column and bar charts (Simple XML Dashboards 10.4)","note":"\"Stacked charts\" section: use the Format menu to configure stacking; the three Stack options are Unstacked, Stacked and Stacked 100%.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/create-dashboards-and-reports/simple-xml-dashboards/10.4/charts/chart-overview","title":"Chart overview (Simple XML Dashboards 10.4)","note":"Chart type table, useful for placing stacking as a column and bar chart formatting choice rather than an SPL command.","primary":false}],"difficulty":"easy","issues":[],"block":"off-blueprint","tests":["test-2"],"authored":false},{"id":"t2-q9","type":"single","stem":"If no value is specified with the fillnull command, what default value will be used?","options":[{"id":"A","text":"0","correct":true,"why":""},{"id":"B","text":"N/A","correct":false,"why":""},{"id":"C","text":"ג€\"","correct":false,"why":""},{"id":"D","text":"NULL","correct":false,"why":""}],"answer":["A"],"explanation":"fillnull Command • Use fillnull to replace null values in fields • Use value=string to specify a string you want displayed instead Example: fillnull value=NULL • If no value= clause, default replacement value is 0","sec":"2.3","secTitle":"The fillnull command","grp":"2","traps":["T-02-11","T-02-13"],"read":["topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"agree","note":"Documented twice on the fillnull page: the Description says you can \"use the default, field value which is zero (0)\", and the value argument carries \"Default: 0\". Option C is mojibake in the course, a mis-encoded dash. Objective 2.3 is a named blueprint bullet the Udemy video course skips, so lock this in. Two extras from the same page. With no field-list, fillnull applies to every field and is a dataset processing command; with a field-list it is distributable streaming, and a named field that did not previously exist is created. And a field with no non-null value anywhere in the result set does not exist in the schema at all, so fillnull cannot touch it. Contrast filldown, which copies the last non-null value forward rather than writing a constant.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/fillnull","title":"fillnull command (SPL Search Reference 10.4)","note":"value argument: \"Specify a string value to replace null values. If you do not specify a value, the default value is applied\", Default: 0. Usage covers the field-list versus no-field-list command type split.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q10","type":"single","stem":"What other syntax will produce exactly the same results as | chart count over vendor_action by user?","options":[{"id":"A","text":"| chart count by vendor_action, user","correct":true,"why":""},{"id":"B","text":"| chart count over vendor_action, user","correct":false,"why":""},{"id":"C","text":"| chart count by vendor_action over user","correct":false,"why":""},{"id":"D","text":"| chart count over user by vendor_action","correct":false,"why":""}],"answer":["A"],"explanation":"• You can use the by clause with the over clause to split results (over vendor_action by user) • Alternatively, you can just use two by clauses (by vendor_action, user)","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-03","T-01-10"],"read":["topics/01-transforming-commands.md#syntax-and-options","reference/stats-and-chart-functions.md"],"verdict":"imprecise","note":"Keyed answer is right. The chart syntax line settles it: `[ BY <row-split> <column-split> ] | [ OVER <row-split> ] [BY <column-split>]`. So `OVER x BY y` and `BY x y` are the same thing, first field becomes the rows, second becomes the columns. Option D is the sharpest distractor because swapping the two transposes the table, a different result rather than a formatting difference. B and C are simply not grammatical: OVER takes exactly one row-split field, and it cannot follow BY.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (Search Reference 10.4)","note":"Syntax block, plus row-split and column-split argument definitions: row-split becomes the first column and the X-axis label, column-split becomes the data series columns. Basic example 2 is `... | chart max(delay) OVER site BY org`.","primary":true}],"difficulty":"hard","issues":["The explanation says \"you can just use two by clauses (by vendor_action, user)\". There is no such thing as two BY clauses. It is ONE BY clause listing two fields, documented as `BY <row-split> <column-split>`. The wording matters because the same test set elsewhere keys the fact that timechart permits only one BY clause; calling a two-field BY \"two by clauses\" teaches the opposite. The docs' own examples write the two fields without a comma (`... | chart eval(avg(size)/max(delay)) AS ratio BY host user`), though the comma form parses identically."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q11","type":"single","stem":"What are the two parts of a root event dataset?","options":[{"id":"A","text":"Fields and variables.","correct":false,"why":""},{"id":"B","text":"Fields and attributes.","correct":false,"why":""},{"id":"C","text":"Constraints and fields.","correct":true,"why":""},{"id":"D","text":"Constraints and lookups.","correct":false,"why":""}],"answer":["C"],"explanation":"You can create datasets for your data model by define their constraints and fields. • Event datasets contain constraints and fields • Constraints are essentially the search broken down into a hierarchy. • Fields are properties associated with the events","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-08"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"agree","note":"Option B is the trap: attribute is a synonym for field in data model vocabulary, so \"fields and attributes\" names the same thing twice. About data models: \"Data model datasets are defined by characteristics that mostly break down into constraints and fields.\" Design data models: in the Data Model Editor \"you can create datasets for your data model, define their constraints and fields\". A root event dataset's constraint is a simple search with no pipes or commands.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"Datasets and \"Dataset constraints\" sections: datasets are defined by constraints and fields; a root event dataset constraint is a simple search such as sourcetype=access_*.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/design-data-models","title":"Design data models (Knowledge Manager Manual 10.4)","note":"\"Add a root event dataset to a data model\": you give it a Dataset Name, Dataset ID and one or more Constraints, then define its fields.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q12","type":"single","stem":"When using timechart, how many fields can be listed after a by clause?","options":[{"id":"A","text":"0, because timechart doesn't support using a by clause.","correct":false,"why":""},{"id":"B","text":"1, because _time is already implied as the x-axis.","correct":true,"why":""},{"id":"C","text":"2, because one field would represent the x-axis and the other would represent the y-axis.","correct":false,"why":""},{"id":"D","text":"There is no limit specific to timechart","correct":false,"why":""}],"answer":["B"],"explanation":"A timechart is a statistical aggregation applied to a field to produce a chart, with time used as the X-axis • timechart command performs statistical aggregations against time. • Plots and trends data over time. • _time is always the x-axis • You can optionally split data using the by clause for one other field [Ans] - Each distinct value of the split by field is a separate series in the chart","sec":"1.2","secTitle":"Use the timechart command","grp":"1","traps":["T-01-02"],"read":["topics/01-transforming-commands.md#result-contract"],"verdict":"agree","note":"Stated verbatim in the timechart stats-func description: \"Each time you invoke the timechart command, you can use one or more functions. However, you can only use one BY clause.\" The reason in option B is the whole point: rows are already spent on _time, so the single BY field has to become the columns, one series per distinct value. `chart` takes two because it has both axes free.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/timechart","title":"timechart command (Search Reference 10.4)","note":"Optional arguments, <stats-func>: \"you can only use one BY clause\". Description: each distinct value of the split-by field becomes a series in the chart.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q13","type":"single","stem":"A field alias has been created based on an original field. A search without any transforming commands is then executed in Smart Mode. Which field name appears in the results?","options":[{"id":"A","text":"Both will appear in the All Fields list, but only if the alias is specified in the search.","correct":false,"why":""},{"id":"B","text":"Both will appear in the Interesting Fields list, but only if they appear in at least 20 percent of events.","correct":true,"why":""},{"id":"C","text":"The original field only appears in All Fields list and the alias only appears in the Interesting Fields list.","correct":false,"why":""},{"id":"D","text":"The alias only appears in the All Fields list and the original field only appears in the Interesting Fields list.","correct":false,"why":""}],"answer":["B"],"explanation":"Field Aliases • A way to normalize data over any default field (host, source or sourcetype) • When you create a field alias, the original field is not affected • Both fields appear in the All Fields and Interesting Fields lists, if they appear in at least 20% of events","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-01","T-04-07"],"read":["topics/05-aliases-and-calculated-fields.md#result-contract","topics/00-foundations-refresher.md"],"verdict":"imprecise","note":"The key is right. Two facts stacked in one question. An alias ADDS a name and never removes the original, documented as \"An alias does not replace or remove the original field name\", so both fields exist in the results. And the 20 percent threshold governs the Interesting Fields list only: the Search Tutorial says \"Interesting Fields are fields that appear in at least 20% of the events\", while All Fields opens the Select Fields dialog listing every field in the events regardless of frequency. Option A fails because both names are present whether or not the alias is typed into the search.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/create-field-aliases-in-splunk-web","title":"Create field aliases in Splunk Web (Knowledge Manager Manual 10.4)","note":"\"A field can have multiple aliases, but a single alias can only apply to one field... An alias does not replace or remove the original field name.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-tutorial/10.4/part-4-searching-the-tutorial-data/use-fields-to-search","title":"Use fields to search (Search Tutorial 10.4)","note":"Fields sidebar section: \"Interesting Fields are fields that appear in at least 20% of the events\", and the All Fields / Select Fields dialog listing every field with a # of Values column.","primary":false}],"difficulty":"hard","issues":["\"Both fields appear in the All Fields and Interesting Fields lists, if they appear in at least 20% of events\" attaches the 20 percent condition to both lists. The threshold applies to Interesting Fields only. All Fields shows every field extracted from the events regardless of how often it appears, which is exactly the distinction the keyed option B relies on."],"block":null,"tests":["test-2"],"authored":false},{"id":"t2-q14","type":"single","stem":"Which of the following statements describes macros?","options":[{"id":"A","text":"A macro is a reusable search string that must contain the full search.","correct":false,"why":""},{"id":"B","text":"A macro is a reusable search string that must have a fixed time range.","correct":false,"why":""},{"id":"C","text":"A macro is a reusable search string that may have a flexible time range.","correct":true,"why":""},{"id":"D","text":"A macro is a reusable search string that must contain only a portion of the search.","correct":false,"why":""}],"answer":["C"],"explanation":"Macros Overview: • Useful when you frequently run searches or reports with similar search syntax • The time range is selected at search time [Flexible time range] • Macros can be a full search string or a portion of a search that can be reused in multiple places • Allows you to define one or more arguments within search segment – Pass parameter values to macro at execution time – Macro uses values to resolve search string","sec":"7.1","secTitle":"Describe macros","grp":"7","traps":["T-07-11"],"read":["topics/07-macros.md#what-it-is"],"verdict":"imprecise","note":"C is the only survivable option, but it survives by elimination rather than by matching the docs. Options A and D are mirror-image traps, each asserting a 'must' that the docs contradict directly: 'Search macros can be any part of a search, such as an eval statement or search term, and do not need to be a complete command', and they may equally be a whole search. Option B is false because nothing binds a macro to a fixed time range. The phrase 'flexible time range' in option C is Splunk courseware wording, not documentation wording: the 10.4 macro pages say nothing about time ranges, the point being that the time picker is set at search time unless the definition itself contains earliest or latest modifiers. Do not memorise 'flexible time range' as a documented property; memorise that a macro can be any fragment of SPL or an entire search.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros","title":"Use search macros in searches (Knowledge Manager Manual 10.4)","note":"Opening definition: reusable chunks of SPL, can be any part of a search such as an eval statement or search term, and do not need to be a complete command. Kills the 'must' in options A and D.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Manager Manual 10.4)","note":"Same scope statement plus 'Design a search macro definition'. No time-range requirement is stated anywhere on the page.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q15","type":"single","stem":"In what order are the following knowledge objects/configurations applied?","options":[{"id":"A","text":"Field Aliases, Field Extractions, Lookups","correct":false,"why":""},{"id":"B","text":"Field Extractions, Field Aliases, Lookups","correct":true,"why":""},{"id":"C","text":"Field Extractions, Lookups, Field Aliases","correct":false,"why":""},{"id":"D","text":"Lookups, Field Aliases, Field Extractions","correct":false,"why":""}],"answer":["B"],"explanation":"Field Aliases • A way to normalize data over any default field (host, source or sourcetype) • Multiple aliases can be applied to one field • Applied after field extractions, before lookups","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-KO-01","T-KO-02"],"read":["reference/knowledge-object-precedence.md"],"verdict":"agree","note":"The highest-yield idea on the exam, asked in its simplest form, and confirmed twice in the docs: \"Perform field aliasing after key-value extraction but before field lookups so that you can specify a lookup table based on a field alias.\" The full documented sequence is nine operations, not three: field filters, inline extraction (EXTRACT-), transform extraction (REPORT-), automatic key-value extraction (KV_MODE), field aliasing (FIELDALIAS-), calculated fields (EVAL-), lookups (LOOKUP-), event types, tags. Calculated fields sit between aliases and lookups, which is the gap this question leaves out and other questions exploit. The explanation's other two bullets check out: a field can have multiple aliases, though a single alias can only apply to one field.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Manager Manual 10.4)","note":"Numbered table: 1 field filters, 2 EXTRACT-, 3 REPORT-, 4 KV_MODE, 5 FIELDALIAS-, 6 EVAL-, 7 LOOKUP-, 8 event types, 9 tags.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/configure-field-aliases-with-props.conf","title":"Configure field aliases with props.conf (Knowledge Manager Manual 10.4)","note":"\"Perform field aliasing after key-value extraction but before field lookups so that you can specify a lookup table based on a field alias.\" Also \"A field can have multiple aliases, but a single alias can only apply to one field.\"","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q16","type":"single","stem":"In which of the following scenarios is an event type more effective than a saved search?","options":[{"id":"A","text":"When a search should always include the same time range.","correct":false,"why":""},{"id":"B","text":"When a search needs to be added to other users' dashboards.","correct":false,"why":""},{"id":"C","text":"When the search string needs to be used in future searches.","correct":true,"why":""},{"id":"D","text":"When formatting needs to be included with the search string.","correct":false,"why":""}],"answer":["C"],"explanation":"Event Types vs. Saved Search • Event Types – Categorize events based on a search string – Tag event types to organize data into categories – The eventtype field can be included in a search string – Does not include a time range • Saved Search – Search criteria will not change – Includes a time range and formatting of the results – Can be shared with Splunk users and added to dashboards For more info: An event type represents a search that returns a specific type of event or a useful collection of events. Every event that can be returned by that search gets an association with that event type. For example, say you have this search: sourcetype=access_combined status=200 action=purchase. If you save that search as an event type named successful_purchase, any event that could be returned by that search gets eventtype=successful_purchase added to it at search time. And later, if you want to build a search that works with events that match that event type, include eventtype=successful_purchase in the search string.","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-08"],"read":["topics/06-tags-and-event-types.md#decision-rules"],"verdict":"agree","note":"The discriminator is that an event type becomes a searchable field value and carries no time range, so you can drop `eventtype=name` into any future search: \"To build a search that works with events that match that event type, include eventtype=successful_purchase as a search term.\" An event type definition holds only a search string plus optional description, priority, colour and tags (eventtypes.conf syntax table), with nothing for a time range or result formatting, which is what options A, B and D each describe and what a saved search or report gives you instead.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-types","title":"About event types (Knowledge Manager 10.4)","note":"How event types work: eventtype=<name> is added at search time \"even if you are searching for something completely different\", and is then usable as a search term. A single event can match several event types, so eventtype acts as a multivalue field.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/define-event-types-in-splunk-web","title":"Define event types in Splunk Web (Knowledge Manager 10.4)","note":"The Save As Event Type dialog collects Name, Tag(s), Color and Priority only. No time range and no result formatting are part of an event type.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q17","type":"single","stem":"When using the transaction command, what does the argument maxspan do?","options":[{"id":"A","text":"Sets the maximum total time between events in a transaction.","correct":false,"why":""},{"id":"B","text":"Sets the maximum length of all the events within a transaction.","correct":false,"why":""},{"id":"C","text":"Sets the maximum total time between the earliest and latest events in a transaction.","correct":true,"why":""},{"id":"D","text":"Sets the maximum length that any single event can reach to be included in the transaction.","correct":false,"why":""}],"answer":["C"],"explanation":"transaction Command • You can also define a max overall time span between events - maxspan=10m ▸ Maximum total time between the earliest and latest events ▸ If not specified, default is -1 (or no limit Note- Assumptions: Transactions spanning more than 10 minutes with the same client IP are considered unrelated. Also, there can be no more than one minute between any two related events. Ex- index=web sourcetype=access_combined | transaction clientip maxspan=10m","sec":"3.3","secTitle":"Group events using fields and time","grp":"3","traps":["T-03-01"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"agree","note":"Option C is the docs' own wording almost verbatim: maxspan specifies \"the maximum total time between the earliest and latest events in a transaction\". Option A is maxpause, the pause between two CONSECUTIVE events. Both default to -1, which deactivates the constraint, and both can apply at once. Options B and D are pure noise, since neither option measures the byte length or line length of an event. This maxspan versus maxpause pair is one of the most reliably asked distinctions in section 3.0. One operational detail the course omits: events must already be in descending chronological order before maxspan or maxpause is applied, so a preceding eval or similar needs `| sort -_time` immediately before transaction.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"maxspan: \"the maximum total time between the earliest and latest events in a transaction ... If the value is negative, the maxspan constraint is deactivated\", Default: -1. maxpause: pause \"between consecutive events\", Default: -1. Also the descending chronological order requirement.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q18","type":"single","stem":"When creating a Search workflow action, which field is required?","options":[{"id":"A","text":"Search string","correct":true,"why":""},{"id":"B","text":"Data model name","correct":false,"why":""},{"id":"C","text":"Permission setting","correct":false,"why":""},{"id":"D","text":"An eval statement","correct":false,"why":""}],"answer":["A"],"explanation":"Creating a Search Workflow Action Settings > Fields > Workflow actions> New 1. Select the app 2. Name the workflow action with no spaces or special characters 3. Define the label, which will appear in the Event Action menu 4. Determine if your workflow action applies to a field or event type 5. From the Show action in dropdown list, select Event menu 6. From the Action type dropdown list, select search 7. Enter the Search string (A) 8. Select the app if it is different from the current app 9. Enter the view name where the search will execute 10. Indicate if the search should run in a New window or the Current window 11. Enter the time range for the search or choose to use the same time range as the search 12. Save","sec":"8.4","secTitle":"Create a Search workflow action","grp":"8","traps":["T-08-14"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"imprecise","note":"Search string is the field that only the search type has and that the search type cannot work without: \"In Search string enter a search string that includes one or more placeholders for field values, bounded by dollar signs.\" Everything else on the search half of the form falls back to a default. Omit the app and the view and the search runs in the current app and current view, and if Earliest time and Latest time are left blank \"the search runs over all time by default\". Data model name and eval statement are not workflow action settings at all, and permissions are set after the object exists, not on the creation form. Verdict is imprecise only because of the false naming rule in the explanation; the key is right.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-search-workflow-action","title":"Set up a search workflow action (Knowledge Manager Manual 10.4)","note":"Setting Action type to search \"reveals a set of Search configuration fields\"; Search string is the first and is the only one with no fallback.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"Search type section: search.search_string is the search to construct; search.app and search.view both default to the current app and current view.","primary":false}],"difficulty":"easy","issues":["\"Name the workflow action with no spaces or special characters\" is not a Splunk rule and no documentation states it. The workflow_actions.conf.example file shipped with Splunk 10.4 defines the stanzas [Create JIRA issue] and [Controller req over time], both containing spaces.","Steps 8 and 9 present the app and the view as things you must enter. The docs make both optional: \"Identify the app that the search runs in. If you want it to run in a view other than the current one, select that view\", and the spec defaults search.app to the current app and search.view to the current view."],"block":null,"tests":["test-2"],"authored":false},{"id":"t2-q19","type":"single","stem":"To identify all of the contributing events within a transaction that contain at least one REJECT event, which syntax is correct?","options":[{"id":"A","text":"index=main REJECT | transaction sessionid","correct":false,"why":""},{"id":"B","text":"index=main | transaction sessionid | search REJECT","correct":true,"why":""},{"id":"C","text":"index=main | transaction sessionid | where transaction=reject","correct":false,"why":""},{"id":"D","text":"index=main | transaction sessionid | where transaction=\"REJECT*","correct":false,"why":""}],"answer":["B"],"explanation":"By creating a transaction, you can then search and see additional events related to the rejection.","sec":"3.4","secTitle":"Search with transactions","grp":"3","traps":["T-03-10","T-02-18"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"agree","note":"Option A is the instructive wrong answer: filtering on REJECT before the transaction discards every other event in the session, so you get one-event transactions instead of the whole session. Group first, filter after. The filter in B works because a transaction is \"made up of the raw text (the _raw field) of each member\", so `search REJECT` matches the text contributed by any member event. Options C and D invent a field called transaction, which the command never creates (and D is also missing a closing quote). The docs model the same shape with `| transaction ... | where duration>0`, noting the filter cannot be applied before transaction because the field does not exist yet.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"Description: \"Transactions are made up of the raw text (the _raw field) of each member, the time and date fields of the earliest member, as well as the union of all other fields of each member.\" The output fields are duration and eventcount, never a field named transaction.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Transaction search example pipes transactions into a post-transaction filter and states the filter \"cannot be applied before the transaction command\" because the field is added by transaction.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q20","type":"single","stem":"Which workflow uses field values to perform a secondary search?","options":[{"id":"A","text":"POST","correct":false,"why":""},{"id":"B","text":"Action","correct":false,"why":""},{"id":"C","text":"Search","correct":true,"why":""},{"id":"D","text":"Sub-search","correct":false,"why":""}],"answer":["C"],"explanation":"• Execute workflow actions from an event in your search results to interact with external resources or run another search – GET - retrieve information from an external resource – POST - send field values to an external resource – Search - use field values to perform a secondary search","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-01"],"read":["topics/08-workflow-actions.md#decision-rules"],"verdict":"agree","note":"Straight from the docs: \"Search workflow actions launch secondary searches that use specific field values from an event, such as a search that looks for the occurrence of specific combinations of ipaddress and http_status field values in your index over a specific time range.\" The three-way split to memorise is GET retrieves from an external resource, POST sends field values to an external resource, Search runs a secondary Splunk search. Option D is a real Splunk concept but an unrelated one, since a subsearch is SPL in square brackets evaluated inside one search job, not a user-clicked menu entry. Option B, \"Action\", is not a type at all.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"The three kinds table defines GET, POST and Search workflow actions in one place; Search \"launch[es] secondary searches that use specific field values from an event\".","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-search-workflow-action","title":"Set up a search workflow action (Knowledge Manager Manual 10.4)","note":"Shows the field-value placeholder syntax, for example clientip=$clientip$, that makes the secondary search dynamic.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q21","type":"single","stem":"Which of the following statements describes field aliases?","options":[{"id":"A","text":"Field alias names replace the original field name.","correct":false,"why":""},{"id":"B","text":"Field aliases can be used in lookup file definitions.","correct":true,"why":""},{"id":"C","text":"Field aliases only normalize data across sources and sourcetypes.","correct":false,"why":""},{"id":"D","text":"Field alias names are not case sensitive when used as part of a search.","correct":false,"why":""}],"answer":["B"],"explanation":"Field Aliases • A way to normalize data over any default field (host, source or sourcetype) • Multiple aliases can be applied to one field • Applied after field extractions, before lookups • Can be referenced by a lookup • When you create a field alias, the original field is not affected • Both fields appear in the All Fields and Interesting Fields lists, if they appear in at least 20% of events • Fiels aliases are also case sensitive as field names are case sensitive.","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-01","T-05-11","T-KO-09"],"read":["reference/knowledge-object-precedence.md","topics/05-aliases-and-calculated-fields.md#decision-rules"],"verdict":"imprecise","note":"The key is right. Option B is true because of ordering, stated outright in the docs: \"Perform field aliasing after key-value extraction but before field lookups so that you can specify a lookup table based on a field alias\", and the Splunk Web page repeats it as \"you can design a lookup table that is based on a field alias\". Option A is false: \"An alias does not replace or remove the original field name.\" Option C is false because the scope is host, source AND sourcetype, three choices not two, per the Splunk Web step \"Select the host, source, or sourcetype to apply to a default field\". Option D is false because an alias name is a FIELD NAME, and the Search Tutorial states \"Field names are case sensitive, but field values are not\". That is the opposite side of the tag question in t1-q23 and t2-q1. Marked imprecise only for the All Fields bullet in the explanation.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/configure-field-aliases-with-props.conf","title":"Configure field aliases with props.conf (Knowledge Manager Manual 10.4)","note":"Settles B and A in two sentences: aliasing runs before lookups \"so that you can specify a lookup table based on a field alias\", and \"An alias does not replace or remove the original field name.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/create-field-aliases-in-splunk-web","title":"Create field aliases in Splunk Web (Knowledge Manager Manual 10.4)","note":"Steps: \"(Required) Select the host, source, or sourcetype to apply to a default field\", which is why option C's \"sources and sourcetypes\" only is false.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-tutorial/10.4/part-4-searching-the-tutorial-data/use-fields-to-search","title":"Use fields to search (Search Tutorial 10.4)","note":"Search with fields section: \"Field names are case sensitive, but field values are not.\" This kills option D.","primary":false}],"difficulty":"hard","issues":["\"Both fields appear in the All Fields and Interesting Fields lists, if they appear in at least 20% of events\" applies the 20 percent threshold to both lists. It governs Interesting Fields only; All Fields lists every field found in the events regardless of frequency."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q22","type":"single","stem":"Which statement is true?","options":[{"id":"A","text":"Pivot is used for creating datasets.","correct":false,"why":""},{"id":"B","text":"Data models are randomly structured datasets.","correct":false,"why":""},{"id":"C","text":"Pivot is used for creating reports and dashboards.","correct":true,"why":""},{"id":"D","text":"In most cases, each Splunk user will create their own data model.","correct":false,"why":""}],"answer":["C"],"explanation":"• Data models are hierarchically structured datasets that generate searches and drive Pivot. • Pivot reports are created based on datasets • Pivot are used for creating reports and dashboards (C) • As a knowledge manager, you’re responsible for building the data model that provides the datasets for Pivot","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-01"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"agree","note":"Option B fails on one word: a data model is \"a hierarchically structured search-time mapping of semantic knowledge\", not randomly structured. Option A inverts the relationship, which is the single most repeated error in this material and is keyed backwards in the Apress book: datasets come from the data model, Pivot consumes them. Option C is stated directly in the Pivot Manual: \"The pivots that you create can be saved as reports or dashboard panels.\" Option D is wrong because knowledge managers, not individual users, design data models.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"Pivots are saved as reports or dashboard panels; data models and datasets are designed by knowledge managers.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"\"What is a data model?\": hierarchically structured search-time mapping, composed of datasets arranged in parent/child hierarchies.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q23","type":"single","stem":"Which of the following statements describes the use of the Field Extractor (FX)?","options":[{"id":"A","text":"The Field Extractor automatically extracts all fields at search time.","correct":false,"why":""},{"id":"B","text":"The Field Extractor uses PERL to extract fields from the raw events.","correct":false,"why":""},{"id":"C","text":"Fields extracted using the Field Extractor persist as knowledge objects.","correct":true,"why":""},{"id":"D","text":"Fields extracted using the Field Extractor do not persist and must be defined for each search.","correct":false,"why":""}],"answer":["C"],"explanation":"• In addition to the many fields Splunk auto-extracts, you can also extract your own fields with the Field Extractor (FX) • Use FX to extract fields that are static and that you use often in searches - Graphical UI - Extract fields from events using regex or delimiter - Extracted fields persist as knowledge objects(C) - Can be shared and re-used in multiple searches","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-02"],"read":["topics/04-field-extractions.md#what-it-is"],"verdict":"imprecise","note":"The keyed answer is right: an FX extraction is saved as a named knowledge object with permissions, listed on Settings > Field Extractions, and reusable across searches. Option D describes rex, which is search-scoped and does not persist, and option A describes automatic key-value extraction rather than the FX, which is a manual guided tool. Option B is the sloppy one: Splunk regular expressions ARE PCRE, Perl Compatible Regular Expressions, using the PCRE C library, so \"uses PERL\" is wrong only on the technicality that PCRE is a C library rather than the Perl language. Note also that a new extraction is initially set to Owner, so it persists but is private until you share it.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-save-step","title":"Field Extractor: Save step (Knowledge Manager 10.4)","note":"\"In the Save step of the field extractor you define the name of the new field extraction definition, set its permissions, and save the extraction.\" Saved extractions are listed on the Field Extractions page in Settings, and default to Owner.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/about-splunk-regular-expressions","title":"About Splunk regular expressions (Knowledge Manager 10.4)","note":"\"Splunk regular expressions are PCRE (Perl Compatible Regular Expressions) and use the PCRE C library.\" This is why option B is only technically false.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/manage-knowledge-object-permissions","title":"Manage knowledge object permissions (Knowledge Manager 10.4)","note":"Knowledge objects persist with owner, app and sharing settings; a newly created object \"is only available to that user\" until shared.","primary":false}],"difficulty":"medium","issues":["The explanation says extracted fields \"can be shared and re-used in multiple searches\" without noting the default. The Save step docs state the extraction is set to Owner on creation, \"meaning that it only extracts fields in searches run by the person who created the extraction\"; sharing to App or All apps is a separate, explicit step and requires the capability to change permissions."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t2-q24","type":"single","stem":"Which of the following searches would return a report of sales by product_name?","options":[{"id":"A","text":"chart sales by product_name","correct":false,"why":""},{"id":"B","text":"chart sum(price) as sales by product_name","correct":true,"why":""},{"id":"C","text":"stats sum(price) as sales over product_name","correct":false,"why":""},{"id":"D","text":"timechart list(sales), values(product_name)","correct":false,"why":""}],"answer":["B"],"explanation":"Learner can try this in a Splunk practice lab. You can download trail version of Splunk from https://www.splunk.com/en_us/download. Download lab practice data from below link: https://docs.splunk.com/Documentation/Splunk/9.0.1/SearchTutorial/Systemrequirements#Download_the_tutorial_data_files Download the tutorialdata.zip file. Do not uncompress the file. Download the Prices.csv.zip file. Do not uncompress the file at this time","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-10"],"read":["topics/01-transforming-commands.md#syntax-and-options"],"verdict":"imprecise","note":"The keyed answer is right but the overall explanation explains nothing, it just tells you to download Splunk. The actual reasoning, all documented: A fails because the chart docs state \"You must specify a statistical function when you use the chart command\", so a bare field name is not a valid stats-agg-term. C fails because the stats syntax offers only a BY clause, OVER belongs to chart. D is a time series over the wrong fields entirely, and `list(sales)` would not aggregate price by product.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (Search Reference 10.4)","note":"Description: \"You must specify a statistical function when you use the chart command.\" Required arguments require a stats-agg-term such as sum(price) AS sales.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/stats","title":"stats command (Search Reference 10.4)","note":"Syntax and by-clause: stats accepts only `BY <field-list>`. There is no OVER keyword, which is what kills option C.","primary":false}],"difficulty":"medium","issues":["The overallExplanation gives no reason for the answer at all; it is download instructions for the Search Tutorial dataset, pointed at the 9.0.1 docs rather than current. It should say why the three distractors fail: chart requires a statistical function (docs: \"You must specify a statistical function when you use the chart command\"), and stats has no OVER clause, only `BY <field-list>`."],"block":null,"tests":["test-2"],"authored":false},{"id":"t2-q25","type":"multi","stem":"Which of the following data models are included in the Splunk Common Information Model (CIM) add-on? (Choose all that apply.)","options":[{"id":"A","text":"Alerts","correct":true,"why":""},{"id":"B","text":"Email","correct":true,"why":""},{"id":"C","text":"Databases","correct":true,"why":""},{"id":"D","text":"User permissions","correct":false,"why":""}],"answer":["A","B","C"],"explanation":"Splunk CIM Add-On Data Models Alerts Email Databases Java Virtual Machines (JVM) Application State Malware Authentication Network Resolution (DNS) Certificates Network Sessions Change Analysis Network Traffic CIM Validation (S.o.S) Performance Splunk Audit Logs Ticket Management Interprocess Messaging Updates Intrusion Detection Vulnerabilities Inventory Web","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-10-06","T-10-11"],"read":["reference/cim-data-models.md","topics/10-cim.md#what-it-is"],"verdict":"imprecise","note":"The keys are right. Alerts, Email and Databases each have their own reference page in the CIM 8.6 Data Models chapter, and there is no User permissions model. The problem is the catalogue printed in the explanation, which is several versions out of date, so do not memorise it. The 8.6 Data Models chapter lists: Alerts, Application State (deprecated), Authentication, Certificates, Change, Change Analysis (deprecated), Data Access, Data Loss Prevention, Databases, Email, Endpoint, Event Signatures, Interprocess Messaging, Intrusion Detection, Inventory, Java Virtual Machines (JVM), Malware, Network Resolution (DNS), Network Sessions, Network Traffic, Performance, Splunk Audit Logs, Ticket Management, Updates, Vulnerabilities, Web. CIM Validation (S.o.S.) is a real additional model but is documented on the validation page rather than in the reference-table chapter. Use reference/cim-data-models.md for the current catalogue.","courseKey":["A","B","C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models","title":"Data Models chapter index (CIM 8.6)","note":"The authoritative 8.6 model catalogue. Confirms Alerts, Email and Databases have reference pages, that there is no User permissions model, and that Application State and Change Analysis are flagged deprecated.","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-to-validate-your-data","title":"Use the CIM to validate your data (CIM 8.6)","note":"\"Use the CIM Validation (S.o.S.) datamodel\" section: CIM 4.2.0 moved the validation datasets into their own data model, so CIM Validation (S.o.S.) genuinely is a shipped model even though it has no reference-table page.","primary":false},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models/cim-fields-per-associated-data-model","title":"CIM fields per associated data model (CIM 8.6)","note":"Single-page field-to-model map; the model column shows the current names in use (Change, Data Access, Data Loss Prevention, Endpoint) with no Application State or Change Analysis.","primary":false}],"difficulty":"medium","issues":["The list presents Application State and Change Analysis as current models. In CIM 8.6 both are documented as deprecated (the pages are titled \"Application State (deprecated)\" and \"Change Analysis (deprecated)\"); Change Analysis was superseded by the Change data model.","The list is missing five models that exist in CIM 8.6: Change, Data Access, Data Loss Prevention, Endpoint, and Event Signatures. Anyone memorising this list would fail to recognise them.","The list omits Authentication, which is the single most heavily used CIM model and the keyed answer of t4-q10 in this same question bank."],"block":null,"tests":["test-2","test-final"],"authored":false},{"id":"t3-q1","type":"single","stem":"What is a limitation of searches generated by workflow actions?","options":[{"id":"A","text":"Searches generated by workflow actions cannot use macros.","correct":false,"why":""},{"id":"B","text":"Searches generated by workflow actions must be less than 256 characters long.","correct":false,"why":""},{"id":"C","text":"Searches generated by workflow actions must run in the same app as the workflow action.","correct":false,"why":""},{"id":"D","text":"Searches generated by workflow actions run with the same permissions as the user running them.","correct":true,"why":""}],"answer":["D"],"explanation":"Your role and permissions determine your ability to modify an object’s ettings","sec":"8.4","secTitle":"Create a Search workflow action","grp":"8","traps":["T-08-14","T-08-13"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"imprecise","note":"Option D is the best of four rather than a documented statement. Option C is definitively false: search.app exists precisely so the secondary search can run in a different app, and the setup page says \"Identify the app that the search runs in.\" Option B invents a 256 character limit that appears nowhere. Option A is not addressed by the docs in either direction. But calling D a limitation is odd, since running as the invoking user is normal Splunk behaviour for every knowledge object rather than a restriction peculiar to workflow actions. The real documented limitation of a search workflow action is escaping: the spec says search.search_string \"Does NOT attempt to determine if the inserted field values may break quoting or other search language escaping\", so quoting a token as \"$field$\" in SPL is on you. That is the fact worth carrying out of this question.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"search.app names \"the Splunk application in which to perform the constructed search\", which refutes option C, and search.search_string carries the only stated limitation, the absence of escaping.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-search-workflow-action","title":"Set up a search workflow action (Knowledge Manager Manual 10.4)","note":"\"Identify the app that the search runs in. If you want it to run in a view other than the current one, select that view.\" No character limit or macro restriction is stated anywhere on the page.","primary":false}],"difficulty":"medium","issues":["\"Your role and permissions determine your ability to modify an object's ettings\" is about editing knowledge objects, not about running the secondary search that a workflow action dispatches, so it does not support option D. It also contains a typo, \"ettings\" for \"settings\"."],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q2","type":"single","stem":"What does the transaction command do?","options":[{"id":"A","text":"Groups a set of transactions based on time.","correct":false,"why":""},{"id":"B","text":"Creates a single event from a group of events.","correct":true,"why":""},{"id":"C","text":"Separates two events based on one or more values.","correct":false,"why":""},{"id":"D","text":"Returns the number of credit card transactions found in the event logs.","correct":false,"why":""}],"answer":["B"],"explanation":"transaction Command • The transaction command creates a single event from a group of events – The events must share the same value in a specified field • Transactions can cross multiple tiers such as web servers or application servers • For example, you can easily view the events for JSESSIONID Ex- index=web sourcetype=access_combined | transaction JSESSIONID","sec":"3.1","secTitle":"Identify transactions","grp":"3","traps":["T-03-16"],"read":["topics/03-correlating-events.md#what-it-is"],"verdict":"agree","note":"Straight definitional recall for objective 3.1. Option A inverts the object (transaction groups events, not transactions), option C describes the opposite operation, and option D is the finance red herring that the exam likes to use for this command name.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"Description: transaction finds transactions based on events meeting various constraints; a transaction is made up of the raw text of each member plus the union of the members' fields, and adds duration and eventcount.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/identify-and-group-events-into-transactions","title":"Identify and group events into transactions (Search Manual 10.4)","note":"Opening line: \"You can search for related events and group them into one single event, called a transaction (sometimes referred to as a session).\"","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q3","type":"single","stem":"What is the relationship between data models and pivots?","options":[{"id":"A","text":"Data models provide the datasets for pivots.","correct":true,"why":""},{"id":"B","text":"Pivots and data models have no relationship.","correct":false,"why":""},{"id":"C","text":"Pivots and data models are the same thing.","correct":false,"why":""},{"id":"D","text":"Pivots provide the datasets for data models.","correct":false,"why":""}],"answer":["A"],"explanation":"Data model provides the datasets for Pivots","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-01"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"agree","note":"Objective 9.1 asked in its purest form. About data models opens with \"Data models drive the pivot tool\", and the Pivot Manual says Pivot \"uses data models to define the broad category of event data that you're working with\". The Apress study guide in this repo keys this exact question backwards, selecting option D. See source-notes/apress-errata.md.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"First line: \"Data models drive the pivot tool.\" Pivot users select a data model, then a dataset within it.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"\"How does Pivot work? It uses data models to define the broad category of event data that you're working with.\"","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q4","type":"single","stem":"Which of the following statements describes Search workflow actions?","options":[{"id":"A","text":"By default, Search workflow actions will run as a real-time search.","correct":false,"why":""},{"id":"B","text":"Search workflow actions can be configured as scheduled searches.","correct":false,"why":""},{"id":"C","text":"The user can define the time range of the search when created the workflow action.","correct":true,"why":""},{"id":"D","text":"Search workflow actions cannot be configured with a search string that includes the transaction command.","correct":false,"why":""}],"answer":["C"],"explanation":"Creating a Search Workflow Action Settings > Fields > Workflow actions> New 1. Select the app 2. Name the workflow action with no spaces or special characters 3. Define the label, which will appear in the Event Action menu 4. Determine if your workflow action applies to a field or event type 5. From the Show action in dropdown list, select Event menu 6. From the Action type dropdown list, select search 7. Enter the Search string (A) 8. Select the app if it is different from the current app 9. Enter the view name where the search will execute 10. Indicate if the search should run in a New window or the Current window 11. Enter the time range for the search or choose to use the same time range as the search (C) 12. Save","sec":"8.4","secTitle":"Create a Search workflow action","grp":"8","traps":["T-08-08"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"imprecise","note":"Option C is documented: \"Be sure to set a time range for the search (or identify whether it should use the same time range as the search that created the field listing) by entering relative time modifiers in the Earliest time and Latest time fields.\" The worked example sets Earliest time to -24h and leaves Latest time blank. Option A is documented false, since \"If these fields are left blank the search runs over all time by default\", not real time. Option B is the good distractor because a workflow action is user-triggered by definition and has no schedule setting. Option D invents a transaction restriction that does not exist. Worth knowing beyond this question: search.preserve_timerange is \"Ignored if either the search.earliest or search.latest values are set\", so an explicit bound always beats the inherit checkbox. Verdict is imprecise only because of the false naming rule in the explanation.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-search-workflow-action","title":"Set up a search workflow action (Knowledge Manager Manual 10.4)","note":"States the Earliest time and Latest time fields, the inherit-the-originating-range alternative, and that blank bounds mean all time rather than real time.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"search.earliest and search.latest accept absolute and relative times; search.preserve_timerange defaults to false and is ignored when either bound is set.","primary":false}],"difficulty":"medium","issues":["\"Name the workflow action with no spaces or special characters\" is not a Splunk rule and no documentation states it. The workflow_actions.conf.example file shipped with Splunk 10.4 defines the stanzas [Create JIRA issue] and [Controller req over time], both containing spaces.","The explanation is a copy of the search-action click path from another question and still carries an \"(A)\" marker against the Search string step, which is not the correct option here. The marker that matters is \"(C)\" on the time range step."],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q5","type":"single","stem":"Which of the following commands support the same set of functions?","options":[{"id":"A","text":"stats, eval, table","correct":false,"why":""},{"id":"B","text":"search, where, eval","correct":false,"why":""},{"id":"C","text":"stats, chart, timechart","correct":true,"why":""},{"id":"D","text":"transaction, chart, timechart","correct":false,"why":""}],"answer":["C"],"explanation":"","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-10"],"read":["reference/stats-and-chart-functions.md"],"verdict":"agree","note":"The docs open the page with exactly this sentence: \"You can use the statistical and charting functions with the chart, stats, and timechart commands.\" That is why one page documents count, sum, avg, distinct_count, values, list, earliest, latest and the rest for all three. They differ in output SHAPE, not in the function library. eval has a completely separate library (evaluation functions), which rules out A and B. One caveat worth knowing: the overlap is not literally total, the same page notes \"Sparkline is a function that applies to only the chart and stats commands\".","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/statistical-and-charting-functions/statistical-and-charting-functions","title":"Statistical and charting functions (Search Reference 10.4)","note":"Opening sentence names chart, stats and timechart as the three commands that take these functions; the related-commands table extends them to sichart, eventstats, streamstats, geostats, sistats and sitimechart. Sparkline is called out as chart and stats only.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q6","type":"multi","stem":"The eval command allows you to do which of the following? (Choose all that apply.)","options":[{"id":"A","text":"Format values","correct":true,"why":""},{"id":"B","text":"Convert values","correct":true,"why":""},{"id":"C","text":"Perform calculations","correct":true,"why":""},{"id":"D","text":"Use conditional statements","correct":true,"why":""}],"answer":["A","B","C","D"],"explanation":"Use the eval command to: – Perform calculations – Convert values – Round values – Format values – Use conditional statements","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-17"],"read":["reference/eval-functions.md"],"verdict":"agree","note":"All four keyed correct, so the question carries no discriminating information. Each is documented: calculations through the arithmetic operators, conversion through tostring and tonumber, formatting through tostring formats and strftime, rounding through round and sigfig, and conditionals through if, case, validate and coalesce. The one thing eval genuinely cannot do is assign a Boolean result to a field, which is why a bare like() or in() has to be wrapped in case, if or validate.","courseKey":["A","B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/eval","title":"eval command (SPL Search Reference 10.4)","note":"Operators table (arithmetic, concatenation, boolean, LIKE), Rounding and Significant digits sections, and the Supported functions pointer to the full evaluation function catalogue.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions (SPL Search Reference 10.4)","note":"case, if, validate, coalesce and the note that eval cannot accept a Boolean value directly.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q7","type":"single","stem":"When using the timechart command, how can a user group the events into buckets based on time?","options":[{"id":"A","text":"Using the span argument.","correct":true,"why":""},{"id":"B","text":"Using the duration argument.","correct":false,"why":""},{"id":"C","text":"Using the interval argument.","correct":false,"why":""},{"id":"D","text":"Adjusting the fieldformat options.","correct":false,"why":""}],"answer":["A"],"explanation":"• The timechart command \"buckets\" the values of the _time field – This provides dynamic sampling intervals, based upon the time range of the search • Example defaults: – Last 60 minutes uses span=1m – Last 24 hours uses span=30m • Adjust the interval using the span argument, e.g. span=15m Search query example: index=security sourcetype=linux_secure vendor_action=* | timechart span=15m count by vendor_action","sec":"1.2","secTitle":"Use the timechart command","grp":"1","traps":["T-01-05","T-01-06"],"read":["reference/time-modifiers.md","topics/01-transforming-commands.md#syntax-and-options"],"verdict":"agree","note":"`span` is the documented bin option that sets the size of each time bin. Option B is the sharp distractor because `duration` is a real Splunk field, just an OUTPUT of the transaction command rather than a timechart argument, and there is no `interval` argument anywhere in the timechart syntax. Related documented facts: timechart accepts either bins or span, and if you supply both, span wins and bins is ignored; with neither, it defaults to bins=100. The default-span table confirms the explanation's examples exactly: last 15 minutes 10s, last 60 minutes 1m, last 4 hours 5m, last 24 hours 30m, last 7 days 1 day, last 30 days 1 day, previous year 1 month.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/timechart","title":"timechart command (Search Reference 10.4)","note":"Bin options: span sets the size of each bin, bins defaults to 100. Usage, \"bins and span arguments\" and \"Default time spans\" tables confirm span wins over bins and list the picker defaults.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q8","type":"single","stem":"Which of the following statements about data models and pivot are true? (Choose all that apply.)","options":[{"id":"A","text":"They are both knowledge objects.","correct":false,"why":""},{"id":"B","text":"Data models are created out of datasets called pivots.","correct":false,"why":""},{"id":"C","text":"Pivot requires users to input SPL searches on data models.","correct":false,"why":""},{"id":"D","text":"Pivot allows the creation of data visualizations that present different aspects of a data model.","correct":true,"why":""}],"answer":["D"],"explanation":"• Pivots are used for creating reports and dashboards (D) First, identify a dataset that you want to report on, and then use a drag-and-drop interface to design and generate pivots that present different aspects of that data in the form of tables, charts, and other visualizations. • Data model provides the datasets for pivots. (Makes B invalid) • The Pivot tool lets you report on a specific data set without the Splunk Search Processing Language (SPL) (makes C invalid)","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-01"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"imprecise","note":"The stem says \"Choose all that apply\" but the course marks a single correct answer, so it renders as single-select. Option D is documented verbatim: Pivot uses \"a drag-and-drop interface to design and generate pivots that present different aspects of that data in the form of tables, charts, and other visualizations\". Option C is false because Pivot reports \"without the Splunk Search Processing Language (SPL)\". Option A is the shaky distractor: About data models says \"Data models are a category of knowledge object\", so a data model IS a knowledge object; the option only fails because Pivot is a tool rather than a knowledge object.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"Opening paragraph supplies both the \"without SPL\" fact and the drag-and-drop tables, charts and visualizations wording.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"\"Data models are a category of knowledge object and are fully permissionable\", which is why option A is debatable rather than plainly false.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q9","type":"multi","stem":"Data model fields can be added using the Auto-Extracted method. Which of the following statements describe Auto-Extracted fields? (Choose all that apply.)","options":[{"id":"A","text":"Auto-Extracted fields can be hidden in Pivot.","correct":true,"why":""},{"id":"B","text":"Auto-Extracted fields can have their data type changed.","correct":true,"why":""},{"id":"C","text":"Auto-Extracted fields can be given a friendly name for use in Pivot.","correct":true,"why":""},{"id":"D","text":"Auto-Extracted fields can be added if they already exist in the dataset with constraints.","correct":true,"why":""}],"answer":["A","B","C","D"],"explanation":"Adding Fields- Auto-Extracted • Hidden: This field is not displayed to Pivot users when they select the dataset in Pivot (A) • Auto-Extracted fields can have their data type changed like string, number, boolean,IPV4. (B) • Give the field a friendly name for use in Pivot(C) • Fields that already exist for the constraint can be added as attributes to the data model(D)","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-05","T-09-07","T-09-06"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"agree","note":"All four are documented in Define dataset fields, so the question has no discrimination. A: \"A hidden field is not displayed to Pivot users when they select the dataset in a Pivot context.\" B: Bulk Edit offers Boolean, IPv4, Number, String, and \"If an auto-extracted field's Type value is assigned incorrectly, you can provide the correct one.\" C: the editor \"lets you give fields in the Extracted and Calculated categories a display Name of your choice\", and renaming does not change the field name in the index. D: auto-extracted fields are the fields already present for the constraint, and you can also manually add fields that do not appear yet. The fact the exam actually tests and this question misses: \"You can only add auto-extracted fields to root datasets. Child datasets can inherit them, but they cannot add new auto-extracted fields of their own.\" Also separate Hidden from Required: Hidden only removes a field from the Pivot picker, while Required filters out every event lacking the field.","courseKey":["A","B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/define-data-model-dataset-fields/define-dataset-fields","title":"Define dataset fields (Knowledge Manager Manual 10.4)","note":"\"Marking fields as hidden or required\" and \"Enter or update field names and types\" cover hiding, renaming, and the Boolean/IPv4/Number/String type list; the Auto-extracted entry gives the root-dataset-only rule.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"\"Dataset field types\" lists the five field types (auto-extracted, eval expression, lookup, regular expression, geo IP) and the three groups of auto-extracted fields.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q10","type":"single","stem":"Which type of visualization shows relationships between discrete values in three dimensions?","options":[{"id":"A","text":"Pie chart","correct":false,"why":""},{"id":"B","text":"Line chart","correct":false,"why":""},{"id":"C","text":"Bubble chart","correct":true,"why":""},{"id":"D","text":"Scatter chart","correct":false,"why":""}],"answer":["C"],"explanation":"• Bubble chart provides a visual way to view a three dimensional series. • Each bubble plots against two dimensions on the X and Y axes. • The size of the bubble represents the value for the third dimension.","sec":null,"secTitle":null,"grp":null,"traps":[],"read":["topics/01-transforming-commands.md#result-contract"],"verdict":"agree","note":"Off blueprint but cleanly documented: \"Use a bubble chart to visualize multiple series data in three dimensions. Bubble position represents two dimensions of the data series. Bubble size represents the third dimension.\" Choosing a visualization type is not on SPLK-1002; section 1.0 covers the chart and timechart commands. The transferable part is the table shape: the bubble chart docs say the Statistics tab should have FOUR columns (row label plus x, y and size), against three for a scatter chart, and the worked example is `source=\"earthquakes.csv\" | stats count by place, mag, depth`. Scatter is the near-miss because it plots only two dimensions.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/create-dashboards-and-reports/simple-xml-dashboards/10.4/charts/bubble-chart","title":"Bubble chart (Simple XML Dashboards 10.4)","note":"Definition of the three dimensions, the `<stats_command> <y-axis_field> <x-axis_field> <bubble_size_field>` data shape, and the four-column Statistics tab requirement.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/create-dashboards-and-reports/simple-xml-dashboards/10.4/charts/chart-overview","title":"Chart overview (Simple XML Dashboards 10.4)","note":"Chart selection table: pie shows a single dimension, column/bar/line/area plot on two axes, scatter and bubble represent multiple dimensions.","primary":false}],"difficulty":"easy","issues":[],"block":"off-blueprint","tests":["test-3"],"authored":false},{"id":"t3-q11","type":"single","stem":"Which of the following is a function of the Splunk Common Information Model (CIM)?","options":[{"id":"A","text":"Normalizing data across a Splunk deployment.","correct":true,"why":""},{"id":"B","text":"Providing templates for reports and dashboards.","correct":false,"why":""},{"id":"C","text":"Algorithmically shifting events to other indexes.","correct":false,"why":""},{"id":"D","text":"Reingesting previously indexed data with new field names.","correct":false,"why":""}],"answer":["A"],"explanation":"• The Splunk Common Information Model (CIM) provides a methodology to normalize data. • Leverage the CIM when creating field extractions, field aliases,event types, and tags to ensure: – Multiple apps can co-exist on a single Splunk deployment – Object permissions can be set to global for the use of multiple apps – Easier and more efficient correlation of data from different sources and source types • The Common Information Model Add-on is based on the idea that you can break down most log files into two components: - fields - event category tags","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-01"],"read":["topics/10-cim.md#what-it-is"],"verdict":"agree","note":"Straight from the overview: the CIM \"helps you to normalize your data to match a common standard, using the same field names and event tags for equivalent events from different sources or vendors\" and \"acts as a search-time schema (schema-on-the-fly) to allow you to define relationships in the event data while leaving the raw machine data intact\". Options C and D are the same trap in different clothes: they imply CIM touches indexed data. It does not. CIM is search-time only and never moves, rewrites or reingests anything. Option B is the softest distractor and worth understanding rather than just rejecting: the CIM manual does have a \"Use the CIM to generate reports and dashboards\" chapter, but that is you building them in Pivot from the models, and the CIM-compliant dashboards themselves come from apps like Enterprise Security and the App for PCI Compliance. The add-on ships one dashboard, Data Model Audit, which reports on acceleration status, not a library of report templates.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/overview-of-the-splunk-common-information-model","title":"Overview of the Splunk Common Information Model (CIM 8.6)","note":"Why the CIM exists section: normalization to a common standard, the schema-on-the-fly statement, and the point that CIM-compliant dashboards come from other apps such as Enterprise Security.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/understand-and-use-the-common-information-model-add-on","title":"Understand and use the Common Information Model Add-on (Knowledge Manager Manual 10.4)","note":"The exact source of this question's explanation text: fields plus event category tags, normalized at search time to a similar schema.","primary":false},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/approaches-to-using-the-cim","title":"Approaches to using the CIM (CIM 8.6)","note":"Lists the documented uses (normalize, validate, generate reports and dashboards via Pivot, common action model), which is what makes option B a near-miss rather than nonsense.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q12","type":"multi","stem":"What is a Splunk Job? (Select all that apply.)","options":[{"id":"A","text":"A user-defined Splunk capability.","correct":false,"why":""},{"id":"B","text":"Searches that are subjected to some usage quota.","correct":false,"why":""},{"id":"C","text":"A search process kicked off via a report or an alert.","correct":true,"why":""},{"id":"D","text":"A child OS process manifested from the splunkd process.","correct":true,"why":""}],"answer":["C","D"],"explanation":"","sec":null,"secTitle":null,"grp":null,"traps":[],"read":["topics/00-foundations-refresher.md"],"verdict":"imprecise","note":"Off blueprint, and the distractor set is soft. C and D are both documented: \"Each time you run a search, create a pivot, open a report, or load a dashboard panel, the Splunk software creates a job\", and \"When a search job runs, it will manifest itself as a process in the OS called splunkd search\" (two processes actually, a main one and a helper). A is correctly false, capabilities are a role authorisation concept, not a job. Search jobs and the Job Inspector are assumed background rather than a listed objective; worth two minutes for the concepts that appear indirectly, such as scan count versus event count and execution costs. Also documented and useful: default job lifetime is 10 minutes, and 7 days once a job is shared.","courseKey":["C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/manage-jobs/about-jobs-and-job-management","title":"About jobs and job management (Search Manual 10.4)","note":"Defines a job as the process created by any search, pivot, report or dashboard panel, tracking owner, app, event count and runtime, and creating a search artifact. Also lists srchJobsQuota and srchDiskQuota, which is why option B is not clearly false.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/manage-jobs/manage-splunk-enterprise-jobs-from-the-os","title":"Manage Splunk Enterprise jobs from the OS (Search Manual 10.4)","note":"\"When a search job runs, it will manifest itself as a process in the OS called splunkd search\", with the ps output showing the child processes under the splunkd pid. Settles option D.","primary":false}],"difficulty":"medium","issues":["No explanation text is supplied, and option B is keyed false when the documentation arguably supports it. The same manual describes per-role job quotas that apply to search jobs: srchJobsQuota (default 3 concurrent searches) and srchDiskQuota (default 100 MB of job artifacts). B is a true statement about jobs; it fails only as a DEFINITION of one. If this question is reused, either rewrite B or accept it."],"block":"off-blueprint","tests":["test-3","test-final"],"authored":false},{"id":"t3-q13","type":"single","stem":"Which of the following statements is true, especially in large environments?","options":[{"id":"A","text":"Use the stats command when you need to group events by two or more fields.","correct":false,"why":""},{"id":"B","text":"The stats command is faster and more efficient than the transaction command.","correct":true,"why":""},{"id":"C","text":"The transaction command is faster and more efficient than the stats command.","correct":false,"why":""},{"id":"D","text":"Use the transaction command when you want to see the results of a calculation","correct":false,"why":""}],"answer":["B"],"explanation":"transaction vs. stats • When you have a choice, use stats—it’s faster and more efficient, especially in large Splunk environments • Only use transaction when you: – Need to see events correlated together – Must define event grouping based on start/end values or segment on time • Use stats when you: – Want to see the results of a calculation – Can group events based on a field value (e.g., by src_ip) • By default, there’s a limit of 1,000 events per transaction – No such limit applies to stats – Admins can change limit by configuring max_events_per_bucket in limits.conf","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-09"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"imprecise","note":"The keyed answer matches the docs, which say stats \"performs more efficiently, especially in a distributed environment\". The underlying reason is architectural: stats is distributable and can be computed on the peers, while transaction is a centralized streaming command that holds open transactions in search head memory (bounded by maxopentxn and maxopenevents). Option A is the flaw in the question: it is not actually false, since stats handles multiple BY fields perfectly well. It is simply less responsive to what was asked than B. Option D reverses the roles, because computing statistics is exactly what stats is for. Same bogus max_events_per_bucket claim in the explanation as t1-q8.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Using stats instead of transaction: \"In other cases, it's usually better to use the stats command, which performs more efficiently, especially in a distributed environment.\" Also the trade_id worked example showing the stats and transaction forms that yield the same answer.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"Usage: \"The transaction command is a centralized streaming command.\" Memory control options maxopentxn and maxopenevents exist precisely because open transactions are held in memory.","primary":false},{"url":"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/limits.conf","title":"limits.conf (Admin Manual 10.4)","note":"[transactions] stanza: maxopentxn Default 5000, maxopenevents Default 100000. max_events_per_bucket appears only under [search].","primary":false}],"difficulty":"medium","issues":["\"Admins can change limit by configuring max_events_per_bucket in limits.conf\" is a conflation. The setting does exist, but it sits in the [search] stanza of limits.conf where it limits the number of events retrieved for each timeline bucket for searches with status_buckets>0 (Default: 1000 in code). It has nothing to do with the transaction command. The per-transaction 1,000 ceiling is the transaction command's maxevents option (Default: 1000, deactivated if the value is negative). The limits.conf settings that actually bound transaction processing are in the [transactions] stanza: maxopentxn (Default: 5000) and maxopenevents (Default: 100000)."],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q14","type":"single","stem":"What does the following search do?\n\nindex=corndog type= mysterymeat action=eaten | stats count as corndog_count by user","options":[{"id":"A","text":"Creates a table of the total count of users and split by corndogs.","correct":false,"why":""},{"id":"B","text":"Creates a table of the total count of mysterymeat corndogs split by user.","correct":true,"why":""},{"id":"C","text":"Creates a table with the count of all types of corndogs eaten split by user.","correct":false,"why":""},{"id":"D","text":"Creates a table that groups the total number of users by vegetarian corndogs.","correct":false,"why":""}],"answer":["B"],"explanation":"","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-10"],"read":["reference/stats-and-chart-functions.md","topics/01-transforming-commands.md#result-contract"],"verdict":"agree","note":"Reading a stats result shape. Docs: \"If a BY clause is used, one row is returned for each distinct value specified in the BY clause.\" So `BY user` makes user the rows, `count` the single value column renamed corndog_count, and the base filter restricts to type=mysterymeat, which is what rules out option C. A and D invert the roles of the count and the split field.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/stats","title":"stats command (Search Reference 10.4)","note":"Description and by-clause: one row per distinct BY value, one row total when BY is omitted. AS renames the aggregate column.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q15","type":"multi","stem":"Which of the following statements about event types is true? (Choose all that apply.)","options":[{"id":"A","text":"Event types can be tagged.","correct":true,"why":""},{"id":"B","text":"Event types must include a time range.","correct":false,"why":""},{"id":"C","text":"Event types categorize events based on a search.","correct":true,"why":""},{"id":"D","text":"Event types can be a useful method for capturing and sharing knowledge.","correct":true,"why":""}],"answer":["A","C","D"],"explanation":"• Event Types – Categorize events based on a search string – Tag event types to organize data into categories – The eventtype field can be included in a search string – Does not include a time range - A useful method for institutional knowledge capturing and sharing - Can be tagged to group similar types of events","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-08","T-KO-06"],"read":["topics/06-tags-and-event-types.md#what-it-is"],"verdict":"agree","note":"A is documented outright: \"Event types can have one or more tags associated with them\", added when you save the search or later from Settings > Event types, or configured in tags.conf. It matters more than it looks, because tagging event types is the exact mechanism the CIM uses: event types run at stage 8 and tags at stage 9, so `eventtype` is just another field by the time tags apply, and you then search `tag::eventtype=<tagname>`. C is the definition of an event type. D holds because event types are shareable knowledge objects that let you \"find similar patterns, and create alerts and reports\". B is the discriminator: an eventtypes.conf stanza accepts only disabled, search, description, priority and color, so no time range exists to include, unlike a saved search or report.","courseKey":["A","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-types","title":"About event types (Knowledge Manager 10.4)","note":"\"Event types are a categorization system to help you make sense of your data\"; Event type tags section confirms one or more tags per event type and the `tag::eventtype=HTTP client error` search.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/configure-event-types-in-eventtypes.conf","title":"Configure event types in eventtypes.conf (Knowledge Manager 10.4)","note":"Event type syntax: disabled, search, description, priority, color. No time-range attribute exists, which is what makes option B false.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/define-event-types-in-splunk-web","title":"Define event types in Splunk Web (Knowledge Manager 10.4)","note":"\"(Optional) Add one or more comma-separated Tag(s). You can apply the same tag to event types that produce similar results.\"","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q16","type":"multi","stem":"The Field Extractor (FX) is used to extract a custom field. A report can be created using this custom field. The created report can then be shared with other people in the organization. If another person in the organization runs the shared report and no results are returned, why might this be? (Choose all that apply.)","options":[{"id":"A","text":"Fast mode is enabled.","correct":false,"why":""},{"id":"B","text":"The dashboard is private.","correct":false,"why":""},{"id":"C","text":"The extraction is private.","correct":true,"why":""},{"id":"D","text":"The person in the organization running the report does not have access to the index.","correct":true,"why":""}],"answer":["C","D"],"explanation":"","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-04"],"read":["topics/04-field-extractions.md#syntax-and-options","reference/knowledge-object-precedence.md"],"verdict":"agree","note":"The lesson worth keeping: sharing a report does not share the knowledge objects it depends on. The Save step docs are explicit that a new field extraction is set to Owner, \"meaning that it only extracts fields in searches run by the person who created the extraction\", so it must be promoted to App or All apps separately (C). Independently, roles control which indexes a user may search, so a colleague without access to the index gets no events at all (D). Option A is a real distractor to reason through: Fast mode turns off automatic field discovery, but fields the search explicitly references are still extracted, so it does not zero out the results. Option B is off-topic, the shared object is a report, not a dashboard.","courseKey":["C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-save-step","title":"Field Extractor: Save step (Knowledge Manager 10.4)","note":"\"The field extraction is set to Owner, meaning that it only extracts fields in searches run by the person who created the extraction.\" Setting Permissions to App or All apps is an explicit, separate action.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/manage-knowledge-object-permissions","title":"Manage knowledge object permissions (Knowledge Manager 10.4)","note":"\"When a Splunk user first creates a new report, event type, transaction, or similar knowledge object, it is only available to that user.\" Read means see and use; no permission means the role cannot see or use the object.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/manage-users-and-security/10.4/manage-splunk-platform-users-and-roles/create-and-manage-roles-with-splunk-web","title":"Create and manage roles with Splunk Web (Securing 10.4)","note":"\"Use the Indexes tab to choose the indexes that the role can search, and which ones it should search by default.\" Backs option D.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q17","type":"single","stem":"Which of the following statements describe the search string below?\n\n| datamodel Application_State All_Application_State search","options":[{"id":"A","text":"Events will be returned from dataset named Application_State.","correct":false,"why":""},{"id":"B","text":"Events will be returned from the data model named Application_State.","correct":true,"why":""},{"id":"C","text":"Events will be returned from the data model named All_Application_State.","correct":false,"why":""},{"id":"D","text":"No events will be returned because the pipe should occur after the datamodel command.","correct":false,"why":""}],"answer":["B"],"explanation":"Syntax: | datamodel [data model name] [dataset name] [search mode {search, flat, accelerate_search}]","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-10-07","T-09-12"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"imprecise","note":"Positional argument order is model first, dataset second, search mode third, so Application_State is the data model and All_Application_State is the dataset. Options A and C swap the first two. Option D inverts the rule for generating commands, which must lead with the pipe. The Search Reference example | datamodel Tutorial Client_errors search is the same shape. The course's syntax line misspells the third mode, see below.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/datamodel","title":"datamodel command (Search Reference 10.4)","note":"\"dataset name ... Must be specified after the data model name\", plus example 4, | datamodel Tutorial Client_errors search.","primary":true}],"difficulty":"medium","issues":["The syntax line names the search mode \"accelerate_search\". The documented mode name is acceleration_search.","The mode list is incomplete: there are six modes, three result modes (search, flat, acceleration_search) and three search-string modes (search_string, flat_string, acceleration_search_string)."],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q18","type":"single","stem":"What is the correct syntax to search for a tag associated with a value on a specific field?","options":[{"id":"A","text":"tag=<field>","correct":false,"why":""},{"id":"B","text":"tag=<field>(<tagname>)","correct":false,"why":""},{"id":"C","text":"tag=<field>::<tagname>","correct":false,"why":""},{"id":"D","text":"tag::<field>=<tagname>","correct":true,"why":""}],"answer":["D"],"explanation":"Searching for Tags • To search for a tag associated with a value:- tag= Ex: tag=privileged • To search for a tag associated with a value on a specific field:- tag::= Ex: tag::user=privileged • To search for a tag using a partial field value:– Use (*) wildcard Ex: tag=p* Note: tagname in this example has been taken as \"privileged\". Ref: https://docs.splunk.com/Documentation/Splunk/8.0.3/Knowledge/TagandaliasfieldvaluesinSplunkWeb","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-02"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"agree","note":"Verbatim from the docs: \"To search for a tag associated with a value in a specific field, use the following syntax: tag::<field>=<tagname>\". Double colon between `tag` and the field name, then a single equals before the tag name. Option C is the near-miss that puts the colons after the field and is the one people actually pick. The unscoped form is `tag=<tagname>` (option A drops the tag name entirely). Two caveats on the item text: the angle brackets have been stripped out of the transcribed explanation, so it reads \"tag::=\", and the reference link it cites is the 8.0.3 docs.splunk.com page, which now redirects to the 10.4 help.splunk.com page below.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in Search (Knowledge Manager 10.4)","note":"Search for tagged field values: exactly two forms, `tag=<tagname>` for any field and `tag::<field>=<tagname>` for a specific field. Wildcard examples `tag::eventtype=IP-*`, `tag::host=*local*`, `NOT tag::eventtype=*`.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-types","title":"About event types (Knowledge Manager 10.4)","note":"Worked example of the scoped form against the eventtype field: `tag::eventtype=HTTP client error`.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t3-q19","type":"single","stem":"In most large Splunk environments, what is the most efficient command that can be used to group events by fields?","options":[{"id":"A","text":"join","correct":false,"why":""},{"id":"B","text":"stats","correct":true,"why":""},{"id":"C","text":"streamstats","correct":false,"why":""},{"id":"D","text":"transaction","correct":false,"why":""}],"answer":["B"],"explanation":"transaction vs. stats • When you have a choice, use stats—it’s faster and more efficient, especially in large Splunk environments • Only use transaction when you: – Need to see events correlated together – Must define event grouping based on start/end values or segment on time • Use stats when you: – Want to see the results of a calculation – Can group events based on a field value (e.g., by src_ip) • By default, there’s a limit of 1,000 events per transaction – No such limit applies to stats – Admins can change limit by configuring max_events_per_bucket in limits.conf","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-09","T-03-17"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"imprecise","note":"The keyed answer is doc-backed twice over: the grouping chapter says stats and transaction \"are recommended over using the join and append commands\", and the transactions topic says stats \"performs more efficiently, especially in a distributed environment\". Option A is the trap for anyone importing SQL habits. Option C is a near-miss worth knowing: streamstats computes running aggregates event by event and does not collapse events into groups. Option D is the command the question is steering you away from in large environments. Marked imprecise only because the overallExplanation repeats the max_events_per_bucket error.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-event-grouping-and-correlation","title":"About event grouping and correlation (Search Manual 10.4)","note":"\"In most cases, you can accomplish more with the stats command or the transaction command; and these are recommended over using the join and append commands.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Using stats instead of transaction: stats \"performs more efficiently, especially in a distributed environment\", and \"Often there is a unique ID in the events and you can use the stats command.\"","primary":false}],"difficulty":"easy","issues":["\"Admins can change limit by configuring max_events_per_bucket in limits.conf\" is a conflation. The setting does exist, but it sits in the [search] stanza of limits.conf where it limits the number of events retrieved for each timeline bucket for searches with status_buckets>0 (Default: 1000 in code). It has nothing to do with the transaction command. The per-transaction 1,000 ceiling is the transaction command's maxevents option (Default: 1000, deactivated if the value is negative). The limits.conf settings that actually bound transaction processing are in the [transactions] stanza: maxopentxn (Default: 5000) and maxopenevents (Default: 100000).","The overallExplanation is generic transaction-versus-stats boilerplate and never addresses the two distractors this question actually turns on, join and streamstats. Neither groups events the way the question means: the docs recommend stats and transaction over join and append, and streamstats adds running aggregates to events rather than collapsing them into groups."],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q20","type":"single","stem":"A data model can consist of what three types of datasets?","options":[{"id":"A","text":"Pivot, searches, and events.","correct":false,"why":""},{"id":"B","text":"Pivot, events, and transactions.","correct":false,"why":""},{"id":"C","text":"Searches, transactions, and pivot.","correct":false,"why":""},{"id":"D","text":"Events, searches, and transactions","correct":true,"why":""}],"answer":["D"],"explanation":"Data Model Dataset Types - A data model can consist of 3 types of datasets • Events • Searches • Transactions","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-08"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"imprecise","note":"Key stands: every wrong option smuggles in \"Pivot\", which is a tool for consuming a data model, never a dataset type inside one. The stem is loose in the same way as t1-q14 though: events, searches and transactions are the three ROOT dataset types, and About data models counts four dataset types in total by adding child datasets.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Manager Manual 10.4)","note":"Root datasets are the event, search and transaction datasets; the Datasets section adds child datasets as a fourth type. Pivot is never a dataset type.","primary":true}],"difficulty":"easy","issues":["\"A data model can consist of 3 types of datasets\" counts root dataset types only. The docs list four dataset types: event, search, transaction, and child."],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q21","type":"single","stem":"When is a GET workflow action needed?","options":[{"id":"A","text":"To send field values to an external resource.","correct":false,"why":""},{"id":"B","text":"To retrieve information from an external resource.","correct":true,"why":""},{"id":"C","text":"To use field values to perform a secondary search.","correct":false,"why":""},{"id":"D","text":"To define how events flow from forwarders to indexes.","correct":false,"why":""}],"answer":["B"],"explanation":"• Execute workflow actions from an event in your search results to interact with external resources or run another search – GET - retrieve information from an external resource – POST - send field values to an external resource – Search - use field values to perform a secondary search","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-01","T-08-06"],"read":["topics/08-workflow-actions.md#decision-rules"],"verdict":"imprecise","note":"B is the intended and best answer, because A and C are the docs' own definitions of POST and Search, and D describes forwarding and routing, which has nothing to do with workflow actions. The imprecision is real though: the GET setup page opens with \"Clicking that link performs an HTTP GET request in a browser, allowing you to pass information to an external web resource\", so a GET action also sends field values outward, which is close to what option A says. The defensible distinction is the one the courseware compresses into retrieve versus send: GET puts the values in the URL query string and you land on the resource's response, while POST puts them in an HTTP-form-encoded request body so the target can create something. Answer B, but do not carry away the idea that a GET action sends nothing.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-get-workflow-action","title":"Set up a GET workflow action (Knowledge Manager Manual 10.4)","note":"\"GET link workflow actions drop one or more values into an HTML link\", with WHOIS lookups and search engines as the canonical examples; values in the URI are URL encoded automatically.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"The three kinds table separates GET, POST and Search, which is what options A, B and C are drawn from.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q22","type":"single","stem":"Which of the following statements describe GET workflow actions?","options":[{"id":"A","text":"GET workflow actions must be configured with POST arguments.","correct":false,"why":""},{"id":"B","text":"Configuration of GET workflow actions includes choosing a sourcetype.","correct":false,"why":""},{"id":"C","text":"Label names for GET workflow actions must include a field name surrounded by dollar signs.","correct":false,"why":""},{"id":"D","text":"GET workflow actions can be configured to open the URI link in the current window or in a new window.","correct":true,"why":""}],"answer":["D"],"explanation":"• GET workflow actions create typical HTML links to do things like perform Google searches on specific values or run domain name queries against external WHOIS databases. Define a GET workflow action: Steps 1.Navigate to Settings > Fields > Workflow Actions. 2.Click New to open up a new workflow action form. 3.Define a Label for the action. - The Label field enables you to define the text that is displayed in either the field or event workflow menu. Labels can be static or include the value of relevant fields. 4.Determine whether the workflow action applies to specific fields or event types in your data. 5.For Show action in determine whether you want the action to appear in the Event menu, the Fields menus, or Both. 6.Set Action type to link. 7.In URI provide a URI for the location of the external resource that you want to send your field values to. Note: Similar to the Label setting, WHEN you declare the Value of a Field, you use the name of the field enclosed by dollar signs. 8.Under Open link in, determine whether the workflow action displays in the current window or if it opens the link in a new window. 9.Set the Link method to get. 10. Click Save to save your workflow action definition.","sec":"8.2","secTitle":"Create a GET workflow action","grp":"8","traps":["T-08-02","T-08-10"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"agree","note":"D is documented step 8 of the GET procedure: \"Under Open link in, determine whether the workflow action displays in the current window or if it opens the link in a new window.\" The setting behind it is link.target, which accepts \"blank\" (new window) or \"self\" (same window) and defaults to \"blank\". Option C is the instructive miss: labels \"can be static or include the value of relevant fields\", so tokens are allowed but not required, and \"must\" is what makes it false. Option A confuses the two link methods, since link.postargs is \"Only available when link.method = post\". Option B is false because workflow action scope is narrowed by Apply only to the following fields and Apply only to the following event types; sourcetype is not a workflow action setting.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-get-workflow-action","title":"Set up a GET workflow action (Knowledge Manager Manual 10.4)","note":"The ten-step Define a GET workflow action procedure, including Open link in at step 8 and the statement that labels can be static or token-bearing.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"link.target accepts blank or self and defaults to blank; link.postargs is available only when link.method = post.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"Target workflow actions to a narrow grouping of events: scope is set by fields and event types, never by sourcetype, which refutes option B.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q23","type":"multi","stem":"Which are valid ways to create an event type? (Choose all that apply.)","options":[{"id":"A","text":"By using the searchtypes command in the search bar.","correct":false,"why":""},{"id":"B","text":"By editing the event_type stanza in the props.conf file.","correct":false,"why":""},{"id":"C","text":"By going to the Settings menu and clicking Event Types > New.","correct":true,"why":""},{"id":"D","text":"By selecting an event in search results and clicking Event Actions > Build Event Type.","correct":true,"why":""}],"answer":["C","D"],"explanation":"Creating an Event Type • Using the Event Type Builder 1. From the event details, select Event Actions > Build Event Type 2. Refine the criteria for your event type such as: - Search string - Field values - Tags 3. Verify your selections and click Save • From the Search Page 1. Run a search and verify that all results meet your event type criteria 2. From the Save As menu, select Event Type 3. Provide a Name for your event type (name should not contain spaces)","sec":"6.3","secTitle":"Create an event type","grp":"6","traps":["T-06-11"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"agree","note":"Both keyed routes are documented. C: \"Select Settings > Event Types. Click New.\" D: \"Click Event Actions and select Build Event Type\", the Build Event Type utility (Event Type Builder), which also lets you set a Style (colour) and Priority. Option A is a name trap: the command that finds candidate event types is `findtypes`, not searchtypes, and it finds them rather than creating them. Option B is the good trap: event types live in eventtypes.conf, not props.conf, and there is no event_type stanza. Two further valid routes the options omit, one of which the explanation itself describes: run a search and use Save As > Event Type, or edit eventtypes.conf directly. The explanation is not wrong, but note that it documents only the Build Event Type and Save As routes and never mentions the Settings > Event Types > New route it keys as correct.","courseKey":["C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/define-event-types-in-splunk-web","title":"Define event types in Splunk Web (Knowledge Manager 10.4)","note":"Adding a new event type in Settings: \"Select Settings > Event Types. Click New.\" Also documents the Save As > Event Type route from a search.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/automatically-find-and-build-event-types","title":"Automatically find and build event types (Knowledge Manager 10.4)","note":"Build Event Type utility: expand an event in the results, \"Click Event Actions and select Build Event Type\". Same page shows the finder command is `findtypes` (default top 10, max argument, analyses up to 5000 events), not searchtypes.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/configure-event-types-in-eventtypes.conf","title":"Configure event types in eventtypes.conf (Knowledge Manager 10.4)","note":"Settles option B: event type definitions are stanzas in eventtypes.conf, never props.conf, and the stanza header is the event type name.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q24","type":"single","stem":"Which command can include both an over and a by clause to divide results into sub-groupings?","options":[{"id":"A","text":"chart","correct":true,"why":""},{"id":"B","text":"stats","correct":false,"why":""},{"id":"C","text":"xyseries","correct":false,"why":""},{"id":"D","text":"transaction","correct":false,"why":""}],"answer":["A"],"explanation":"chart Command • You can use the by clause with the over clause to split results (over vendor_action by user) Ex- index=security sourcetype=linux_secure | chart count over vendor_action by user","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-03"],"read":["topics/01-transforming-commands.md#syntax-and-options"],"verdict":"agree","note":"OVER belongs to chart alone. The chart syntax line is `[ BY <row-split> <column-split> ] | [ OVER <row-split> ] [BY <column-split>]`, and the docs example `... | chart max(delay) OVER site BY org` shows both clauses together. stats has BY only (`BY <field-list>`), and timechart has BY only because its rows are already _time. xyseries takes positional x, y-name and y-data fields with no OVER or BY, and transaction takes a field list rather than either clause.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (Search Reference 10.4)","note":"Syntax block showing OVER <row-split> combined with BY <column-split>; basic example 2 is `... | chart max(delay) OVER site BY org`.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/stats","title":"stats command (Search Reference 10.4)","note":"stats syntax offers only `[<by-clause>]`, confirming there is no OVER on stats.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-3"],"authored":false},{"id":"t3-q25","type":"single","stem":"When should you use the transaction command instead of the stats command?","options":[{"id":"A","text":"When you need to group on multiple values.","correct":false,"why":""},{"id":"B","text":"When duration is irrelevant in search results.","correct":false,"why":""},{"id":"C","text":"When you have over 1000 events in a transaction.","correct":false,"why":""},{"id":"D","text":"When you need to group based on start and end constraints.","correct":true,"why":""}],"answer":["D"],"explanation":"transaction vs. stats • Only use transaction when you: – Need to see events correlated together – Must define event grouping based on start/end values or segment on time","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-09","T-03-19"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"agree","note":"Objective 3.6 in its cleanest form, and 3.0 is the heaviest section at 15%. startswith and endswith are the capability that has no stats equivalent, and the docs make the point explicitly: when trade_id values are reused but each trade ends with the text \"END\", \"the only solution is to use this transaction search\". Option A is false because stats groups on multiple BY fields fine. Option B argues for stats, since duration is one of the two things transaction gives you for free. Option C inverts the rule, as passing 1,000 events is a reason to avoid transaction (it is the maxevents default). This question's overallExplanation is a truncated version of the one on t1-q8 and t1-q18 and, usefully, stops before the bogus max_events_per_bucket line.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Using stats instead of transaction lists the two cases where transaction is most useful and shows the endswith=END example where transaction is \"the only solution\"; otherwise use stats.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"startswith and endswith definitions, and maxevents Default: 1000.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-3","test-final"],"authored":false},{"id":"t4-q1","type":"single","stem":"Which of the following statements describes POST workflow actions?","options":[{"id":"A","text":"POST workflow actions are always encrypted.","correct":false,"why":""},{"id":"B","text":"POST workflow actions cannot use field values in their URI.","correct":false,"why":""},{"id":"C","text":"POST workflow actions cannot be created on custom sourcetypes.","correct":false,"why":""},{"id":"D","text":"POST workflow actions can open a web page in either the same window or a new window.","correct":true,"why":""}],"answer":["D"],"explanation":"POST workflow actions generate an HTTP POST request to a specified URI. This action type enables you to do things like creating entries in external issue management systems using a set of relevant field values. POST - send field values to an external resource Ref: https://docs.splunk.com/Documentation/Splunk/8.0.3/Knowledge/SetupaPOSTworkflowaction","sec":"8.3","secTitle":"Create a POST workflow action","grp":"8","traps":["T-08-02","T-08-06"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"agree","note":"D is documented step 8 of the POST procedure, the same Open link in control the GET procedure uses, backed by link.target with values blank and self. Option A is false because encryption depends entirely on whether link.uri is https; nothing about the POST method guarantees it. Option B is directly refuted by the POST page's own note that \"variables passed in URIs for POST actions are URL encoded\", which only makes sense if POST URIs can carry $field$ tokens. The real difference from GET is that POST additionally carries key and value arguments in the HTTP-form-encoded request body rather than the query string. Option C is false because workflow action scope is set by fields and event types, not by sourcetype, custom or otherwise.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-post-workflow-action","title":"Set up a POST workflow action (Knowledge Manager Manual 10.4)","note":"Procedure step \"Under Open link in, determine whether the workflow action displays in the current window or if it opens the link in a new window\", plus the note that POST URI variables are URL encoded.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"link.target: \"blank\" opens a new window, \"self\" opens in the same window, default \"blank\". No encryption or sourcetype setting exists.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q2","type":"multi","stem":"What does the Splunk Common Information Model (CIM) add-on include? (Choose all that apply.)","options":[{"id":"A","text":"Custom visualizations","correct":false,"why":""},{"id":"B","text":"Pre-configured data models","correct":true,"why":""},{"id":"C","text":"Fields and event category tags","correct":true,"why":""},{"id":"D","text":"Automatic data model acceleration","correct":false,"why":""}],"answer":["B","C"],"explanation":"Splunk CIM Add-on • Set of 22 pre-configured data models – Fields and event category tags – Least common denominator of a domain of interest","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-10-02","T-10-14"],"read":["reference/cim-data-models.md","topics/10-cim.md#what-it-is"],"verdict":"imprecise","note":"The keys are right. The overview says the add-on \"contains a collection of pre-configured data models that you can apply to your data at search time\" and that each model \"consists of a set of field names and tags that define the least common denominator of a domain of interest\", which is options B and C verbatim. Option D is the one to hold on to: acceleration ships DISABLED and you enable it per model on the CIM Setup page. The only caveat is that Enterprise Security and the App for PCI Compliance auto-accelerate some CIM models through a Data Model Acceleration Enforcement modular input, which is those apps, not the CIM add-on. Option A is false, the add-on ships no custom visualizations, though it does ship more than models: a custom command for CIM validation, the common action model, the Data Model Audit dashboard, and macros (cim_datamodelinfo, cim_filter_*).","courseKey":["B","C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/overview-of-the-splunk-common-information-model","title":"Overview of the Splunk Common Information Model (CIM 8.6)","note":"\"The CIM add-on contains a collection of pre-configured data models ... Each data model in the CIM consists of a set of field names and tags that define the least common denominator of a domain of interest.\" Also lists the extra tools shipped with the add-on.","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/accelerate-cim-data-models","title":"Accelerate CIM data models (CIM 8.6)","note":"Settles option D: acceleration for all CIM models is disabled by default and is enabled per model on the CIM Setup page.","primary":false},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models","title":"Data Models chapter index (CIM 8.6)","note":"The current model catalogue, which is what makes the explanation's count of 22 out of date.","primary":false}],"difficulty":"medium","issues":["\"Set of 22 pre-configured data models\" is a dated count. The 8.6 docs never state a number; the Data Models chapter lists 26 model pages, of which Application State and Change Analysis are marked deprecated, and CIM Validation (S.o.S.) is documented separately on the validation page. Do not memorise a count for the exam."],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q3","type":"single","stem":"Which of the following statements about tags is true?","options":[{"id":"A","text":"Tags are case insensitive.","correct":false,"why":""},{"id":"B","text":"Tags are created at index time.","correct":false,"why":""},{"id":"C","text":"Tags can make your data more understandable.","correct":true,"why":""},{"id":"D","text":"Tags are searched by using the syntax tag::<fieldname>","correct":false,"why":""}],"answer":["C"],"explanation":"Tags: • A knowledge object that enables you to search for events that contain particular field values • Tags are like labels that you create for related field/value pairs • Tags make your data More Understandable and less ambiguous • You can create one or more tags for any field/value combination • Tags are case sensitive For more understanding: Tags are like nicknames that you create for related field/value pairs. When tagged field/value pairs are selected, the tags appear: – In parentheses next to the associated field/value pairs. Ex: user root(privileged) Note: privileged is tagname in this example. ref: https://docs.splunk.com/Documentation/Splunk/8.0.3/Knowledge/TagandaliasfieldvaluesinSplunkWeb","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-12","T-06-02","T-06-14"],"read":["topics/06-tags-and-event-types.md#traps"],"verdict":"disputed","note":"C is safely correct: tags exist to give abstract field values like IP addresses or ID numbers descriptive names and to group several values under one searchable name. B is cleanly false, since \"Tags come last in the sequence of search-time operations\" (stage 9 of 9), so tags are search-time, not index-time, and they can be applied to fields \"extracted at index time, search time, or added through some other method\". D is cleanly false, since the field-scoped syntax needs a tag name after the equals: `tag::<field>=<tagname>`. But A again asserts that tags ARE case sensitive, which the 10.4 docs never state. Third appearance of the same unsourced claim after t1-q23 and t2-q1. The key survives because C is right whatever the answer, but do not learn option A as a fact, and note that if tags are in fact case insensitive this single-answer item has two correct options.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/about-tags-and-aliases","title":"About tags and aliases (Knowledge Manager 10.4)","note":"\"Tags come last in the sequence of search-time operations\" settles option B; the Tags section (track abstract field values, group values under one name) settles option C. No case-sensitivity statement on the page.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in Search (Knowledge Manager 10.4)","note":"Settles option D: the two documented forms are `tag=<tagname>` and `tag::<field>=<tagname>`. A bare `tag::<fieldname>` is not valid syntax.","primary":false}],"difficulty":"easy","issues":["\"Tags are case sensitive\" is unsourced. Nothing in the 10.4 tags documentation states the case behaviour of tag names in either direction, so this cannot be quoted as fact even though it is the assumption the item is keyed on."],"block":"disputed","tests":["test-4","test-final"],"authored":false},{"id":"t4-q4","type":"single","stem":"Which of the following file formats can be extracted using a delimiter field extraction?","options":[{"id":"A","text":"CSV","correct":true,"why":""},{"id":"B","text":"PDF","correct":false,"why":""},{"id":"C","text":"XML","correct":false,"why":""},{"id":"D","text":"JSON","correct":false,"why":""}],"answer":["A"],"explanation":"Field Extraction Methods: • Delimiter - Use this option when your event contains structured data like a .csv file - The data doesn’t have headers and the fields must be separated by delimiters (spaces, commas, pipes, tabs, or other characters) • Regex – Use this option when your event contains unstructured data like a system log file – FX attempts to extract fields using a Regular Expression that matches similar events","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-15"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"imprecise","note":"Key is right. The Select Method docs use a .csv file as the worked example of delimiter-based extraction. XML and JSON are structured but hierarchical rather than delimited, and Splunk handles them through automatic key-value extraction (KV_MODE) or spath; PDF is not a text event format at all. Watch the second condition the docs attach to the delimiter method: the fields must also be consistent across events, each value in the same position. If they are not, the docs tell you to use the regular expression method with required text instead, even though a delimiter is present.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-select-method-step","title":"Field Extractor: Select Method step (Knowledge Manager 10.4)","note":"\"This is commonly the case with structured, table-based data such as .csv files or events indexed from a database\", with a comma-delimited USGS earthquake .csv event as the example. Regular Expression is for unstructured data such as a system log.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-rename-fields-step","title":"Field Extractor: Rename Fields step (Knowledge Manager 10.4)","note":"The delimiters-only step: pick Space, Comma, Tab, Pipe or Other, then rename at least one of the field1, field2, field3 placeholders.","primary":false}],"difficulty":"medium","issues":["The explanation says the delimiters method is for data that \"doesn't have headers\". The 10.4 docs describe the method as designed for \"data from files with headers, where all of the fields in the events are separated by a common delimiter\". The accurate takeaway is that the header row is not inside each event, so the extractor gives you field1, field2, field3 to rename.","The explanation omits the docs' second requirement, that the fields be consistent across events (same value in the same position). The docs give a counterexample of cleanly comma-separated events that are still a bad candidate for delimiter extraction."],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q5","type":"single","stem":"A user wants to create a new field alias for a field that appears in two sourcetypes. How many field aliases need to be created?","options":[{"id":"A","text":"One.","correct":false,"why":""},{"id":"B","text":"Two.","correct":true,"why":""},{"id":"C","text":"It depends on whether the original fields have the same name.","correct":false,"why":""},{"id":"D","text":"It depends on whether the two sourcetypes are associated with the same index.","correct":false,"why":""}],"answer":["B"],"explanation":"New field alias required for each sourcetype.","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-11","T-05-14"],"read":["topics/05-aliases-and-calculated-fields.md#syntax-and-options"],"verdict":"imprecise","note":"Two is the intended answer and the docs back it: \"Each field alias configuration is specific to events belonging to a particular host, source, or source type\", and the Splunk Web form makes you select one host, source or sourcetype value per alias. Correct the older note on this question: you cannot wildcard your way out of it for source types. The props.conf spec documents its pattern and wildcard match language for [source::<source>] and [host::<host>] stanzas only, while a [<sourcetype>] stanza is a literal source type. The only way one definition covers both would be to scope it to a source or host pattern common to both, which is not what the question describes. Learn the intended rule, one alias per sourcetype, and the reason: an alias lives in a props.conf stanza and a stanza targets one selector.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/create-field-aliases-in-splunk-web","title":"Create field aliases in Splunk Web (Knowledge Manager Manual 10.4)","note":"Steps: \"(Required) Select the host, source, or sourcetype to apply to a default field\", one selector per alias definition.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Manager Manual 10.4)","note":"Field aliasing section: \"Each field alias configuration is specific to events belonging to a particular host, source, or source type.\"","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/props.conf","title":"props.conf (Configuration File Reference 10.4)","note":"[<spec>] stanza section: spec is <sourcetype>, host::<host> or source::<source>, and the wildcard pattern match language is documented for the source:: and host:: forms, not for a bare source type stanza.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q6","type":"single","stem":"In the following eval statement, what is the value of description if the status is 503?\n\nindex=main | eval description=case(status==200, \"OK\", status==404, \"Not found\", status==500, \"Internal Server Error\")","options":[{"id":"A","text":"The description field would contain no value.","correct":true,"why":""},{"id":"B","text":"The description field would contain the value 0.","correct":false,"why":""},{"id":"C","text":"The description field would contain the value \"Internal Server Error\".","correct":false,"why":""},{"id":"D","text":"This statement would produce an error in Splunk because it is incomplete.","correct":false,"why":""}],"answer":["A"],"explanation":"case(X1,Y1,X2,Y2...) • The first argument, X1, is a boolean expression • If it evaluates to TRUE, the result evaluates to Y1 • If it evaluates to FALSE, the next boolean expression, X2, is evaluated, etc. • If none of the boolean expressions is true, the result evaluates to NULL ref: https://docs.splunk.com/Documentation/Splunk/8.1.1/SearchReference/ConditionalFunctions","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-07","T-02-05"],"read":["reference/eval-functions.md","topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"agree","note":"case() has no default branch: \"The function defaults to NULL if none of the <condition> arguments are true.\" The docs use this exact search as the basic example for case, and their results table shows rows for status 408 and 406 with the description cell empty, so 503 behaves the same way. Option C is the trap for anyone reading 503 as close enough to 500, and option D is wrong because three complete condition-value pairs are valid syntax. To supply a default, end with `true(), \"Other\"` (the documented idiom) or `1==1, \"Other\"`. Note also the = versus == convention the eval page spells out on this very statement: = assigns description, == compares status.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions, case (SPL Search Reference 10.4)","note":"case(<condition>,<value>,...): conditions evaluated first to last, \"defaults to NULL if none of the <condition> arguments are true\". Its example is this exact 200/404/500 search, with blank descriptions for 408 and 406. The true() entry shows the default-value idiom.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/eval","title":"eval command (SPL Search Reference 10.4)","note":"The = and == operators section uses this same case statement to explain assignment versus comparison.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q7","type":"single","stem":"In which Settings section are macros defined?","options":[{"id":"A","text":"Fields","correct":false,"why":""},{"id":"B","text":"Tokens","correct":false,"why":""},{"id":"C","text":"Advanced Search","correct":true,"why":""},{"id":"D","text":"Searches, Reports, Alerts","correct":false,"why":""}],"answer":["C"],"explanation":"Creating a Basic Macro Settings > Advanced search > Search macros 1. Click New Search Macro 2. Select the destination app 3. Enter a name 4. Type the search string 5. Save Note: Test your search string before saving your macro. You can check the contents of your macro with keyboard shortcuts (Command-Shift-E on Mac OS or Control-Shift-E on Linux or Windows) from the Search bar in the Search page.","sec":"7.2","secTitle":"Create and use a basic macro","grp":"7","traps":["T-07-14"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"agree","note":"Docs step 1: 'Select Settings > Advanced Search > Search macros.' Option A is where almost everything else in this exam lives (field extractions, aliases, calculated fields, workflow actions), which is exactly why macros being somewhere else is worth remembering. The Control-Shift-E (Command-Shift-E on macOS) expansion preview quoted in the explanation is real and is documented on the Use search macros page; it expands nested macros and saved searches too. One UI drift to ignore: 10.4 docs say 'Click New', while older versions and the course say 'New Search Macro'.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Manager Manual 10.4)","note":"Steps section: Settings > Advanced Search > Search macros, then Click New, set Destination app, Name, Definition, Save.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros","title":"Use search macros in searches (Knowledge Manager Manual 10.4)","note":"Preview search macros in search strings: Command-Shift-E (macOS) or Control-Shift-E (Linux, Windows) shows the expanded search string.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q8","type":"single","stem":"Which of the following statements describes calculated fields?","options":[{"id":"A","text":"Calculated fields are only used on fields added by lookups.","correct":false,"why":""},{"id":"B","text":"Calculated fields are a shortcut for repetitive and complex eval commands.","correct":true,"why":""},{"id":"C","text":"Calculated fields are a shortcut for repetitive and complex calc commands.","correct":false,"why":""},{"id":"D","text":"Calculated fields automatically calculate the simple moving average for indexed fields.","correct":false,"why":""}],"answer":["B"],"explanation":"Calculated Field is • A shortcut for performing repetitive, long, or complex transformations using the eval command • Must be based on an extracted field","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-05","T-KO-04"],"read":["topics/05-aliases-and-calculated-fields.md#what-it-is"],"verdict":"imprecise","note":"The key is right and matches the docs almost word for word: \"Use calculated fields as a shortcut for performing repetitive, long, or complex transformations using the eval command.\" Option A is exactly backwards and is the useful one: a calculated field runs at stage 6 and lookups at stage 7, and the docs say a calculated field \"can't reference lookups, event types, or tags\" and that you get an error if the eval expression uses a lookup field. Option C invents a `calc` command that does not exist. Marked imprecise for the \"must be based on an extracted field\" line in the explanation.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Manager Manual 10.4)","note":"Opening paragraph gives the \"shortcut for repetitive, long, or complex transformations using the eval command\" wording; Restrictions section rules out lookups, event types and tags.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Manager Manual 10.4)","note":"Calculated fields at 6, lookups at 7, with the explicit warning that a calculated field eval expression must never include fields added by a lookup.","primary":false}],"difficulty":"easy","issues":["\"Must be based on an extracted field\" overstates the rule. The docs say calculated fields \"can reference all types of field extractions\" and cannot reference lookups, event types or tags; they may also reference a field alias, because aliasing is stage 5 and calculated fields stage 6, and the eval statement itself is as flexible as the eval command."],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q9","type":"single","stem":"Which of the following are required to create a POST workflow action?","options":[{"id":"A","text":"Label, URI, search string.","correct":false,"why":""},{"id":"B","text":"XML attributes, URI, name.","correct":false,"why":""},{"id":"C","text":"Label, URI, post arguments.","correct":true,"why":""},{"id":"D","text":"URI, search string, time range picker.","correct":false,"why":""}],"answer":["C"],"explanation":"Creating a POST Workflow Action Settings > Fields >Workflow actions > New Workflow Action 1. Select the app 2. Name the workflow action with no spaces or special characters 3. Define the label, which will appear in the Event Action menu [Label] 4. Determine if your workflow action applies to a field or event type 5. From the Show action in dropdown list, select Event menu 6. From Action type dropdown list, select link 7. Enter the URI of where the user will be directed [URI] 8. Open the link in a New window or Current window 9. Select the Link method of post 10. Provide post argument parameters [ Post argument] 11. Save","sec":"8.3","secTitle":"Create a POST workflow action","grp":"8","traps":["T-08-06"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"imprecise","note":"Post arguments are what make a POST a POST: \"POST requests are typically defined by a form element in HTML along with some inputs that are converted into POST arguments. This means that you have to identify POST arguments to send to the identified URI.\" Label is a general required setting, link.uri carries an explicit Required line, and the arguments are key and value pairs written as link.postargs.<int>.key and .value. Options A and D both smuggle in \"search string\", which belongs to the search type and is not available when Action type is link, and D adds a time range picker for the same reason. Option B invents XML attributes. Objective 8.3 is the one the Apress book never demonstrates, so this question is worth extra attention. Verdict is imprecise only because of the false naming rule in the explanation.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-post-workflow-action","title":"Set up a POST workflow action (Knowledge Manager Manual 10.4)","note":"The procedure requires Label, URI and Post arguments; the Post arguments step describes the key and value pairs and the Add another field button.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"label sits under General required settings, link.uri is marked Required, and link.postargs.1.key / link.postargs.1.value show the foo=bar encoding.","primary":false}],"difficulty":"medium","issues":["\"Name the workflow action with no spaces or special characters\" is not a Splunk rule and no documentation states it. The workflow_actions.conf.example file shipped with Splunk 10.4 defines the stanzas [Create JIRA issue] and [Controller req over time], both containing spaces."],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q10","type":"single","stem":"Which of the following is one of the pre-configured data models included in the Splunk Common Information Model (CIM) add-on?","options":[{"id":"A","text":"Access","correct":false,"why":""},{"id":"B","text":"Accounting","correct":false,"why":""},{"id":"C","text":"Authorization","correct":false,"why":""},{"id":"D","text":"Authentication","correct":true,"why":""}],"answer":["D"],"explanation":"Splunk CIM Add-On Data Models Alerts Authentication Email Databases Java Virtual Machines (JVM) Application State Malware Network Resolution (DNS) Certificates Network Sessions Change Analysis Network Traffic CIM Validation (S.o.S) Performance Splunk Audit Logs Ticket Management Interprocess Messaging Updates Intrusion Detection Vulnerabilities Inventory Web","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-10-06"],"read":["reference/cim-data-models.md"],"verdict":"imprecise","note":"The key is right: Authentication has its own reference page in the CIM 8.6 Data Models chapter and there is no Access, Accounting or Authorization model. Watch the near-miss, though: Data Access IS a CIM 8.6 model, so option A is only wrong because it drops the qualifier. Authentication is the most heavily used CIM model and its events must carry tag=authentication. The distractors are the price of not knowing the catalogue, so learn it from reference/cim-data-models.md rather than from the list in this explanation.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models","title":"Data Models chapter index (CIM 8.6)","note":"Authoritative catalogue: Authentication is present; Access, Accounting and Authorization are not. Data Access and Data Loss Prevention are, which is why the distractors read as plausible.","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models/cim-fields-per-associated-data-model","title":"CIM fields per associated data model (CIM 8.6)","note":"Field-to-model map showing Authentication-only fields such as authentication_method and authentication_service, and confirming the current model names.","primary":false}],"difficulty":"easy","issues":["The model list presents Application State and Change Analysis as current. Both are marked deprecated in CIM 8.6, and Change Analysis was superseded by the Change data model.","The list is missing five CIM 8.6 models: Change, Data Access, Data Loss Prevention, Endpoint, and Event Signatures. The Data Access omission matters directly here, because it is what makes option A (\"Access\") look plausible."],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q11","type":"multi","stem":"Which of the following statements describe the search below? (Choose all that apply.)\n\nindex=main | transaction clientip host maxspan=30s maxpause=5s","options":[{"id":"A","text":"Events in the transaction occurred within 5 seconds.","correct":true,"why":""},{"id":"B","text":"It groups events that share the same clientip and host.","correct":true,"why":""},{"id":"C","text":"The first and last events are no more than 5 seconds apart.","correct":false,"why":""},{"id":"D","text":"The first and last events are no more than 30 seconds apart","correct":true,"why":""}],"answer":["A","B","D"],"explanation":"transaction Command – maxspan/maxpause • You can also define a max overall time span and max gap between events - maxspan=10m ▸ Maximum total time between the earliest and latest events (D) ▸ If not specified, default is -1 (or no limit) - maxpause=1m ▸ Maximum total time between events(A) ▸ If not specified, default is -1 (or no limit) Note: • The transaction command creates a single event from a group of events – The events must share the same value in a specified field (B)","sec":"3.3","secTitle":"Group events using fields and time","grp":"3","traps":["T-03-01","T-03-16"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"agree","note":"The best question in the set. A and C are deliberately near-identical and only the maxspan versus maxpause distinction separates them: maxpause=5s bounds the gap between CONSECUTIVE events (A), maxspan=30s bounds earliest to latest (D). The docs use exactly the phrasing option A borrows, describing `transaction clientip maxpause=5m maxspan=3h` as events \"that occurred within 5 minutes of each other (within a 3 hour time span)\". Option B is supported by the Search Reference's own extended example, which runs this very search and describes it as events with \"a unique combination of host and clientip values\". Careful with the follow-on generalisation though: the docs warn that multiple fields are not necessarily interpreted as a strict conjunction, because a transitive relationship (an event carrying only one of the fields) can pull events into the same transaction.","courseKey":["A","B","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"maxspan and maxpause definitions and defaults; Extended example 2 runs `sourcetype=access_* | transaction clientip host maxspan=30s maxpause=5s` and describes the result as a distinct combination of clientip and host values. The Specifying multiple fields section carries the not-necessarily-a-conjunction caveat.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/identify-and-group-events-into-transactions","title":"Identify and group events into transactions (Search Manual 10.4)","note":"maxpause \"Requires there be no pause between the events within the transaction greater than maxpause\"; the worked example reads maxpause=5m as events that \"occurred within 5 minutes of each other (within a 3 hour time span)\", which is the reading option A depends on.","primary":false}],"difficulty":"hard","issues":["The explanation glosses maxpause as \"Maximum total time between events\", which is the phrase that makes options A and C confusable. The operative definition is the pause between CONSECUTIVE events: the docs state maxpause \"Requires there be no pause between the events within the transaction greater than maxpause\", while the total earliest-to-latest span is maxspan. A transaction here can still be up to 30 seconds long overall.","\"The events must share the same value in a specified field\" is right for this search but understates the multi-field case. The Search Reference says Splunk \"does not necessarily interpret the transaction defined by multiple fields as a conjunction ... or a disjunction\", and an event missing one of the fields can still join (only a different value excludes it)."],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q12","type":"single","stem":"Consider the following search: index=web sourcetype=access_combined The log shows several events that share the same JSESSIONID value (SD421K26502F783). View the events as a group. From the following list, which search groups events by JSESSIONID?","options":[{"id":"A","text":"index-web sourcetype=access_combined | transaction JSESSIONID | search SD42IK26502F783","correct":true,"why":""},{"id":"B","text":"index-web sourcetype=access_combined | highlight JSESSIONID | search SD421K26502F783","correct":false,"why":""},{"id":"C","text":"index=web sourcetype=access_combined SD42IK26502F783 | table JSESSIONID","correct":false,"why":""},{"id":"D","text":"index=web sourcetype=access_combined JSESSIONID <SD421K26502F783>","correct":false,"why":""}],"answer":["A"],"explanation":"","sec":"3.4","secTitle":"Search with transactions","grp":"3","traps":["T-03-10"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"imprecise","note":"The reasoning is right, group with transaction then filter, which is the same lesson as t2-q19. Option B fails because highlight only colours matching terms in the results and does not group anything. Option C returns individual events with one column, not a group. Option D is not valid SPL. The question itself is riddled with transcription errors: `index-web` with a hyphen instead of `index=web` in options A and B, and the session id is inconsistently `SD42IK26502F783` and `SD421K26502F783`, swapping the digit 1 and the letter I. As printed, the keyed answer would not run. Note also that filtering after transaction is the correct answer here for pedagogy, not for performance: the docs point out that anything you can filter before the first pipe makes the search faster, but pre-filtering on the session id would still work here because every contributing event carries that JSESSIONID.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"Transactions retain the raw text of every member, so a post-transaction `search <term>` matches on any member's text. Extended examples use `sourcetype=access_* | transaction clientip ...` in this shape.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"Transaction search example groups first and filters afterwards, and adds \"Anytime you can filter the search before the first pipe, the faster the search runs.\"","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q13","type":"single","stem":"When defining a macro, what are the required elements?","options":[{"id":"A","text":"Name and a validation error message.","correct":false,"why":""},{"id":"B","text":"Definition and arguments.","correct":false,"why":""},{"id":"C","text":"Name and arguments.","correct":false,"why":""},{"id":"D","text":"Name and definition.","correct":true,"why":""}],"answer":["D"],"explanation":"Search Macros Search macros are reusable chunks of Search Processing Language (SPL) that you can insert into other searches. • The fundamental part of a search macro is its definition, which is the SPL chunk that the macro expands to when you reference it in another search. • Search macro must have a unique name. • (Optional) If your search macros require the search writer to provide argument variables, you can design validation expressions that tell the search writer when invalid arguments have been submitted. ref: https://docs.splunk.com/Documentation/Splunk/9.0.1/Knowledge/Definesearchmacros","sec":"7.2","secTitle":"Create and use a basic macro","grp":"7","traps":["T-07-11","T-07-05"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"agree","note":"Name and definition are the only two required fields: in the docs' step list every other field is prefixed '(Optional)', including Destination app, Use eval-based definition?, Arguments, Validation expression and Validation error message. That is what makes A, B and C wrong. macros.conf mirrors this, with the stanza name carrying the macro name and definition carrying the expansion. Note the course's reference link points at the 9.0.1 manual on docs.splunk.com; the current page is the 10.4 Knowledge Manager manual on help.splunk.com.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Manager Manual 10.4)","note":"Steps: 'Enter a unique Name' and 'In Definition, enter the search string' carry no (Optional) prefix; Arguments, Validation expression and Validation error message all do.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf (Configuration File Reference 10.4)","note":"Settings list: args, definition, validation, errormsg, iseval (default false), description (marked OPTIONAL). Stanza name plus definition are the substance of a macro.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q14","type":"single","stem":"What is the correct syntax to find events associated with a tag?","options":[{"id":"A","text":"tag:<field>=<tagname>","correct":false,"why":""},{"id":"B","text":"tags=<tagname>","correct":false,"why":""},{"id":"C","text":"tags:<field>=<tagname>","correct":false,"why":""},{"id":"D","text":"tag=<field>","correct":false,"why":""}],"answer":[],"explanation":"Searching for Tags • To search for a tag associated with a value:- tag= Ex: tag=privileged • To search for a tag associated with a value on a specific field:- tag::= Ex: tag::user=privileged • To search for a tag using a partial field value:– Use (*) wildcard Ex: tag=p* Note: tagname in this example has been taken as \"privileged\"","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-02"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"wrong","note":"The keyed answer is WRONG and the item is unanswerable as printed. The documentation gives exactly two forms: \"To search for a tag associated with a value in any field, use the following syntax: tag=<tagname>\" and \"To search for a tag associated with a value in a specific field, use the following syntax: tag::<field>=<tagname>\". The keyed option B is `tags=<tagname>` with an s, which is not valid; the multivalue field is named tag. A uses a single colon instead of the required double colon; C is both pluralised and single-coloned; D is `tag=<field>`, which puts a field name where a tag name belongs. So no offered option is correct. The question's own explanation states the right syntax and therefore contradicts its own key. Learn `tag=<tagname>` and `tag::<field>=<tagname>` and ignore this item.","courseKey":["B"],"corrected":[],"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in Search (Knowledge Manager 10.4)","note":"Search for tagged field values: the only two documented syntaxes are `tag=<tagname>` and `tag::<field>=<tagname>`. Nothing named `tags=` exists.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/about-tags-and-aliases","title":"About tags and aliases (Knowledge Manager 10.4)","note":"Worked search using the singular form: `tag=router tag=SF NOT (tag=Building1)`.","primary":false}],"difficulty":"medium","issues":[],"block":"unanswerable","tests":["test-4"],"authored":false},{"id":"t4-q15","type":"single","stem":"Which of the following is true about the Splunk Common Information Model (CIM)?","options":[{"id":"A","text":"The CIM contains 28 pre-configured datasets.","correct":false,"why":""},{"id":"B","text":"The data models included in the CIM are configured with data model acceleration turned on.","correct":false,"why":""},{"id":"C","text":"The data models included in the CIM are configured with data model acceleration turned off.","correct":true,"why":""},{"id":"D","text":"The CIM is an app that needs to run on the indexer.","correct":false,"why":""}],"answer":["C"],"explanation":"The data models included in the CIM add-on are configured with data model acceleration turned off.","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-02","T-10-05"],"read":["topics/10-cim.md#syntax-and-options"],"verdict":"agree","note":"Option C is doc-exact: \"All data models included in the CIM add-on have data model acceleration turned off by default.\" B is its inversion. Option D is worth as much attention as the key: the install page says \"Install the Splunk Common Information Model Add-on to your search heads only\", because everything the CIM does is search-time. Option A is false on two counts, the number, and the fact that it says datasets when the count people half-remember is of data models; the 8.6 docs state no count for either. The Apress book keys this same acceleration fact the wrong way round, see source-notes/apress-errata.md.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/set-up-the-splunk-common-information-model-add-on","title":"Set up the Splunk Common Information Model Add-on (CIM 8.6)","note":"\"All data models included in the CIM add-on have data model acceleration turned off by default\", plus the CIM Setup page where acceleration, Indexes allow list and Tags allow list are configured.","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/install-the-splunk-common-information-model-add-on","title":"Install the Splunk Common Information Model Add-on (CIM 8.6)","note":"Settles option D: \"Install the Splunk Common Information Model Add-on to your search heads only.\" Also Splunkbase app 1621 and the cim_modactions index.","primary":false},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/accelerate-cim-data-models","title":"Accelerate CIM data models (CIM 8.6)","note":"Second statement of the same default, and the per-model enable procedure with its acceleration parameters.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q16","type":"single","stem":"Which of the following statements describes POST workflow actions?","options":[{"id":"A","text":"Configuration of a POST workflow action includes choosing a sourcetype.","correct":false,"why":""},{"id":"B","text":"POST workflow actions can be configured to send email to the URI location.","correct":false,"why":""},{"id":"C","text":"By default, POST workflow actions are shown in both the event and field menus.","correct":false,"why":""},{"id":"D","text":"POST workflow actions can be configured to send POST arguments to the URI location.","correct":true,"why":""}],"answer":["D"],"explanation":"POST workflow actions generate an HTTP POST request to a specified URI. This action type enables you to do things like creating entries in external issue management systems using a set of relevant field values. POST requests are typically defined by a form element in HTML along with some inputs that are converted into POST arguments. This means that you have to identify POST arguments to send to the identified URI. Ref: https://docs.splunk.com/Documentation/Splunk/8.0.3/Knowledge/SetupaPOSTworkflowaction","sec":"8.3","secTitle":"Create a POST workflow action","grp":"8","traps":["T-08-12","T-08-06"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"imprecise","note":"D is right and is the point of the question: \"you have to identify POST arguments to send to the identified URI\", and they travel in an HTTP-form-encoded request body rather than the query string. Option C is the problem, and the docs do not support keying it false. workflow_actions.conf states plainly \"display_location = <string> ... Accepts field_menu, event_menu, or both. Default: both\", and fields defaults to * as well, so an action defined with neither setting really is offered in both the event menu and every field menu. The only sense in which C is false is that the Splunk Web form makes you pick Show action in explicitly rather than leaving a stanza default in place. Treat C as a defective distractor, not a settled falsehood, and remember the default is both. Option A is false because scope is set by fields and event types, not sourcetype, and option B is false because a workflow action has no email capability; that belongs to alert actions.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf (Admin Manual 10.4)","note":"display_location accepts field_menu, event_menu or both, with \"Default: both\", and fields defaults to *. This is the page that undermines the course's keying of option C.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-post-workflow-action","title":"Set up a POST workflow action (Knowledge Manager Manual 10.4)","note":"\"This means that you have to identify POST arguments to send to the identified URI\", and the Show action in step offering Event menu, Fields menus or Both.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/control-workflow-action-appearance-in-field-and-event-menus","title":"Control workflow action appearance in field and event menus (Knowledge Manager Manual 10.4)","note":"\"You can arrange for workflow actions to be event-level ... field-level ... or both\", confirming both is a supported and ordinary configuration.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q17","type":"multi","stem":"Which of the following are correct about search job inspector?(Choose all that apply)","options":[{"id":"A","text":"Allows you to examine overall stats of search.","correct":true,"why":""},{"id":"B","text":"Use to troubleshoot search’s performance and understand impact of knowledge objects on processing.","correct":true,"why":""},{"id":"C","text":"Contains three components.","correct":true,"why":""},{"id":"D","text":"Any existing (i.e., not expired) search job can be inspected.","correct":true,"why":""}],"answer":["A","B","C","D"],"explanation":"Search Job Inspector • Tool allows you to examine: – Overall stats of search (e.g., records processed and returned,processing time) – How search was processed – Where Splunk spent its time • Use to troubleshoot search’s performance and understand impact of knowledge objects on processing (e.g., event types, tags, lookups) • Any existing (i.e., not expired) search job can be inspected. • Search Job Inspector- Header, Execution costs, Search job properties.","sec":null,"secTitle":null,"grp":null,"traps":[],"read":["topics/00-foundations-refresher.md"],"verdict":"imprecise","note":"Off blueprint, and all four keyed correct so it discriminates nothing. A, B and D are documented almost word for word: the Job Inspector lets you \"troubleshoot the performance of a search job and understand the behavior of knowledge objects such as event types, tags, lookups and so on\", and \"You can access the Search Job Inspector for a search job, as long as the search job has not expired (which means that the search artifact still exists)\", with the search not needing to be running. C is courseware phrasing rather than a documented count, see the explanation issue. The genuinely useful idea is option B: the Job Inspector shows what your knowledge objects cost, which is how you would diagnose a slow search full of lookups and event types.","courseKey":["A","B","C","D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/manage-jobs/view-search-job-properties","title":"View search job properties, Search Job Inspector (Search Manual 10.4)","note":"Confirms the troubleshooting and knowledge-object purpose, the not-expired access rule, and that the key sections are Execution costs and Search job properties. Also documents the Job Details dashboard sections.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/manage-jobs/about-jobs-and-job-management","title":"About jobs and job management (Search Manual 10.4)","note":"Job menu section: Inspect Job opens the Search Job Inspector in a separate window; contrasts it with the Job Management page and Job Details dashboard.","primary":false}],"difficulty":"easy","issues":["\"Contains three components\" and the list \"Header, Execution costs, Search job properties\" come from Splunk courseware, not from the docs. The 10.4 page names only two: \"The key information that the Search Job Inspector displays are the execution costs and the search job properties.\" The header area is an information message plus the SID and two links (search.log and Job Details Dashboard), and current versions add the Job Details dashboard with its own four sections (Summary, Search Strings, Search Costs, Indexers). Treat the count as a mnemonic, not a fact to defend."],"block":"off-blueprint","tests":["test-4","test-final"],"authored":false},{"id":"t4-q18","type":"single","stem":"By default, which of the following fields would be listed in the fields sidebar under interesting Fields?","options":[{"id":"A","text":"host","correct":false,"why":""},{"id":"B","text":"index","correct":true,"why":""},{"id":"C","text":"source","correct":false,"why":""},{"id":"D","text":"sourcetype","correct":false,"why":""}],"answer":["B"],"explanation":"By default, the selected fields are: – host – source – sourcetype","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-07","T-04-06"],"read":["topics/00-foundations-refresher.md","topics/04-field-extractions.md#syntax-and-options"],"verdict":"agree","note":"A genuinely clever question and easy to misread. The Search Tutorial is explicit: \"When you first run a search the Selected Fields list contains the default fields host, source, and sourcetype\", so A, C and D sit in their own section above. index is also a default field, created when the data is indexed (\"The field that specifies the location of the data in your Splunk deployment is the index field\"), and it appears in every event, so it clears the Interesting Fields bar without being Selected. Remember the two lists are distinct and that the threshold, \"Interesting Fields are fields that appear in at least 20% of the events\", governs Interesting Fields only. All Fields is the dialog box you open to move a field into Selected Fields.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-tutorial/10.4/part-4-searching-the-tutorial-data/use-fields-to-search","title":"Use fields to search (Search Tutorial 10.4)","note":"\"When you first run a search the Selected Fields list contains the default fields host, source, and sourcetype. These default fields appear in every event. Interesting Fields are fields that appear in at least 20% of the events.\" Also names index as a default field created at index time.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q19","type":"single","stem":"How can an existing accelerated data model be edited?","options":[{"id":"A","text":"It cannot be edited. A new data model would need to be created.","correct":false,"why":""},{"id":"B","text":"The data model must be de-accelerated before edits can be made to its structure.","correct":true,"why":""},{"id":"C","text":"An accelerated data model can be edited once its .tsidx file has expired.","correct":false,"why":""},{"id":"D","text":"An accelerated data model can be edited from the Pivot tool.","correct":false,"why":""}],"answer":["B"],"explanation":"Accelerating a Data Model • With persistent data model acceleration, all fields in the model become \"indexed\" fields • You must have administrative permissions or the accelerate_datamodel capability to accelerate a data model • Private data models cannot be accelerated • Accelerated data models cannot be edited (Ans-A)","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-09-04","T-09-09","T-09-19"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"wrong","note":"The docs answer this question in option B's exact words. Manage data models: \"After you accelerate a data model, you cannot edit it. To make changes to an accelerated data model, you must turn off its acceleration.\" The same page adds \"You might disable and reenable acceleration for a data model when you edit the data model, because the data model cannot be edited when it is in an accelerated state\", and notes the summary is rebuilt automatically when you re-enable. Option A is right about the accelerated state but wrong about the remedy: nothing in the docs requires creating a new data model. Keep the slogan \"an accelerated data model cannot be edited\" for statement-style questions such as t2-q7 option B, but when the question asks HOW to edit one, de-accelerate is the documented answer.","courseKey":["A"],"corrected":["B"],"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/manage-data-models","title":"Manage data models (Knowledge Manager Manual 10.4)","note":"\"Enable data model acceleration\" caveat list and the note under \"Rebuild a summary for an accelerated data model\": you must turn acceleration off to change an accelerated model, and re-enabling triggers an automatic rebuild.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-data-summaries-to-accelerate-searches/accelerate-data-models","title":"Accelerate data models (Knowledge Manager Manual 10.4)","note":"\"When the data model definition changes and your summaries have not been updated to match it\" describes editing an existing accelerated model's definition and the allow_old_summaries setting, which presupposes that the model can be changed rather than replaced.","primary":false}],"difficulty":"medium","issues":["The explanation jumps from \"Accelerated data models cannot be edited\" to answer A, implying a new data model must be created. Manage data models gives the actual remedy: turn acceleration off, edit the model, then turn acceleration back on, at which point the Splunk platform automatically rebuilds the summary.","\"With persistent data model acceleration, all fields in the model become indexed fields\" is misleading as written. What the docs describe is .tsidx summary files built on the indexers that record the indexed field::value combinations for the accelerated datasets. The model's fields are not turned into index-time extracted fields in the source index."],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q20","type":"single","stem":"Which syntax is used to represent an argument in a macro definition?","options":[{"id":"A","text":"%argument%","correct":false,"why":""},{"id":"B","text":"'argument'","correct":false,"why":""},{"id":"C","text":"\"argument\"","correct":false,"why":""},{"id":"D","text":"$argument$","correct":true,"why":""}],"answer":["D"],"explanation":"Adding Arguments • Include the number of arguments in parentheses after the macro name - monthly_sales(3) • Within the search definition, use $arg$ (Ans-D) - currency=$currency$ - symbol=$symbol$ - rate=$rate$ • In the Arguments field, enter the name of the argument(s) • Provide one or more variables of the macro at search time","sec":"7.3","secTitle":"Define arguments and variables for a macro","grp":"7","traps":["T-07-01","T-07-04"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"agree","note":"Docs: 'the macro user must input the variables into the definition as tokens with dollar signs on either side of them. For example, $arg1$'. macros.conf is blunter: 'Arguments to be substituted must begin and end with a dollar sign ($)', and the substitution is global across the definition string, even inside quotation marks. Three different delimiters live in this area and the exam mixes them deliberately: BACKTICKS invoke a macro, $dollars$ mark an argument inside its definition, and 'single quotes' denote a field name containing special characters. Option B is that third one offered as a distractor.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Manager Manual 10.4)","note":"Design a search macro definition: variables appear in the definition as tokens with dollar signs on either side, for example $arg1$.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf (Configuration File Reference 10.4)","note":"definition setting: arguments to be substituted must begin and end with a dollar sign, and $<arg>$ is replaced globally in the string.","primary":false},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros","title":"Use search macros in searches (Knowledge Manager Manual 10.4)","note":"Contrast for the distractors: the backtick, not the dollar sign, is what invokes a macro in a search string.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q21","type":"single","stem":"Which of the following options will define the first event in a transaction?","options":[{"id":"A","text":"with","correct":false,"why":""},{"id":"B","text":"startswith","correct":true,"why":""},{"id":"C","text":"startingwith","correct":false,"why":""},{"id":"D","text":"firstevent","correct":false,"why":""}],"answer":["B"],"explanation":"transaction Command – startswith/endswith • To form transactions based on terms, field values, or evaluations, use startswith and endswith options (Ans- B) • In this example: – The first event in the transaction includes addtocart – The last event includes purchase transaction Command – startswith/endswith index=web sourcetype=access_combined | transaction clientip JSESSIONID startswith=eval(action=\"addtocart\") endswith=eval(action=\"purchase\") | table clientip, JSESSIONID, duration, eventcount","sec":"3.3","secTitle":"Group events using fields and time","grp":"3","traps":["T-03-15","T-03-05"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"agree","note":"startswith and endswith are the capability with no stats equivalent, which is why objective 3.6 keeps returning to them. Options A, C and D are invented names. The filter string accepts a search expression, a quoted search expression, or eval(<eval-expression>) that evaluates to a Boolean, so `startswith=eval(action=\"addtocart\")` in the course example is valid, but a bare regex is not an accepted form. One subtlety worth carrying: startswith is one of the four conditions (with maxevents, maxspan and maxpause) that lets a transaction be marked closed_txn=1, and endswith is not on that list, so endswith alone does not guarantee closed_txn=1. The docs explain why: transaction sees events in reverse chronological order, so it closes a transaction when the start condition is satisfied.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (Search Reference 10.4)","note":"startswith: \"A search or eval filtering expression which if satisfied by an event marks the beginning of a new transaction.\" Filter string options give the three accepted forms. keepevicted lists maxevents, maxspan, maxpause and startswith as the conditions that set closed_txn to 1.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/identify-and-group-events-into-transactions","title":"Identify and group events into transactions (Search Manual 10.4)","note":"startswith and endswith option entries with worked forms (startswith=\"login\", startswith=(username=foobar), startswith=eval(...)), both defaulting to the empty string.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q22","type":"single","stem":"What approach is recommended when using the Splunk Common Information Model (CIM) add-on to normalize data?","options":[{"id":"A","text":"Run a search using the authentication command.","correct":false,"why":""},{"id":"B","text":"Consult the CIM event type reference tables.","correct":false,"why":""},{"id":"C","text":"Consult the CIM data model reference tables.","correct":true,"why":""},{"id":"D","text":"Run a search using the correlation command.","correct":false,"why":""}],"answer":["C"],"explanation":"CIM Data Model Reference Tables: The CIM data model reference tables are a crucial resource for understanding how to map your data to the CIM data models. These tables contain object names, required tags for the objects, field names for the object, and the type of data that field is expected to contain.","sec":"10.3","secTitle":"Use the CIM Add-On to normalize data","grp":"10","traps":["T-10-03"],"read":["reference/cim-data-models.md","topics/10-cim.md#decision-rules"],"verdict":"agree","note":"Correct. Step 2 of Use the CIM to normalize data at search time says to \"Use the CIM reference tables to find fields that are relevant to your domain and your data\", and How to use the CIM data model reference tables describes exactly what they hold: the required tags that act as constraints for each dataset, plus the extracted and calculated fields with descriptions and expected values. Options A and D invent commands that do not exist, and option B invents a table type: the reference tables are organised per data model, with tags tables and fields tables inside them, not per event type. One terminology note when reading the explanation: the docs renamed data model \"objects\" to \"datasets\" in Splunk 6.5.0, so \"object names\" in the explanation means dataset names. reference/cim-data-models.md in this guide is that table.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models/how-to-use-the-cim-data-model-reference-tables","title":"How to use the CIM data model reference tables (CIM 8.6)","note":"Describes the tags tables (constraints per dataset, including inherited tags from parent datasets) and the fields tables (extracted and calculated fields, descriptions, expected values), and notes that \"object\" is the pre-6.5.0 term for \"dataset\".","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-to-normalize-data-at-search-time","title":"Use the CIM to normalize data at search time (CIM 8.6)","note":"Step 2 tells you to consult the reference tables as the recommended approach, and to keep the docs and the Data Model Editor open side by side.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"t4-q23","type":"single","stem":"If a calculated field has the same name as an extracted field, what happens to the extracted field?","options":[{"id":"A","text":"The calculated field will override the extracted field.","correct":true,"why":""},{"id":"B","text":"The calculated and extracted fields will be combined.","correct":false,"why":""},{"id":"C","text":"The calculated field will duplicate the extracted field.","correct":false,"why":""},{"id":"D","text":"An error will be returned and the search will fail.","correct":false,"why":""}],"answer":["A"],"explanation":"Preventing overrides of existing fields (Ans-A) If a calculated field has the same name as a field that has been extracted by normal means, the calculated field will override the extracted field, even if the eval statement evaluates to null. You can cancel this override with the coalesce function for eval in conjunction with the eval expression. Coalesce takes an arbitrary number of arguments and returns the first value that is not null. ref: https://docs.splunk.com/Documentation/Splunk/9.3.1/Knowledge/definecalcfields","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-09"],"read":["topics/05-aliases-and-calculated-fields.md#traps","reference/knowledge-object-precedence.md"],"verdict":"agree","note":"The sharp part is in the explanation rather than the options, and the 10.4 docs still carry it verbatim under \"Preventing overrides of existing fields\": the override happens EVEN IF the eval statement evaluates to null, so a badly written calculated field can silently blank a field that was extracting fine. The documented defence is coalesce, and the docs give two forms with different meanings: EVAL-field = coalesce(field, <eval expression>) keeps the existing field when the eval returns a value, while EVAL-field = coalesce(<eval expression>, field) keeps the existing field only when the eval returns null. The course's docs.splunk.com 9.3.1 link redirects to help.splunk.com and is not dead. This is a favourite exam detail.","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Manager Manual 10.4)","note":"\"Preventing overrides of existing fields\": \"If a calculated field has the same name as a field that has been extracted by normal means, the calculated field will override the extracted field, even if the eval statement evaluates to null.\" Both coalesce forms follow.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/configure-calculated-fields-with-props.conf","title":"Configure calculated fields with props.conf (Knowledge Manager Manual 10.4)","note":"\"<eval_statement> ... can be evaluated to any value type, including multivals, boolean, or null\", which is why the null case arises at all.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q24","type":"single","stem":"Which of the following knowledge objects can reference field aliases?","options":[{"id":"A","text":"Calculated fields and event types only.","correct":false,"why":""},{"id":"B","text":"Calculated fields and tags only.","correct":false,"why":""},{"id":"C","text":"Calculated fields, lookups, event types, and tags.","correct":true,"why":""},{"id":"D","text":"Calculated fields, lookups, event types, and extracted fields.","correct":false,"why":""}],"answer":["C"],"explanation":"https://docs.splunk.com/Documentation/Splunk/9.3.1/Knowledge/Searchtimeoperationssequence#Field_aliasing","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-KO-01","T-KO-03","T-KO-10"],"read":["reference/knowledge-object-precedence.md"],"verdict":"agree","note":"Pure precedence, and the cleanest question in the whole course set. Aliases run at stage 5, so everything AFTER them can consume an alias: calculated fields (6), lookups (7), event types (8), tags (9). The Splunk Web page states both directions: \"you cannot create aliases for calculated fields, event types, tags, or fields that are added to your events by a lookup\", and \"you can reference field aliases in the configurations for search-time operations that follow the field aliasing process\". Option D fails because extracted fields run BEFORE aliases and therefore cannot see them. Answer any question of this shape by locating both objects in the nine-stage sequence.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/create-field-aliases-in-splunk-web","title":"Create field aliases in Splunk Web (Knowledge Manager Manual 10.4)","note":"\"Where field aliases fit in the search-time sequence of operations\": aliases are applied after key-value extraction but before calculated fields, lookups, event types and tags, and later operations can reference them.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Manager Manual 10.4)","note":"\"Each operation can have configurations that reference fields derived by operations that precede them in the sequence. However, those same configurations cannot contain fields that are derived by operations that follow them.\" Lookup section adds that lookups can reference extractions, aliases and calculated fields.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["test-4","test-final"],"authored":false},{"id":"t4-q25","type":"single","stem":"Which of the following searches will return all clientip addresses that start with 108?","options":[{"id":"A","text":"... | where (clientip, \"108.%\"","correct":false,"why":""},{"id":"B","text":"... | where like(clientip, \"108.%\")","correct":true,"why":""},{"id":"C","text":"... | where (clientip=108.%)","correct":false,"why":""},{"id":"D","text":"... | search clientip=108","correct":false,"why":""}],"answer":["B"],"explanation":"Specify a wildcard with the where command You can only specify a wildcard with the where command by using the like function. The percent ( % ) symbol is the wildcard you must use with the like function. The where command returns like=TRUE if the ipaddress field starts with the value 198. ... | where like(ipaddress, \"198.%\") ref: https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Where?r=searchtip","sec":"2.2","secTitle":"Use the search and where commands to filter results","grp":"2","traps":["T-02-09","T-02-10"],"read":["topics/02-filtering-and-formatting.md#decision-rules","reference/eval-functions.md"],"verdict":"agree","note":"The where page states it flatly: \"You can only specify a wildcard with the where command by using the like function. The percent (%) symbol is the wildcard you must use\", and its example is `... | where like(ipaddress, \"198.%\")`. So `*` carries no wildcard meaning inside where. In like(), % matches multiple characters and _ matches exactly one, and the match is case sensitive. Option A is missing the function name and a parenthesis, option C is invalid syntax with a bare % , and option D is an exact-value match: it would be right as `search clientip=108*`, which is the whole search-versus-where distinction in one question. The equivalent forms are `where like(clientip,\"108.%\")` and `where clientip LIKE \"108.%\"`.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/where","title":"where command (SPL Search Reference 10.4)","note":"\"Using a wildcard with the where command\" and example 1: only the like function provides a wildcard, and that wildcard is %.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions, like (SPL Search Reference 10.4)","note":"like(<str>,<pattern>) \"performs a case-sensitive match\"; % is the multi-character wildcard, _ matches a single character; supported forms include `where <str> LIKE <pattern>`.","primary":false}],"difficulty":"medium","issues":[],"block":null,"tests":["test-4"],"authored":false},{"id":"tfinal-q1","type":"single","stem":"Which of the following is a feature of the Pivot tool?","options":[{"id":"A","text":"Data Models are not required.","correct":false,"why":""},{"id":"B","text":"Creates reports without using SPL.","correct":true,"why":""},{"id":"C","text":"Creates lookups without using SPL.","correct":false,"why":""},{"id":"D","text":"Datasets are not required.","correct":false,"why":""}],"answer":["B"],"explanation":"Pivot • Used for creating reports and dashboards • As a knowledge manager, you’re responsible for building the data model that provides the datasets for Pivot","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-01","T-09-18"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"agree","note":"The defining feature of Pivot is the first sentence of its manual: \"The Pivot tool lets you report on a specific data set without the Splunk Search Processing Language (SPL).\" Options A and D invert the dependency: Pivot cannot function without a data model supplying the dataset, and the workflow starts by identifying a dataset to report on. Option C is a category error, since lookups are defined in Settings, not in Pivot.","courseKey":["B"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"Opening paragraph: report without SPL; Pivot uses data models and their datasets, and pivots are saved as reports or dashboard panels.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["test-final"],"authored":false},{"id":"tfinal-q2","type":"single","stem":"Which workflow action type performs a secondary search?","options":[{"id":"A","text":"GET","correct":false,"why":""},{"id":"B","text":"POST","correct":false,"why":""},{"id":"C","text":"Search","correct":true,"why":""},{"id":"D","text":"Drilldown","correct":false,"why":""}],"answer":["C"],"explanation":"What are Workflow Actions? • Execute workflow actions from an event in your search results to interact with external resources or run another search – GET - retrieve information from an external resource – POST - send field values to an external resource – Search - use field values to perform a secondary search","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-01"],"read":["topics/08-workflow-actions.md#decision-rules"],"verdict":"agree","note":"Search is the only one of the three types that dispatches a new Splunk search job: \"Search workflow actions launch secondary searches that use specific field values from an event.\" Option D is the useful distractor, since a drilldown is a real Splunk concept but belongs to dashboards and is not one of the three workflow action kinds. Keep the two levels straight as well: Action type is link or search, while GET and POST are the two Link method values available once the type is link, which is why A and B cannot be the answer to a question about type.","courseKey":["C"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"The three kinds table: GET, POST and Search workflow actions, with Search defined as launching secondary searches from event field values.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-search-workflow-action","title":"Set up a search workflow action (Knowledge Manager Manual 10.4)","note":"Setting Action type to search reveals the Search configuration fields, confirming search is a type rather than a method.","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-final"],"authored":false},{"id":"tfinal-q3","type":"single","stem":"What type of command is eval?","options":[{"id":"A","text":"Distributable streaming","correct":true,"why":""},{"id":"B","text":"Report generating","correct":false,"why":""},{"id":"C","text":"Streaming in some modes","correct":false,"why":""},{"id":"D","text":"Centralized streaming","correct":false,"why":""}],"answer":["A"],"explanation":"ref: https://docs.splunk.com/Documentation/SplunkCloud/9.2.2406/SearchReference/Commandsbytype","sec":"2.1","secTitle":"The eval command","grp":"2","traps":[],"read":["reference/spl-command-reference.md","topics/00-foundations-refresher.md"],"verdict":"agree","note":"The Command types table lists eval as \"Distributable streaming\", and the eval page's own Usage line says the same. Be precise about what that buys you: a distributable streaming command runs on the indexers OR the search head depending on where it sits, and any distributable streaming command placed after a non-streaming command is forced onto the search head. That is why eval early in a pipeline costs almost nothing next to transaction, which is centralized streaming and only ever runs on the search head. The distractors are other commands' real classifications: \"Streaming in some modes\" is cluster, \"Centralized streaming\" is head or transaction, and report generating is not one of the six types (distributable streaming, centralized streaming, transforming, generating, orchestrating, dataset processing).","courseKey":["A"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/quick-reference/command-types","title":"Command types (SPL Search Reference 10.4)","note":"Streaming commands table: eval = Distributable streaming; transaction = Centralized streaming; cluster = Streaming in some modes. Intro names the six command types.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/eval","title":"eval command (SPL Search Reference 10.4)","note":"Usage: \"The eval command is a distributable streaming command.\"","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["test-final"],"authored":false},{"id":"tfinal-q4","type":"single","stem":"Which field extraction method should be selected for comma-separated data?","options":[{"id":"A","text":"table extraction","correct":false,"why":""},{"id":"B","text":"eval expression","correct":false,"why":""},{"id":"C","text":"Regular expression","correct":false,"why":""},{"id":"D","text":"Delimiters","correct":true,"why":""}],"answer":["D"],"explanation":"Field Extraction Methods Regex – Use this option when your event contains unstructured data like a system log file – FX attempts to extract fields using a Regular Expression that matches similar events • Delimiter - Use this option when your event contains structured data like a .csv file - The data doesn’t have headers and the fields must be separated by delimiters (spaces, commas, pipes, tabs, or other characters)","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-15"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"imprecise","note":"Key is right. Comma-separated events are the docs' own example for the Delimiters method, and the Rename Fields step offers Comma as a preset. Regex is technically capable of parsing CSV, so option C is not absurd, and the docs even tell you to fall back to Regular Expression with required text when delimited fields are NOT consistent across events. \"table extraction\" and \"eval expression\" are not field extraction methods in the FX at all: the only two are Regular expression and Delimiters.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-select-method-step","title":"Field Extractor: Select Method step (Knowledge Manager 10.4)","note":"The two methods are Regular expression (unstructured, such as a system log) and Delimiter (fields cleanly separated by a common delimiter and consistent across events, such as .csv).","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-rename-fields-step","title":"Field Extractor: Rename Fields step (Knowledge Manager 10.4)","note":"Comma is one of the four preset Delimiter options offered for delimiter-based extraction.","primary":false}],"difficulty":"easy","issues":["The explanation says the delimiters method is for data that \"doesn't have headers\". The 10.4 docs describe it as designed for \"data from files with headers, where all of the fields in the events are separated by a common delimiter\". The header row is simply not part of the individual events, which is why you rename field1, field2, field3 yourself."],"block":null,"tests":["test-final"],"authored":false},{"id":"tfinal-q5","type":"single","stem":"Which of the following is included with the Common Information Model (CIM) add-on?","options":[{"id":"A","text":"tsidx files","correct":false,"why":""},{"id":"B","text":"Search macros","correct":false,"why":""},{"id":"C","text":"Workflow actions","correct":false,"why":""},{"id":"D","text":"Event category tags","correct":true,"why":""}],"answer":["D"],"explanation":"Splunk CIM Add-on • Set of 22 pre-configured data models – Fields and event category tags – Least common denominator of a domain of interest • Leverage the CIM so that knowledge objects in multiple apps can co-exist on a single Splunk deployment • Available on splunkbase: – https://splunkbase.splunk.com/app/1621/ • Use the CIM Reference Tables – https://docs.splunk.com/Documentation/CIM/4.9.0/User/Howtousethesereferencetables","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-10-15","T-10-02"],"read":["reference/cim-data-models.md","topics/10-cim.md#what-it-is"],"verdict":"imprecise","note":"D is right and is the best answer: the overview says each CIM data model \"consists of a set of field names and tags\", and the Knowledge Manager Manual says the add-on breaks log files into fields and event category tags. Tags are the mechanism that admits an event into a CIM dataset. But option B should not be keyed false, because the add-on genuinely ships search macros. Treat this as a flawed distractor set rather than a mis-key: D is the defining content of the add-on and is what the item is testing, so score D and move on. The macros the 8.6 docs actually name are `cim_datamodelinfo` (data model acceleration status) and the CIM Filter macros such as `cim_filter_known_scanners`, which the docs place in the CIM Filters section of $SPLUNK_HOME/etc/apps/Splunk_SA_CIM/default/macros.conf. The earlier claim in this guide that the shipped set is `cim_<model>_indexes` is not supported by the 8.6 docs: index constraint is now the per-model Indexes allow list on the CIM Setup page. Option A is the clean falsehood, since tsidx summaries are produced by acceleration, which the add-on ships turned OFF. Option C is false, the add-on ships no workflow actions.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/overview-of-the-splunk-common-information-model","title":"Overview of the Splunk Common Information Model (CIM 8.6)","note":"Settles option D: each CIM data model \"consists of a set of field names and tags that define the least common denominator of a domain of interest\". Also lists the additional tools the add-on ships.","primary":true},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-filters-to-exclude-data","title":"Use the CIM Filters to exclude data (CIM 8.6)","note":"Why option B is not really false: the CIM Filter macros \"are available by default and located in the CIM Filters section of the $SPLUNK_HOME/etc/apps/Splunk_SA_CIM/default/macros.conf file\".","primary":false},{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/accelerate-cim-data-models","title":"Accelerate CIM data models (CIM 8.6)","note":"Why option A is false: tsidx column stores only exist once acceleration is enabled, and CIM acceleration ships disabled for every model.","primary":false}],"difficulty":"hard","issues":["\"Set of 22 pre-configured data models\" is a dated count. The 8.6 docs state no number; the Data Models chapter lists 26 model pages, two of them deprecated (Application State, Change Analysis), plus the separately documented CIM Validation (S.o.S.) model.","The explanation links the reference tables at CIM 4.9.0 (docs.splunk.com/Documentation/CIM/4.9.0/User/Howtousethesereferencetables). Current is CIM 8.6 at help.splunk.com/en/data-management/common-information-model/8.6/data-models/how-to-use-the-cim-data-model-reference-tables.","By listing only data models, fields and event category tags as add-on contents, the explanation reinforces the false premise behind option B. The add-on also ships search macros, a custom validation command, the common action model, and the Data Model Audit dashboard."],"block":null,"tests":["test-final"],"authored":false},{"id":"tfinal-q6","type":"single","stem":"Which type of workflow action sends field values to an external resource (e.g. a ticketing system)?","options":[{"id":"A","text":"GET","correct":false,"why":""},{"id":"B","text":"Search","correct":false,"why":""},{"id":"C","text":"Format","correct":false,"why":""},{"id":"D","text":"POST","correct":true,"why":""}],"answer":["D"],"explanation":"What are Workflow Actions? • Execute workflow actions from an event in your search results to interact with external resources or run another search – GET - retrieve information from an external resource – POST - send field values to an external resource – Search - use field values to perform a secondary search","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-01","T-08-06"],"read":["topics/08-workflow-actions.md#decision-rules"],"verdict":"agree","note":"The ticketing-system example is the canonical POST use case straight from the docs: POST workflow actions \"enable you to do things like creating entries in external issue management systems using a set of relevant field values\", and the worked example posts a title and a stacktrace to a bug tracker. POST arguments travel in the request body, HTTP-form encoded, not in the query string, which is the practical difference from GET. Option C, Format, is not a workflow action type at all.","courseKey":["D"],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-post-workflow-action","title":"Set up a POST workflow action (Knowledge Manager Manual 10.4)","note":"Worked example sends http_status and _raw as POST arguments to an external issue management system; Splunk \"HTTP-form encodes\" the passed variables.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Manager Manual 10.4)","note":"POST workflow actions \"generate an HTTP POST request to a specified URI ... creating entries in external issue management systems using a set of relevant field values\".","primary":false}],"difficulty":"easy","issues":[],"block":null,"tests":["test-final"],"authored":false},{"id":"sg-01-01","type":"single","stem":"A search returns one row per host, with a column for each distinct `status` value. Which search produces that table?","options":[{"id":"A","text":"`... | chart count OVER host BY status`","correct":true,"why":"The field after OVER is the row-split, so it becomes the first column and the X-axis. The field after BY is the column-split, so each distinct status becomes a column header. That is exactly the described shape."},{"id":"B","text":"`... | chart count OVER status BY host`","correct":false,"why":"This transposes the table. status becomes the row-split and each host becomes a column, which is the mirror image of what was asked for."},{"id":"C","text":"`... | stats count BY host status`","correct":false,"why":"With stats, every unique host and status combination is its own row and both fields stay as columns. You get three columns and many rows, not one row per host."},{"id":"D","text":"`... | timechart count BY host status`","correct":false,"why":"timechart accepts only one field in its BY clause, so this is a syntax error. It would also split rows by _time rather than by host."}],"answer":["A"],"explanation":"chart takes a row-split and a column-split. `chart count OVER host BY status` and `chart count BY host status` are the same search: the first field named is the row-split, the second is the column-split. Swapping the two fields transposes the result table.","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-03","T-01-10"],"read":["topics/01-transforming-commands.md#syntax-and-options"],"verdict":"authored","note":"The chart page defines the BY clause as `BY <row-split> <column-split>` with the comma optional, which is why the OVER form and the two-field BY form are equivalent.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (SPL Search Reference 10.4)","note":"Syntax section: the row-split becomes the X-axis, the column-split becomes the series.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-01"],"authored":true},{"id":"sg-01-02","type":"single","stem":"Why does `index=web | timechart count BY host, status` fail?","options":[{"id":"A","text":"timechart accepts only one field in its BY clause.","correct":true,"why":"_time is always timechart's row-split, so the single BY field is the column-split. There is no second slot to fill."},{"id":"B","text":"timechart requires an explicit `span` whenever a BY clause is used.","correct":false,"why":"span is optional. Without it timechart chooses a span from the time range, capped by the bins option, which defaults to 100."},{"id":"C","text":"The comma is invalid; `BY host status` would work.","correct":false,"why":"The comma is optional in a BY clause and is not the problem. Removing it still leaves two fields, which timechart cannot take."},{"id":"D","text":"count cannot be split by more than one field on any command.","correct":false,"why":"chart splits count by two fields routinely, and stats accepts a whole field list. The restriction belongs to timechart, not to count."}],"answer":["A"],"explanation":"Count fields, not clauses. Both chart and timechart have exactly one BY clause. chart's BY clause holds two fields because it needs a row-split and a column-split. timechart's holds one, because _time is already the row-split.","sec":"1.2","secTitle":"Use the timechart command","grp":"1","traps":["T-01-02","T-01-21"],"read":["topics/01-transforming-commands.md#timechart"],"verdict":"authored","note":"The timechart syntax shows a single split-by-clause, in contrast to chart's `BY <row-split> <column-split>`.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/timechart","title":"timechart command (SPL Search Reference 10.4)","note":"Syntax: _time is the implied row-split, leaving one split-by field.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-01"],"authored":true},{"id":"sg-01-03","type":"single","stem":"In `chart` and `timechart`, which option controls the series that collects values excluded by `limit`, and what is that series called by default?","options":[{"id":"A","text":"`useother`, and the series is labelled OTHER","correct":true,"why":"useother controls the catch-all series for values the limit or where-clause excluded. Its label comes from otherstr, which defaults to OTHER, and useother defaults to true on both commands."},{"id":"B","text":"`usenull`, and the series is labelled NULL","correct":false,"why":"usenull governs a different series entirely: events that have no value for the split-by field. Its label comes from nullstr, default NULL."},{"id":"C","text":"`useother`, and the series is labelled NULL","correct":false,"why":"The option is right but the label is not. NULL is nullstr's default and belongs to the missing-field series, not the excluded-values series."},{"id":"D","text":"`otherstr`, and the series is labelled OTHER","correct":false,"why":"otherstr only renames the series. Whether the series appears at all is controlled by useother."}],"answer":["A"],"explanation":"Two separate series, two separate switches. usenull with nullstr covers events missing the split-by field. useother with otherstr covers values that were pushed out by limit. Both default to true on chart and timechart, and useother defaults to false on top.","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-04","T-01-07"],"read":["topics/01-transforming-commands.md#syntax-and-options"],"verdict":"authored","note":"Worth carrying into the exam: the same option name defaults differently per command. useother is true on chart and timechart but false on top, which is why `top 5 host` shows no OTHER row.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (SPL Search Reference 10.4)","note":"Option table: usenull, nullstr, useother, otherstr and their defaults.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/top","title":"top command (SPL Search Reference 10.4)","note":"useother default is false here, unlike on chart.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-01"],"authored":true},{"id":"sg-01-04","type":"single","stem":"What does `limit=0` do on the `chart` command?","options":[{"id":"A","text":"Returns all results, applying no series limit.","correct":true,"why":"On chart, limit=0 removes the cap so every distinct value of the column-split gets a series."},{"id":"B","text":"Suppresses the series entirely, returning only the row-split column.","correct":false,"why":"Nothing is suppressed. Zero means no limit here, not none."},{"id":"C","text":"Falls back to the default of the top ten values.","correct":false,"why":"The top ten behaviour is what you get by omitting limit. Setting it to 0 explicitly overrides that default."},{"id":"D","text":"Errors, because limit must be a positive integer.","correct":false,"why":"Zero is a documented value on chart, timechart, top and rare."}],"answer":["A"],"explanation":"limit=0 means no limit across chart, timechart, top and rare. On top and rare it returns all values up to maxresultrows, whose default maximum is 50,000. Reading it as zero results is the trap.","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-17","T-01-01"],"read":["topics/01-transforming-commands.md#syntax-and-options"],"verdict":"authored","note":"The related trap is what limit counts. On chart it limits the number of columns, not rows, and it is only valid when a column-split is specified.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (SPL Search Reference 10.4)","note":"limit option: 0 returns all results.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-01"],"authored":true},{"id":"sg-01-05","type":"multi","stem":"Which two statements about the `chart` command are true? (Choose two.)","options":[{"id":"A","text":"A statistical function is required; a bare field name is not valid.","correct":true,"why":"The docs state you must specify a statistical function with chart. `chart sales BY product_name` fails; `chart sum(price) AS sales BY product_name` is the working form."},{"id":"B","text":"If both `span` and `bins` are given, `span` is used and `bins` is ignored.","correct":true,"why":"This is documented behaviour on the bin options. Neither errors, and they do not compound."},{"id":"C","text":"The same field can be used both inside the function and as the split-by field.","correct":false,"why":"It cannot. The documented workaround is to copy it first: `eval A1=A` then `chart sum(A) BY A1`."},{"id":"D","text":"`partial` and `fixedrange` are chart options that default to true.","correct":false,"why":"Both exist only on timechart. cont exists on both commands and defaults to true on both."}],"answer":["A","B"],"explanation":"Three chart facts worth separating from timechart: chart demands an aggregation, span wins over bins when both appear, and a field cannot be aggregated and split on at the same time. partial and fixedrange are timechart-only.","sec":"1.1","secTitle":"Use the chart command","grp":"1","traps":["T-01-22","T-01-06","T-01-11","T-01-09"],"read":["topics/01-transforming-commands.md#syntax-and-options"],"verdict":"authored","note":"Bin defaults differ by command and are worth memorising: chart defaults to bins=300, timechart to bins=100. Both are maximums, not targets.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/chart","title":"chart command (SPL Search Reference 10.4)","note":"Usage: a statistical function is required; bin options note that span takes precedence over bins.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/timechart","title":"timechart command (SPL Search Reference 10.4)","note":"partial and fixedrange are documented here and not on chart.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-01"],"authored":true},{"id":"sg-02-01","type":"single","stem":"A search must return events where the `clientip` field and the `ipaddress` field hold the same value. Which search does that?","options":[{"id":"A","text":"`index=web | where clientip=ipaddress`","correct":true,"why":"where compares two field values directly. This is the only construct in the list that treats ipaddress as a field rather than as text."},{"id":"B","text":"`index=web clientip=ipaddress`","correct":false,"why":"The search command expects a field compared to a literal, so it looks for events whose clientip is the eight-character string ipaddress. It almost always returns nothing."},{"id":"C","text":"`index=web | search clientip=ipaddress`","correct":false,"why":"Explicitly piping to search changes nothing. search reads the right-hand side as a literal wherever it appears."},{"id":"D","text":"`index=web | eval clientip=ipaddress`","correct":false,"why":"eval assigns rather than filters. This overwrites clientip with the value of ipaddress on every event and removes no events at all."}],"answer":["A"],"explanation":"Comparing two fields is a where job. search compares a field to a literal value, so a bare field name on the right-hand side is read as a string. The same rule gives the negative form: use `where fieldA!=fieldB`, not a search expression.","sec":"2.2","secTitle":"Use the search and where commands to filter results","grp":"2","traps":["T-02-01"],"read":["topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"authored","note":"The where page states the command is used to compare two different fields, which is the distinction the exam tests most often in this objective.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/where","title":"where command (SPL Search Reference 10.4)","note":"Description: where compares two fields, unlike search which compares a field to a literal.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-02","type":"single","stem":"How does the `search` command evaluate `host=\"www1\" AND status=200 OR action=\"addtocart\"`?","options":[{"id":"A","text":"`host=\"www1\" AND (status=200 OR action=\"addtocart\")`","correct":true,"why":"search evaluates OR before AND, so the OR binds its two neighbours first and the AND applies to the result."},{"id":"B","text":"`(host=\"www1\" AND status=200) OR action=\"addtocart\"`","correct":false,"why":"That is how eval and where read it, because they evaluate AND before OR. search is the exception."},{"id":"C","text":"Strictly left to right, so `((host=\"www1\" AND status=200) OR action=\"addtocart\")`.","correct":false,"why":"SPL applies operator precedence rather than plain left-to-right evaluation, and the result happens to match the eval ordering, not search's."},{"id":"D","text":"It errors, because Boolean operators must be parenthesised in the search command.","correct":false,"why":"Parentheses are recommended for clarity but are not required. The expression runs."}],"answer":["A"],"explanation":"Precedence differs by command. In search, NOT then OR then AND. In eval and where, NOT then AND then OR. Parenthesise anything that mixes them, which is what the documentation itself recommends.","sec":"2.2","secTitle":"Use the search and where commands to filter results","grp":"2","traps":["T-02-02"],"read":["topics/02-filtering-and-formatting.md#traps"],"verdict":"authored","note":"A second difference worth knowing: search has no XOR operator, while eval and where both do.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/search","title":"search command (SPL Search Reference 10.4)","note":"Usage: operator precedence in the search command places OR ahead of AND.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-03","type":"single","stem":"Some events in an index have no `status` field. Which search returns every event except those whose status is 404, including the events that have no status field at all?","options":[{"id":"A","text":"`index=web NOT status=404`","correct":true,"why":"NOT negates the whole match, so anything that is not an event with status 404 comes back, including events that never had a status field."},{"id":"B","text":"`index=web status!=404`","correct":false,"why":"The != form requires the field to exist with a different value, so every event missing status is silently dropped."},{"id":"C","text":"`index=web | where status!=404`","correct":false,"why":"where evaluates the expression per event and a null status makes the comparison untrue, so those events are dropped here too."},{"id":"D","text":"`index=web | search status!=404 OR status=*`","correct":false,"why":"Both sides require a status field to exist, so the OR still excludes every event without one."}],"answer":["A"],"explanation":"`field!=value` is a positive test that the field exists and differs. `NOT field=value` is a true negation covering the missing-field case. The corollary is worth memorising: `NOT field=*` returns events where the field is null, while `field!=*` never returns anything.","sec":"2.2","secTitle":"Use the search and where commands to filter results","grp":"2","traps":["T-02-03"],"read":["topics/02-filtering-and-formatting.md#traps"],"verdict":"authored","note":"This is one of the highest-yield facts in section 2.0 because it decides result counts rather than syntax validity.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/search","title":"search command (SPL Search Reference 10.4)","note":"Difference between NOT and != when a field is absent.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-04","type":"multi","stem":"Which two statements about case sensitivity in SPL are true? (Choose two.)","options":[{"id":"A","text":"In the search command, field names are case sensitive but field values are not.","correct":true,"why":"`Status=200` will not find a field named status, but `status=OK` matches a stored value of ok."},{"id":"B","text":"Expressions in eval and where are case sensitive.","correct":true,"why":"The eval and where pages both state the expression is case-sensitive, which is why `where status=\"ok\"` and `where status=\"OK\"` behave differently."},{"id":"C","text":"Keyword searches are case sensitive unless wrapped in `TERM()`.","correct":false,"why":"Keyword searches are case-insensitive by default. `CASE()` is the function that makes a term match case-sensitively."},{"id":"D","text":"The `like()` function matches without regard to case.","correct":false,"why":"like() matches case-sensitively, which catches people who expect SQL-style behaviour."}],"answer":["A","B"],"explanation":"There is no single rule. Under search, field names are case sensitive, values are not, and keywords are insensitive unless wrapped in CASE(). Under eval and where, everything is case sensitive, including like().","sec":"2.2","secTitle":"Use the search and where commands to filter results","grp":"2","traps":["T-02-04"],"read":["topics/02-filtering-and-formatting.md#traps"],"verdict":"authored","note":"Splunk's own study material contradicts itself on this point, which is why the exam can afford to ask it. Answer from the search and eval pages rather than from memory of a course slide.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/where","title":"where command (SPL Search Reference 10.4)","note":"\"The <eval-expression> is case-sensitive.\"","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions (SPL Search Reference 10.4)","note":"like() performs a case-sensitive match.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-05","type":"single","stem":"Which description of `coalesce()` is correct?","options":[{"id":"A","text":"It takes one or more arguments and returns the first value that is not NULL.","correct":true,"why":"That is the documented behaviour. It is the standard way to merge several source-specific field names into one."},{"id":"B","text":"It takes a predicate and returns the second argument when the predicate is true.","correct":false,"why":"That describes if(), which takes exactly three arguments: a predicate, a true value and a false value."},{"id":"C","text":"It takes two fields and returns NULL when they are equal.","correct":false,"why":"That is nullif(). coalesce does not compare its arguments to each other."},{"id":"D","text":"It takes no arguments and returns NULL, clearing a field when assigned.","correct":false,"why":"That is null(). Assigning it is how you clear a field value in eval."}],"answer":["A"],"explanation":"Four functions that get swapped for each other on exams: coalesce() returns the first non-null of its arguments, if() is the three-argument conditional, nullif() returns NULL when two fields are equal, and null() takes no arguments at all.","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-05","T-02-06"],"read":["topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"authored","note":"The printed Apress study guide states the coalesce and null definitions incorrectly in its Table 2-16, which is recorded in source-notes/apress-errata.md. Answer from the docs.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions (SPL Search Reference 10.4)","note":"coalesce(<values>) returns the first value that is not null.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-06","type":"single","stem":"What happens when a value matches none of the conditions in a `case()` expression?","options":[{"id":"A","text":"The expression returns NULL.","correct":true,"why":"case() returns NULL when no condition evaluates to TRUE. The documented idiom for a default is a final `true(), \"<default>\"` pair."},{"id":"B","text":"The last value listed is returned as a fallback.","correct":false,"why":"There is no implicit fallback. Nothing about being last makes a value a default."},{"id":"C","text":"The original field value is left unchanged.","correct":false,"why":"The assignment still happens; the field is set to NULL rather than left alone."},{"id":"D","text":"The search errors at the first event with no matching condition.","correct":false,"why":"No error is raised. A NULL result is normal and simply means no branch matched."}],"answer":["A"],"explanation":"case() needs an explicit default: end it with `true(), \"<default>\"`. Its mirror is validate(), which returns the value for the first condition that is FALSE and defaults to NULL when every condition is TRUE.","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-07"],"read":["topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"authored","note":"Knowing validate() as case()'s mirror is worth a mark on its own, since it is the less familiar of the pair and appears in distractors.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/comparison-and-conditional-functions","title":"Comparison and Conditional functions (SPL Search Reference 10.4)","note":"case() returns NULL if none of the conditions are true; validate() is documented as its opposite.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-07","type":"single","stem":"Why does `... | eval matched = isnull(user)` fail?","options":[{"id":"A","text":"The result of an eval expression cannot be a Boolean.","correct":true,"why":"isnull() returns a Boolean, and eval cannot assign one to a field. Wrap it in if(), case() or validate(), or convert it with tostring()."},{"id":"B","text":"isnull() is a where-only function and is not available to eval.","correct":false,"why":"isnull() is available to eval. The problem is what it returns, not where it lives."},{"id":"C","text":"matched is a reserved field name in Splunk.","correct":false,"why":"There is no such reservation. Any name that is not an existing field simply creates a new one."},{"id":"D","text":"isnull() takes two arguments, so the call is incomplete.","correct":false,"why":"isnull() takes a single field. The call itself is well formed."}],"answer":["A"],"explanation":"The same restriction hits in(), like(), cidrmatch(), searchmatch() and the whole is* family under eval. Under where they are used directly, because where wants a Boolean. `eval matched = if(isnull(user), \"yes\", \"no\")` is the working form.","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-08"],"read":["topics/02-filtering-and-formatting.md#traps"],"verdict":"authored","note":"The eval Usage section states that booleans cannot be assigned to fields, which is the single sentence this whole family of questions rests on.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/eval","title":"eval command (SPL Search Reference 10.4)","note":"Usage: an eval expression cannot return a Boolean value.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-08","type":"single","stem":"A results table has null cells in several columns. What does a bare `| fillnull` do?","options":[{"id":"A","text":"Writes 0 into every null cell of every field.","correct":true,"why":"The default value is 0, and with no field list the command applies to all fields in the result set."},{"id":"B","text":"Writes the string NULL into every null cell of every field.","correct":false,"why":"NULL is not the default. Getting a NULL string requires `fillnull value=NULL`."},{"id":"C","text":"Writes an empty string into every null cell of every field.","correct":false,"why":"An empty string is a common guess but is not documented as the default."},{"id":"D","text":"Copies the last non-null value from the row above.","correct":false,"why":"That is filldown. fillnull writes one constant everywhere; filldown carries a value forward."}],"answer":["A"],"explanation":"Two commands, two behaviours. fillnull writes a constant, defaulting to 0, and takes a plain field list with no wildcard support. filldown copies the last non-null value seen above and takes a wildcard field list.","sec":"2.3","secTitle":"The fillnull command","grp":"2","traps":["T-02-11","T-02-13"],"read":["topics/02-filtering-and-formatting.md#syntax-and-options"],"verdict":"authored","note":"In the syntax, `value=` precedes the field list. Writing the field list first is a common way to get a confusing error.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/fillnull","title":"fillnull command (SPL Search Reference 10.4)","note":"Default value is 0; with no field list it applies to all fields.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-02-09","type":"single","stem":"A search ends with `| fieldformat bytes=tostring(bytes,\"commas\") | sort - bytes | outputcsv report`. What is written to the CSV?","options":[{"id":"A","text":"The original numeric values, sorted numerically.","correct":true,"why":"fieldformat changes rendering only. Both sort and outputcsv see the underlying numeric value, so the sort is numeric and the file holds raw numbers."},{"id":"B","text":"The comma-formatted strings, sorted numerically.","correct":false,"why":"Export commands do not see the formatted value at all, so the commas never reach the file."},{"id":"C","text":"The comma-formatted strings, sorted lexicographically.","correct":false,"why":"This would be true if fieldformat changed the value, but it does not, so neither half happens."},{"id":"D","text":"The original numeric values, sorted lexicographically.","correct":false,"why":"The values stay numeric, so sort orders them numerically rather than as text."}],"answer":["A"],"explanation":"fieldformat is display-only and is invisible to every later command, including outputcsv and outputlookup. Use eval when the change has to persist, and put fieldformat last in the pipeline. It also takes one expression per command.","sec":"2.1","secTitle":"The eval command","grp":"2","traps":["T-02-15","T-02-19"],"read":["topics/02-filtering-and-formatting.md#decision-rules"],"verdict":"authored","note":"tostring() accepts only binary, hex, commas and duration. commas rounds to two decimal places, and there is no currency option, so a symbol has to be concatenated.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/fieldformat","title":"fieldformat command (SPL Search Reference 10.4)","note":"Changes the display of a field without changing its underlying value; export commands see the original.","primary":true},{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/evaluation-functions/conversion-functions","title":"Conversion functions (SPL Search Reference 10.4)","note":"tostring() format options are binary, hex, commas and duration.","primary":false}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-02"],"authored":true},{"id":"sg-03-01","type":"single","stem":"What are the default values of `maxspan`, `maxpause` and `maxevents` on the `transaction` command?","options":[{"id":"A","text":"maxspan -1, maxpause -1, maxevents 1000","correct":true,"why":"maxspan and maxpause default to -1, which deactivates the constraint. maxevents is the only one of the three with a positive default."},{"id":"B","text":"maxspan 30s, maxpause 5m, maxevents 1000","correct":false,"why":"These look like plausible time limits but neither time option has a positive default. Both are off unless you set them."},{"id":"C","text":"maxspan -1, maxpause -1, maxevents -1","correct":false,"why":"Three deactivated constraints would let a transaction grow without bound. maxevents is capped at 1000 by default."},{"id":"D","text":"maxspan 1000, maxpause 1000, maxevents 1000","correct":false,"why":"1000 is the maxevents default only. The two time options are unset."}],"answer":["A"],"explanation":"Only maxevents constrains a transaction by default, at 1000 events. A negative value on any of the three deactivates that constraint, so `maxevents=-1` means no event ceiling rather than no events.","sec":"3.3","secTitle":"Group events using fields and time","grp":"3","traps":["T-03-01","T-03-14"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"authored","note":"The 1000 is a per-search default, not a product ceiling. The real ceilings live in limits.conf as maxopentxn, default 5000, and maxopenevents, default 100000.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"Option table with the defaults for maxspan, maxpause and maxevents.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-02","type":"single","stem":"A transaction groups exactly one event. What is its `duration`?","options":[{"id":"A","text":"0","correct":true,"why":"duration is the difference in seconds between the first and last event timestamps. With one event those are the same timestamp, so the difference is zero."},{"id":"B","text":"NULL, because a duration needs two events","correct":false,"why":"The field is still produced. A single-event transaction has a real duration of zero rather than a missing one."},{"id":"C","text":"1, counted as one event's worth of time","correct":false,"why":"duration measures elapsed seconds, not events. Event count is reported separately in eventcount."},{"id":"D","text":"The event's `_time` value in epoch seconds","correct":false,"why":"That would be an absolute timestamp rather than an elapsed span. duration is always a difference."}],"answer":["A"],"explanation":"duration is in seconds, always, and is the span from the earliest to the latest member event. Convert with eval if you need minutes. The transaction's own `_time` comes from the earliest member event, not the latest.","sec":"3.5","secTitle":"Report on transactions","grp":"3","traps":["T-03-03","T-03-04"],"read":["topics/03-correlating-events.md#result-contract"],"verdict":"authored","note":"A duration of 0 across many rows usually means the search filtered on a term before grouping, so each group contains only the matching events.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"duration is the difference in seconds between the first and last events in the transaction.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-03","type":"single","stem":"Which option, when specified, causes `transaction` to set `closed_txn=1` on completed groups?","options":[{"id":"A","text":"`startswith`","correct":true,"why":"closed_txn is set when one of maxevents, maxspan, maxpause or startswith is specified. startswith is the one boundary option on that list."},{"id":"B","text":"`endswith`","correct":false,"why":"endswith is deliberately absent from the documented list, which is what makes it the most common wrong answer here."},{"id":"C","text":"`keepevicted`","correct":false,"why":"keepevicted decides whether unclosed transactions are output at all; it does not decide how closure is determined."},{"id":"D","text":"`unifyends`","correct":false,"why":"unifyends governs whether events matching the start or end conditions are unified with the group, not closure marking."}],"answer":["A"],"explanation":"The documented list is maxevents, maxspan, maxpause and startswith. If none of those four is given, every transaction is marked closed. endswith on its own does not qualify, despite reading like a closing condition.","sec":"3.3","secTitle":"Group events using fields and time","grp":"3","traps":["T-03-05"],"read":["topics/03-correlating-events.md#traps"],"verdict":"authored","note":"Pair this with keepevicted: transactions left open carry closed_txn=0 and are only returned when keepevicted=true.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"closed_txn is set to 1 only if one of maxevents, maxspan, maxpause or startswith is specified.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-04","type":"single","stem":"Why does `... | transaction clientip | where count > 5` return nothing?","options":[{"id":"A","text":"transaction produces `eventcount`, not `count`.","correct":true,"why":"count is what stats produces. The field that holds the number of events in a transaction is eventcount, so the filter references a field that does not exist."},{"id":"B","text":"where cannot be used after transaction.","correct":false,"why":"where composes with transaction normally. The problem is the field name in the expression."},{"id":"C","text":"transaction only outputs `_raw` and `_time`.","correct":false,"why":"It also adds duration and eventcount, sets closed_txn, and can add _txn_orphan and transactiontype."},{"id":"D","text":"count exists but is a string, so the numeric comparison fails.","correct":false,"why":"The field is absent rather than mistyped. `where eventcount > 5` is the working form."}],"answer":["A"],"explanation":"The two grouping commands name their count differently: stats gives count, transaction gives eventcount. Options such as maxspan, maxpause and maxevents are inputs only and never come back as fields.","sec":"3.5","secTitle":"Report on transactions","grp":"3","traps":["T-03-10","T-03-22"],"read":["topics/03-correlating-events.md#result-contract"],"verdict":"authored","note":"The full output contract: duration and eventcount always, closed_txn set, _txn_orphan only with keeporphans, transactiontype only when a configured transaction type is used.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"The command adds the fields duration and eventcount to each transaction.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-05","type":"single","stem":"A report needs one row per session with the session's event count, running against a large distributed deployment. Which command should be used, and why?","options":[{"id":"A","text":"stats, because it is transforming and runs on the indexers","correct":true,"why":"stats is a transforming command and performs more efficiently, especially in a distributed environment, because the work distributes across indexers."},{"id":"B","text":"transaction, because it produces fewer results","correct":false,"why":"Result count is not the deciding factor, and transaction is a centralized streaming command that only runs on the search head."},{"id":"C","text":"transaction, because stats cannot count events per group","correct":false,"why":"`stats count BY sessionid` does exactly that. Counting per group is stats' core job."},{"id":"D","text":"streamstats, because it is a cheaper stats","correct":false,"why":"streamstats adds running aggregates to each event and returns every event. It never collapses events into groups."}],"answer":["A"],"explanation":"Prefer stats unless you need something only transaction gives you: events physically grouped and kept, a span or pause constraint, or start and end conditions. The documentation recommends stats for performance in distributed environments.","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-09","T-03-24"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"authored","note":"3.6 is the only sub-objective in this section that is a judgement call rather than a recall fact, and it is weighted inside the heaviest section on the blueprint.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-event-grouping-and-correlation","title":"About event grouping and correlation (Search Manual 10.4)","note":"stats is recommended over transaction for performance; transaction runs on the search head only.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-06","type":"single","stem":"Which pair of `stats` functions returns values in chronological order rather than processing order?","options":[{"id":"A","text":"`earliest()` and `latest()`","correct":true,"why":"These are the time-ordered pair. earliest() returns the chronologically oldest value and latest() the newest."},{"id":"B","text":"`first()` and `last()`","correct":false,"why":"These follow processing order. Because results arrive newest first, first() usually returns the most recent value and last() the oldest, which is the reverse of what the names suggest."},{"id":"C","text":"`min()` and `max()`","correct":false,"why":"These compare values, not timestamps. On a numeric field they return the smallest and largest numbers."},{"id":"D","text":"`list()` and `values()`","correct":false,"why":"Both return collections rather than a single value. list() preserves event order and values() sorts lexicographically."}],"answer":["A"],"explanation":"first() and last() are ordered by how results are processed, not by time. Use earliest() and latest() whenever the question is about chronology, which is most of the time in transaction reporting.","sec":"3.5","secTitle":"Report on transactions","grp":"3","traps":["T-03-12"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"authored","note":"The naming is genuinely counter-intuitive, which is exactly why it is examinable. Read first() as \"first one processed\", not \"first in time\".","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/statistical-and-charting-functions/statistical-and-charting-functions","title":"Statistical and charting functions (SPL Search Reference 10.4)","note":"first() and last() are documented against processing order; earliest() and latest() against time.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-07","type":"single","stem":"How do `values()` and `list()` differ?","options":[{"id":"A","text":"values() returns distinct values sorted lexicographically; list() returns every value in event order and stops at 100.","correct":true,"why":"Both parts matter. values() deduplicates and sorts, list() keeps duplicates and order but silently truncates at 100 values."},{"id":"B","text":"They are the same function under two names.","correct":false,"why":"They differ in deduplication, ordering and whether a cap applies."},{"id":"C","text":"values() keeps duplicates; list() removes them.","correct":false,"why":"This is exactly backwards. values() is the deduplicating one."},{"id":"D","text":"list() sorts lexicographically; values() preserves event order.","correct":false,"why":"Also reversed. values() sorts, list() preserves order."}],"answer":["A"],"explanation":"values() returns distinct values in lexicographical order with no documented cap. list() returns all values in the order the events arrived and returns only the first 100 if a field has more than 100 values.","sec":"3.5","secTitle":"Report on transactions","grp":"3","traps":["T-03-13"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"authored","note":"The 100-value cap on list() is the detail most often missed, and it makes list() unsafe for anything you intend to count.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/statistical-and-charting-functions/statistical-and-charting-functions","title":"Statistical and charting functions (SPL Search Reference 10.4)","note":"list() returns only the first 100 values of a field; values() returns distinct values in lexicographical order.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-08","type":"single","stem":"What is the default of `mvlist` on `transaction`, and what does that default produce?","options":[{"id":"A","text":"false, rendering multivalue fields as a set of unique values in alphabetical order","correct":true,"why":"With mvlist=false, which is the default, duplicate values collapse and the remaining values are ordered alphabetically."},{"id":"B","text":"true, rendering multivalue fields as the original event values in arrival order","correct":false,"why":"That is what mvlist=true does, but it is not the default. You have to ask for it."},{"id":"C","text":"false, suppressing multivalue fields entirely","correct":false,"why":"Nothing is suppressed. The values are deduplicated and sorted, not removed."},{"id":"D","text":"true, and it cannot be changed on a per-search basis","correct":false,"why":"The default is false, and the option is settable per search like every other transaction option."}],"answer":["A"],"explanation":"mvlist=false deduplicates and alphabetises. mvlist=true preserves the original values and their order, which is what you want when the sequence of events inside a transaction is the thing you are analysing.","sec":"3.4","secTitle":"Search with transactions","grp":"3","traps":["T-03-07"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"authored","note":"A related default to keep straight: unifyends inherits its default from connected, so setting connected=false also makes unifyends false.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"mvlist option, default false, controls unique-and-sorted versus original-order rendering.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-09","type":"single","stem":"What kind of value do `startswith` and `endswith` accept?","options":[{"id":"A","text":"A search expression, a quoted search expression in parentheses, or `eval(<expression>)` returning a Boolean","correct":true,"why":"These are the three documented filter-string forms. A regular expression is only usable inside the eval form, via match()."},{"id":"B","text":"A regular expression, applied against `_raw`","correct":false,"why":"They are not regex arguments. Getting regex behaviour requires wrapping it: `startswith=eval(match(_raw, \"...\"))`."},{"id":"C","text":"A field name whose presence opens or closes the transaction","correct":false,"why":"A bare field name is not the documented form. The value is a filter expression, not a field reference."},{"id":"D","text":"An epoch timestamp marking the boundary","correct":false,"why":"Time boundaries are the job of maxspan and maxpause, not of the start and end conditions."}],"answer":["A"],"explanation":"The documented type is a filter-string. Plain search syntax works, parenthesised quoted search syntax works, and eval() with a Boolean expression works. Regex only reaches these options through eval(match(...)).","sec":"3.3","secTitle":"Group events using fields and time","grp":"3","traps":["T-03-15"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"authored","note":"Remember that specifying startswith affects closed_txn marking while specifying endswith does not.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"startswith and endswith take a <filter-string>, defined as search or eval syntax.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-10","type":"single","stem":"What is the difference between `keepevicted=true` and `keeporphans=true`?","options":[{"id":"A","text":"keepevicted outputs transactions left open, marked `closed_txn=0`; keeporphans outputs events that joined no transaction, marked `_txn_orphan=1`.","correct":true,"why":"Two different populations. Evicted means an incomplete group; orphaned means an event that never became part of any group."},{"id":"B","text":"They are two names for the same option.","correct":false,"why":"They output different things and set different marker fields."},{"id":"C","text":"keepevicted keeps orphan events; keeporphans keeps unclosed transactions.","correct":false,"why":"The two are swapped here."},{"id":"D","text":"keepevicted marks results with `orphan=1`; keeporphans marks them with `closed_txn=0`.","correct":false,"why":"The marker fields are also swapped, and there is no field called orphan. The field is _txn_orphan."}],"answer":["A"],"explanation":"Both default to false. keepevicted returns groups that memory pressure or a missing close condition left open, identifiable by closed_txn=0. keeporphans returns individual events that belonged to no transaction, identifiable by _txn_orphan=1.","sec":"3.4","secTitle":"Search with transactions","grp":"3","traps":["T-03-20","T-03-06"],"read":["topics/03-correlating-events.md#syntax-and-options"],"verdict":"authored","note":"The underscore in _txn_orphan matters. Distractors routinely offer a plain orphan field, which does not exist.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"keepevicted and keeporphans option descriptions with their marker fields.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-11","type":"single","stem":"A search appends a second dataset and then needs to group the combined results by `sessionid`. What is the constraint?","options":[{"id":"A","text":"transaction cannot be used after append; use stats to group instead.","correct":true,"why":"This is a documented restriction. stats is the supported way to group after an append."},{"id":"B","text":"append cannot be followed by any transforming command.","correct":false,"why":"stats, chart and timechart all work after append. The restriction is specific to transaction."},{"id":"C","text":"transaction works but silently ignores events from the appended set.","correct":false,"why":"The combination is not supported rather than partially supported."},{"id":"D","text":"There is no constraint; the two compose freely.","correct":false,"why":"They do not. This is one of the few explicit command-ordering restrictions in SPL."}],"answer":["A"],"explanation":"transaction after append is not supported. This reinforces the general lesson of 3.6: stats is the more composable grouping command, and transaction is the special case you reach for only when you need its specific behaviour.","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-11"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"authored","note":"transaction also requires its input in descending chronological order, so any sort has to sit immediately before it.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"Usage: you cannot use the transaction command after the append command.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-12","type":"single","stem":"By default, how many subsearch results will `join` match against each main-search result?","options":[{"id":"A","text":"1","correct":true,"why":"join defaults to max=1, so only the first matching row from the right-hand dataset is used. `max=0` removes the limit."},{"id":"B","text":"All of them","correct":false,"why":"That is the SQL expectation and the reason join surprises people. You have to set max=0 to get it."},{"id":"C","text":"10","correct":false,"why":"There is no ten-row default on join. Ten is the default series limit on chart and timechart."},{"id":"D","text":"50,000","correct":false,"why":"50,000 is the default maximum size of the right-hand dataset, not the number matched per row."}],"answer":["A"],"explanation":"join is the correlation command most likely to give quietly wrong answers: max defaults to 1, the right-hand dataset is capped at 50,000 rows, and it has a default runtime limit of 60 seconds. The documentation recommends stats for most correlation work.","sec":"3.2","secTitle":"Group events using fields","grp":"3","traps":["T-03-17"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"authored","note":"Silent truncation is the danger. A join that returns too few rows looks like a data problem rather than a default.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/join","title":"join command (SPL Search Reference 10.4)","note":"max default is 1; the subsearch is subject to result-count and runtime limits.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-13","type":"multi","stem":"Which two behaviours require `transaction` rather than `stats`? (Choose two.)","options":[{"id":"A","text":"Grouping events that must fall within a maximum elapsed span of each other","correct":true,"why":"maxspan and maxpause have no equivalent in stats. Time-bounded grouping is transaction's distinctive capability."},{"id":"B","text":"Keeping the original events inside each group so their raw text stays available","correct":true,"why":"transaction produces groups of events and preserves _raw. stats produces a statistics table and discards _raw."},{"id":"C","text":"Counting how many events share a field value","correct":false,"why":"`stats count BY field` does this and does it faster, because stats distributes across indexers."},{"id":"D","text":"Producing one row per unique combination of two fields","correct":false,"why":"That is exactly what `stats ... BY fieldA fieldB` produces, and it is the standard approach."}],"answer":["A","B"],"explanation":"Reach for transaction when you need time constraints, start and end conditions, or the events themselves preserved as a group. For plain counting and aggregation by field value, stats is both simpler and faster.","sec":"3.6","secTitle":"Determine when to use transactions vs. stats","grp":"3","traps":["T-03-09"],"read":["topics/03-correlating-events.md#decision-rules"],"verdict":"authored","note":"Because stats does not pass _raw down the pipeline, a later bare-keyword search after stats has nothing to match against.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-manual/10.4/group-and-correlate-events/about-transactions","title":"About transactions (Search Manual 10.4)","note":"When a transaction is the right tool versus aggregation with stats.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-03-14","type":"single","stem":"`... | transaction host cookie` is run. How does Splunk treat the two fields?","options":[{"id":"A","text":"Not necessarily as a strict AND or OR; a transitive relationship across events can join them into one transaction.","correct":true,"why":"The documentation states multiple fields are not necessarily interpreted as a conjunction or a disjunction. If a transitive relationship exists and events appear in the right sequence, transaction uses it."},{"id":"B","text":"As a strict conjunction: both host and cookie must match.","correct":false,"why":"This is the intuitive reading and the documented warning is aimed precisely at it."},{"id":"C","text":"As a strict disjunction: either field matching is enough.","correct":false,"why":"Equally definite and equally wrong. The behaviour is not fixed to either operator."},{"id":"D","text":"Only the first field is used; the second is ignored.","correct":false,"why":"Both participate in grouping. Neither is discarded."}],"answer":["A"],"explanation":"A multi-field transaction can chain events transitively: event 1 and 2 share a host, event 2 and 3 share a cookie, and all three end up in one transaction. This is why multi-field transactions can produce surprisingly large groups.","sec":"3.2","secTitle":"Group events using fields","grp":"3","traps":["T-03-16"],"read":["topics/03-correlating-events.md#traps"],"verdict":"authored","note":"This is the behaviour connected=false is designed to constrain, and connected is only relevant when a field or field list is specified.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/transaction","title":"transaction command (SPL Search Reference 10.4)","note":"Usage: multiple fields are not necessarily interpreted as a conjunction or disjunction; transitive relationships are used.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-03"],"authored":true},{"id":"sg-04-01","type":"single","stem":"A field extraction is saved with the Field Extractor. Which events does it apply to?","options":[{"id":"A","text":"Every already-indexed event of that source type or source, and all future ones, with no reindex needed.","correct":true,"why":"The Field Extractor creates a search-time extraction. It runs when a search runs, so it applies retroactively and needs neither a reindex nor a restart."},{"id":"B","text":"Only events indexed from that point forward.","correct":false,"why":"That would be index-time behaviour. Search-time extractions are evaluated against data already on disk."},{"id":"C","text":"Every already-indexed event, but only after the index is rebuilt.","correct":false,"why":"No reindex is involved. Nothing is rewritten on disk."},{"id":"D","text":"Only events returned by the search that was open when the extraction was created.","correct":false,"why":"The extraction is a knowledge object scoped to a source type or source, not to one search."}],"answer":["A"],"explanation":"Everything the Field Extractor builds is search-time. This is the single most useful fact in section 4.0, because it rules out any answer mentioning reindexing, restarts, or forward-only application.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-01"],"read":["topics/04-field-extractions.md#what-it-is"],"verdict":"authored","note":"Contrast with rex, which is a search command rather than a knowledge object: its fields last for one pipeline and appear nowhere in Settings.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/build-field-extractions-with-the-field-extractor","title":"Build field extractions with the field extractor (Knowledge Management 10.4)","note":"The field extractor generates search-time field extractions.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-02","type":"single","stem":"At the Save step of the Field Extractor, what is the default permission, and what does it mean?","options":[{"id":"A","text":"Owner, meaning the extraction only runs in searches by the person who created it.","correct":true,"why":"Owner is the default of the three choices, and the documentation states it only extracts fields in searches run by the creator."},{"id":"B","text":"App, meaning everyone using the current app sees the fields.","correct":false,"why":"App is one of the three choices but it is not the default. Sharing is a deliberate step."},{"id":"C","text":"All apps, meaning the extraction is global immediately.","correct":false,"why":"This is the widest of the three options and is furthest from the default."},{"id":"D","text":"There is no permission choice at the Save step; permissions are set later under Settings.","correct":false,"why":"The choice is offered at Save. It can also be changed later, but it is present in the wizard."}],"answer":["A"],"explanation":"The three choices are Owner, App and All apps, and the default is Owner. A colleague reporting that they cannot see your new field is almost always this default rather than a broken extraction.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-04"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"authored","note":"The same private-by-default rule governs field aliases and calculated fields, so it is worth learning once and applying across sections 4.0 and 5.0.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-save-step","title":"Field extractor: Save step (Knowledge Management 10.4)","note":"Permissions default to Owner; the choices are Owner, App, All apps.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-03","type":"single","stem":"Which Field Extractor step exists only on the regular expression path and not on the delimiter path?","options":[{"id":"A","text":"Validate","correct":true,"why":"The regex path runs Select Sample, Select Method, Select Fields, Validate, Save. The delimiter path has no Validate step."},{"id":"B","text":"Select Method","correct":false,"why":"Both paths pass through Select Method; that is where the two paths diverge."},{"id":"C","text":"Save","correct":false,"why":"Both paths end at Save."},{"id":"D","text":"Select Sample","correct":false,"why":"Both paths start at Select Sample, unless the wizard was opened from Event Actions on a specific event."}],"answer":["A"],"explanation":"Regex path: Select Sample, Select Method, Select Fields, Validate, Save. Delimiter path: Select Sample, Select Method, Rename Fields, Save. Anything that lives on the Validate step, such as counterexamples, exists only for regex extractions.","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-03","T-04-16"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"authored","note":"Opening the extractor from Event Actions, Extract Fields on a specific event starts at Select Method, because the source type and sample are already decided.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-select-method-step","title":"Field extractor: Select Method step (Knowledge Management 10.4)","note":"The two method paths and the steps each one visits.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-04","type":"single","stem":"When should the Delimiters method be chosen over the Regular Expression method?","options":[{"id":"A","text":"When values are cleanly separated by a common character and are consistent across events, as in CSV-style data.","correct":true,"why":"The documentation describes the delimiters method as designed for structured, table-based data where all fields are separated by a common delimiter."},{"id":"B","text":"When the data is unstructured and the field positions vary between events.","correct":false,"why":"Varying structure is precisely the case for a regular expression. Delimiters need consistency."},{"id":"C","text":"When the events contain no repeating patterns at all.","correct":false,"why":"Delimited data is highly repetitive by definition; that repetition is what makes the method work."},{"id":"D","text":"When the fields must be extracted at index time rather than search time.","correct":false,"why":"Both methods produce search-time extractions. Neither touches index time."}],"answer":["A"],"explanation":"Delimiters are for structured, table-based data. The reversed claim, that delimiters are for data without headers or for unstructured data, appears repeatedly in third-party study material and is wrong.","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-15","T-04-19"],"read":["topics/04-field-extractions.md#decision-rules"],"verdict":"authored","note":"The Udemy practice course states the reverse of this five separate times, which is recorded in the fact-check. Answer from the Select Method page.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-select-method-step","title":"Field extractor: Select Method step (Knowledge Management 10.4)","note":"Delimiters suit structured data such as .csv files or events with a common separator.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-05","type":"single","stem":"Which field does the `rex` command read from when no `field=` argument is given?","options":[{"id":"A","text":"`_raw`","correct":true,"why":"field defaults to _raw on rex. erex has the same default under a different option name, fromfield."},{"id":"B","text":"`_time`","correct":false,"why":"_time holds the event timestamp and is not a text field to run a pattern against."},{"id":"C","text":"The first field in the Selected Fields list","correct":false,"why":"The sidebar's field selection is a display concern and has no bearing on command defaults."},{"id":"D","text":"There is no default; `field=` is required.","correct":false,"why":"It is optional. The command with no field argument is valid and very common."}],"answer":["A"],"explanation":"rex takes an optional field, defaulting to _raw. erex takes fromfield, also defaulting to _raw. extract has neither and can only read _raw, which is why extracting from a substring requires renaming that field to _raw first.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-08","T-04-12"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"authored","note":"The documented workaround for extract is `rename _raw AS temp uri_query AS _raw`, then extract, then rename back.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/rex","title":"rex command (SPL Search Reference 10.4)","note":"field option, default _raw.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-06","type":"single","stem":"What is the default of `max_match` on `rex`, and what does `max_match=0` mean?","options":[{"id":"A","text":"Default 1; 0 means unlimited matches.","correct":true,"why":"Only the first match is kept by default. Setting 0 removes the cap, and any value above 1 produces a multivalue field."},{"id":"B","text":"Default 1; 0 means no matches are kept.","correct":false,"why":"Zero means unlimited here, exactly as it does for limit on chart and top."},{"id":"C","text":"Default 0, meaning unlimited unless restricted.","correct":false,"why":"The default is restrictive, not permissive. One match is kept unless you ask for more."},{"id":"D","text":"Default 10, matching the general series limit.","correct":false,"why":"There is no ten-match default. Ten is the series limit on chart and timechart."}],"answer":["A"],"explanation":"max_match defaults to 1, so a pattern that could match several times per event quietly keeps only the first. Raising it above 1 produces a multivalue field, and 0 means unlimited.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-09"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"authored","note":"A related subtlety: if a capture group can match repeatedly within itself, only the last capture is kept regardless of max_match.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/rex","title":"rex command (SPL Search Reference 10.4)","note":"max_match option: default 1, 0 means unlimited.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-07","type":"single","stem":"What determines whether a field appears under Interesting Fields in the fields sidebar?","options":[{"id":"A","text":"It appears in at least 20 percent of the events returned by the current search.","correct":true,"why":"The threshold is measured against the events this search returned, so changing the search changes the list."},{"id":"B","text":"It appears in at least 20 percent of the events in the index.","correct":false,"why":"The denominator is the current result set, not the index. This is the most common misreading."},{"id":"C","text":"It appears in at least 20 percent of the events of that source type.","correct":false,"why":"Source type is not the denominator either. The measure is per search."},{"id":"D","text":"Splunk has classified it as important based on how often it is searched.","correct":false,"why":"There is no usage-based ranking involved. It is a mechanical percentage."}],"answer":["A"],"explanation":"Interesting Fields is a display rule for the sidebar only. A field present in 5 percent of events is fully extracted and fully searchable; it simply does not clear the bar for that list.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-07","T-04-21"],"read":["topics/04-field-extractions.md#what-it-is"],"verdict":"authored","note":"On a fresh search, Selected Fields contains exactly host, source and sourcetype. index is a default field on every event, so it clears the bar and appears under Interesting Fields.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/search-tutorial/10.4/part-4-searching-the-tutorial-data/use-fields-to-search","title":"Use fields to search (Search Tutorial 10.4)","note":"Interesting Fields lists fields appearing in at least 20 percent of the returned events.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-08","type":"multi","stem":"Which two statements about case sensitivity in field extraction and search are true? (Choose two.)","options":[{"id":"A","text":"Field names are case sensitive.","correct":true,"why":"`sourcetype=x` and `SOURCETYPE=x` are different searches, and only the lowercase form matches the real field."},{"id":"B","text":"Field values are not case sensitive in the search command.","correct":true,"why":"`status=Failed` matches an event whose stored value is failed."},{"id":"C","text":"Regular expressions in an extraction are case insensitive by default.","correct":false,"why":"Splunk regular expressions are case sensitive unless the pattern says otherwise, for example with an inline (?i) flag."},{"id":"D","text":"Field names and values are both case insensitive at search time.","correct":false,"why":"Names are case sensitive. Treating both the same way is the error the exam probes."}],"answer":["A","B"],"explanation":"Names are case sensitive, values are not, and the exception is that eval and where expressions are case sensitive throughout. That three-part rule covers nearly every case-sensitivity question on this exam.","sec":"4.1","secTitle":"Perform regex field extractions using the Field Extractor (FX)","grp":"4","traps":["T-04-05"],"read":["topics/04-field-extractions.md#traps"],"verdict":"authored","note":"Whether tag names are case sensitive is genuinely unsettled in the 10.4 documentation, which is why three questions in the transcribed practice bank are marked disputed and excluded from mock exams.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/search","title":"search command (SPL Search Reference 10.4)","note":"Field names are case sensitive; field values are not.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-04-09","type":"single","stem":"A delimiter extraction discovers six fields. How many must be renamed before the wizard will let you save?","options":[{"id":"A","text":"At least one; the rest keep names such as field1 and field2.","correct":true,"why":"You must select and rename at least one field to reach Save. Unrenamed fields keep their auto-assigned names."},{"id":"B","text":"All six.","correct":false,"why":"Renaming everything is good practice but is not enforced by the wizard."},{"id":"C","text":"None; renaming is entirely optional.","correct":false,"why":"At least one rename is required to progress, so it is not fully optional."},{"id":"D","text":"Exactly half, so the extraction has a mix of named and generated fields.","correct":false,"why":"There is no proportional rule of any kind."}],"answer":["A"],"explanation":"One rename is the minimum to reach Save. Worth pairing with what each method writes: the regex method writes an inline EXTRACT- stanza into props.conf, while the delimiter method writes a transforms.conf stanza holding DELIMS and FIELDS.","sec":"4.2","secTitle":"Perform delimiter field extractions using the FX","grp":"4","traps":["T-04-13","T-04-14","T-04-22"],"read":["topics/04-field-extractions.md#syntax-and-options"],"verdict":"authored","note":"The Rename Fields step offers four delimiter presets, Space, Comma, Tab and Pipe. Anything else, such as a colon or semicolon, has to be typed into the Other box.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-the-field-extractor-in-splunk-web/field-extractor-rename-fields-step","title":"Field extractor: Rename Fields step (Knowledge Management 10.4)","note":"At least one field must be renamed; presets are Space, Comma, Tab, Pipe and Other.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-04"],"authored":true},{"id":"sg-05-01","type":"single","stem":"`clientip` is aliased to `src_ip`. What does `clientip=*` return afterwards?","options":[{"id":"A","text":"The same events as before; both names now work.","correct":true,"why":"An alias is added alongside the original field. It does not replace or remove anything, so both names are searchable."},{"id":"B","text":"Nothing, because the field is now called src_ip.","correct":false,"why":"This assumes aliasing renames. It does not. Renaming is what the rename command does."},{"id":"C","text":"Only events indexed before the alias was created.","correct":false,"why":"Aliases apply at search time to all matching events regardless of when they were indexed."},{"id":"D","text":"An error, because the field has been superseded.","correct":false,"why":"No error occurs. Nothing about the original field changed."}],"answer":["A"],"explanation":"An alias adds a second name for a field. The command that actually replaces a name is rename, and it only affects the result set of the one search it appears in.","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-01","T-05-02"],"read":["topics/05-aliases-and-calculated-fields.md#what-it-is"],"verdict":"authored","note":"An alias is a knowledge object evaluated at step 5 of the nine search-time operations. rename is a search command operating downstream of all nine.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/create-field-aliases-in-splunk-web","title":"Create field aliases in Splunk Web (Knowledge Management 10.4)","note":"A field alias does not replace or remove the original field name.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-02","type":"single","stem":"Two source fields, `userID` and `loginID`, should both be reachable as `user`. What does the documentation say about `FIELDALIAS-x = userID AS user loginID AS user`?","options":[{"id":"A","text":"It is invalid; a single alias can only apply to one field, so only one of the two takes effect.","correct":true,"why":"A field can have multiple aliases, but an alias name cannot be the destination for two different source fields in this way."},{"id":"B","text":"It is valid and merges both source fields into user.","correct":false,"why":"This is the intuitive expectation and it is the documented failure case."},{"id":"C","text":"It is valid but the second alias overwrites the first on every event.","correct":false,"why":"The configuration is not supported, so describing a deterministic overwrite rule misstates it."},{"id":"D","text":"It is valid only when both source fields are present on the same event.","correct":false,"why":"Co-presence is not the issue. The configuration itself is documented as invalid."}],"answer":["A"],"explanation":"Aliases are one-to-many, not many-to-one: one field can carry several alias names, but one alias name cannot collect several fields. The documented way to merge two fields into one is a calculated field using coalesce().","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-03"],"read":["topics/05-aliases-and-calculated-fields.md#traps"],"verdict":"authored","note":"The working alternative is `EVAL-user = coalesce(userID, loginID)`, which is a calculated field and therefore runs at step 6, after aliasing at step 5.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/configure-field-aliases-with-props.conf","title":"Configure field aliases with props.conf (Knowledge Management 10.4)","note":"A single field alias can only apply to one field.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-03","type":"single","stem":"Can a calculated field's eval expression reference a field added by an automatic lookup?","options":[{"id":"A","text":"No. Calculated fields are evaluated before lookups in the search-time sequence.","correct":true,"why":"Calculated fields run at step 6 and lookups at step 7, so the lookup output does not exist yet when the calculated field is evaluated."},{"id":"B","text":"Yes, as long as the lookup is defined in the same app.","correct":false,"why":"App scope has no bearing on ordering. The sequence is fixed regardless of where the objects live."},{"id":"C","text":"Yes, because all search-time knowledge objects are evaluated together.","correct":false,"why":"They are evaluated in a defined order, not simultaneously. That order is the whole point of this objective."},{"id":"D","text":"Only if the lookup is configured as a non-automatic lookup.","correct":false,"why":"A manual lookup runs even later, as a search command, so it is further out of reach rather than closer."}],"answer":["A"],"explanation":"Calculated fields can reference field extractions of every kind, but not lookups, event types or tags, because all three come later in the sequence. The order is worth memorising as the backbone of sections 4, 5, 6 and 9.","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-05"],"read":["reference/knowledge-object-precedence.md"],"verdict":"authored","note":"The nine search-time operations in order: field filters, EXTRACT-, REPORT-, KV_MODE, FIELDALIAS-, EVAL-, LOOKUP-, event types, tags.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Management 10.4)","note":"Calculated fields precede lookups, event types and tags.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-04","type":"single","stem":"A calculated field `EVAL-duration_ms` exists. Can it be given the CIM name `duration` by aliasing it?","options":[{"id":"A","text":"No. Aliasing happens before calculated fields are evaluated, and the spec states you cannot alias a calculated field.","correct":true,"why":"Aliasing is step 5 and calculated fields are step 6, so at aliasing time duration_ms does not yet exist."},{"id":"B","text":"Yes, provided the alias is defined in the same props.conf stanza.","correct":false,"why":"Same-stanza placement does not change the order in which the two operations run."},{"id":"C","text":"Yes, because aliases are resolved last, after all field creation.","correct":false,"why":"Aliases are resolved at step 5, not last. Tags are the final step."},{"id":"D","text":"Only if the calculated field is marked as a permanent field.","correct":false,"why":"There is no such marking. Calculated fields exist only at search time."}],"answer":["A"],"explanation":"Give the calculated field the name you want in the first place, or add a second calculated field. The general rule is directional: a calculated field can consume aliases, but an alias cannot consume a calculated field.","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-06"],"read":["topics/05-aliases-and-calculated-fields.md#traps"],"verdict":"authored","note":"A related restriction: creating a calculated field on an aliased source is not supported, and a calculated field cannot be scoped to an aliased host, source or source type.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/props.conf","title":"props.conf spec (Admin Manual 10.4)","note":"You cannot alias a calculated field.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-05","type":"single","stem":"A props.conf stanza contains `EVAL-response_time = response_time/1000` and `EVAL-bitrate = bytes*1000/response_time`. What value of `response_time` does the bitrate calculation use?","options":[{"id":"A","text":"The original extracted value, because all EVAL- settings in a stanza are processed in parallel.","correct":true,"why":"The documentation states EVAL- configurations within a single props.conf stanza are processed in parallel rather than sequentially, so one cannot consume another's output."},{"id":"B","text":"The converted value, because the settings run in the order written.","correct":false,"why":"Order in the file does not create a dependency chain. Parallel evaluation is explicit in the spec."},{"id":"C","text":"The converted value, because Splunk resolves dependencies automatically.","correct":false,"why":"No dependency resolution takes place between calculated fields in the same stanza."},{"id":"D","text":"Neither; the configuration errors because response_time is defined twice.","correct":false,"why":"Overriding an extracted field with a calculated field of the same name is allowed and does not error."}],"answer":["A"],"explanation":"Calculated fields cannot chain within one stanza. Each EVAL- sees the field values as they were before any calculated field ran, so a calculation that depends on another has to be written out in full.","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-07"],"read":["topics/05-aliases-and-calculated-fields.md#traps"],"verdict":"authored","note":"The exact wording is worth remembering: all EVAL-<fieldname> configurations within a single props.conf stanza are processed in parallel instead of sequentially.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/configure-calculated-fields-with-props.conf","title":"Configure calculated fields with props.conf (Knowledge Management 10.4)","note":"EVAL- settings in one stanza are processed in parallel, not sequentially.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-06","type":"single","stem":"In the Splunk Web form for a calculated field, what goes into the Eval Expression box?","options":[{"id":"A","text":"The right-hand side only, for example `round(bytes/1024, 2)`","correct":true,"why":"The field name is a separate form field, so the expression box holds the expression alone: no eval keyword and no assignment."},{"id":"B","text":"A full command, for example `eval kb = round(bytes/1024, 2)`","correct":false,"why":"The leading eval keyword belongs to the search command, not to the configuration form."},{"id":"C","text":"An assignment without the keyword, for example `kb = round(bytes/1024, 2)`","correct":false,"why":"The name is supplied separately, so repeating it in the expression is wrong."},{"id":"D","text":"A regular expression that matches the value to calculate","correct":false,"why":"Regular expressions belong to field extractions. A calculated field takes an eval expression."}],"answer":["A"],"explanation":"The Name box supplies the <fieldname> portion of EVAL-<fieldname> and the Eval Expression box supplies everything to the right of the equals sign. Both the alias form and the calculated field form scope to a host, a source, or a source type, and nothing else.","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-08","T-05-11"],"read":["topics/05-aliases-and-calculated-fields.md#syntax-and-options"],"verdict":"authored","note":"The conf settings are FIELDALIAS-<class> and EVAL-<fieldname>, both in props.conf. There is no ALIAS- or CALC- setting, despite both appearing in distractors.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Management 10.4)","note":"The Splunk Web form separates the field name from the eval expression.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-07","type":"single","stem":"A source type already extracts a `status` field. A calculated field `EVAL-status` is then defined for the same source type. What happens?","options":[{"id":"A","text":"The calculated field overrides the extracted field, even when its expression evaluates to null.","correct":true,"why":"The override is unconditional. A null result replaces a perfectly good extracted value, which is the failure mode this rule exists to warn about."},{"id":"B","text":"The calculated field fills in only the events where status was not extracted.","correct":false,"why":"That gap-filling behaviour has to be written explicitly with coalesce()."},{"id":"C","text":"The extracted field wins, because extraction happens earlier in the sequence.","correct":false,"why":"Running earlier does not confer precedence here. The later calculated field overwrites the value."},{"id":"D","text":"Both fields exist, as a multivalue field with two values.","correct":false,"why":"No multivalue field is produced. One value replaces the other."}],"answer":["A"],"explanation":"To preserve the extraction where it exists, write `EVAL-status = coalesce(status, <expression>)`. Without coalesce, an expression that returns null on some events silently deletes good data on those events.","sec":"5.2","secTitle":"Describe, create, and use calculated fields","grp":"5","traps":["T-05-09"],"read":["topics/05-aliases-and-calculated-fields.md#traps"],"verdict":"authored","note":"This is the practical reason calculated fields are riskier than they look: they are not additive by default.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/calculated-fields/about-calculated-fields","title":"About calculated fields (Knowledge Management 10.4)","note":"A calculated field overrides an extracted field of the same name, including when the expression is null.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-08","type":"single","stem":"Who can use a field alias immediately after it is created in Splunk Web?","options":[{"id":"A","text":"Only the person who created it, until it is explicitly shared.","correct":true,"why":"Knowledge objects are private on creation. Sharing to an app or globally is a separate step under Settings, Fields, then Permissions."},{"id":"B","text":"Everyone in the app where it was created.","correct":false,"why":"App-level visibility requires sharing it to the app, which does not happen automatically."},{"id":"C","text":"Everyone on the deployment, since aliases are global objects.","correct":false,"why":"Nothing about aliases makes them global by nature. They follow the same permission model as other knowledge objects."},{"id":"D","text":"Everyone with the same role as the creator.","correct":false,"why":"Role membership is not the sharing mechanism. Permissions are set per object."}],"answer":["A"],"explanation":"Private by default is the rule across knowledge objects: field extractions, aliases, calculated fields, event types, macros and workflow actions all start as Owner-scoped, and sharing is a deliberate second step.","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-14"],"read":["topics/05-aliases-and-calculated-fields.md#syntax-and-options"],"verdict":"authored","note":"Objects shared only at app level are invisible to users working in a different app context until they are promoted to All apps.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/manage-knowledge-object-permissions","title":"Manage knowledge object permissions (Knowledge Management 10.4)","note":"Knowledge objects are private to their creator until shared.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-05-09","type":"single","stem":"The same field name appears in events from two different source types and needs the same alias in both. How many field alias configurations are required?","options":[{"id":"A","text":"Two, because each alias is specific to a host, source, or source type.","correct":true,"why":"Alias scope follows the props.conf stanza model, so a second source type needs its own definition."},{"id":"B","text":"One, because aliases are keyed on the field name.","correct":false,"why":"Aliases are not global by field name. They are scoped like every other props.conf setting."},{"id":"C","text":"One, provided both source types are in the same index.","correct":false,"why":"Index is not a scope for aliasing at all."},{"id":"D","text":"It depends on whether the two source types share a host.","correct":false,"why":"Host is an alternative scope, not a modifier of source type scope."}],"answer":["A"],"explanation":"Host, source, source type. That triple is the scope for field aliases, calculated fields and every other props.conf-driven setting. Index is never a scope, which rules out a whole family of distractors.","sec":"5.1","secTitle":"Describe, create, and use field aliases","grp":"5","traps":["T-05-16","T-05-11"],"read":["topics/05-aliases-and-calculated-fields.md#decision-rules"],"verdict":"authored","note":"The docs also warn against aliasing a field to the name of an internal field such as _time, because it produces unpredictable search results.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/field-aliases/configure-field-aliases-with-props.conf","title":"Configure field aliases with props.conf (Knowledge Management 10.4)","note":"Each field alias configuration is specific to events from a particular host, source, or source type.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-05"],"authored":true},{"id":"sg-06-01","type":"single","stem":"What does a tag attach to?","options":[{"id":"A","text":"A field-value pair, such as `host=web01`","correct":true,"why":"Tags are applied to a specific value of a specific field. An event picks the tag up only because it carries that pair."},{"id":"B","text":"An event","correct":false,"why":"Events acquire tags indirectly. Nothing is attached to the event itself."},{"id":"C","text":"A field, regardless of its value","correct":false,"why":"Tagging a whole field would apply the label to every value it holds. Tags are value-specific."},{"id":"D","text":"A source type","correct":false,"why":"You can tag `sourcetype=secure`, but that is still a field-value pair rather than the source type as an object."}],"answer":["A"],"explanation":"A tag always names a pair. `host=web01`, `sourcetype=secure`, `status=404` and `eventtype=failed_login` are all taggable. This is why tagging is the standard remedy when a host value changes: the old and new values can carry the same tag.","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-01","T-06-14"],"read":["topics/06-tags-and-event-types.md#what-it-is"],"verdict":"authored","note":"Tagging never changes the underlying value. It adds a searchable alternate label alongside it.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in search (Knowledge Management 10.4)","note":"Tags are assigned to field-value pairs.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-02","type":"single","stem":"Which search finds events where the tag `webserver` is applied specifically to the `host` field?","options":[{"id":"A","text":"`tag::host=webserver`","correct":true,"why":"The field-scoped form uses exactly two colons between tag and the field name, with no spaces."},{"id":"B","text":"`tag:host=webserver`","correct":false,"why":"One colon is not the documented syntax. It is the single most common way to get this wrong."},{"id":"C","text":"`tags::host=webserver`","correct":false,"why":"The pseudo-field is singular. There is no tags field."},{"id":"D","text":"`tag.host=webserver`","correct":false,"why":"A dot is not a valid separator here. Splunk would read this as a field literally named tag.host."}],"answer":["A"],"explanation":"Two forms exist. `tag=<tagname>` searches every tagged field-value pair regardless of field, and `tag::<field>=<tagname>` scopes the search to one field. Both accept the wildcard.","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-02","T-06-15"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"authored","note":"The unscoped form is `tag=` and not `tags=`. A question in the transcribed practice bank keys `tags=` as correct, which the documentation contradicts.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in search (Knowledge Management 10.4)","note":"Search syntax tag=<tagname> and tag::<field>=<tagname>.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-03","type":"single","stem":"Which of the following disqualifies a search string from being saved as an event type?","options":[{"id":"A","text":"It contains a pipe operator after the initial search.","correct":true,"why":"The documentation forbids an event type definition that includes a pipe after a simple search, and position in the string does not rescue it."},{"id":"B","text":"It contains more than one field-value pair.","correct":false,"why":"Multiple field-value pairs joined with Boolean operators are perfectly normal in an event type."},{"id":"C","text":"It uses a wildcard in a field value.","correct":false,"why":"Wildcards are allowed. `sourcetype=access_combined_wcookie` style patterns are common."},{"id":"D","text":"It specifies an index.","correct":false,"why":"Naming an index is allowed and often sensible for scoping."}],"answer":["A"],"explanation":"The same restriction list forbids a subsearch and forbids referencing a report with the savedsearch command. An event type is a classification rule, so it has to be a plain search expression rather than a pipeline.","sec":"6.3","secTitle":"Create an event type","grp":"6","traps":["T-06-03","T-06-04"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"authored","note":"Three restrictions to carry in: no pipe, no subsearch, no savedsearch reference.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/define-event-types-in-splunk-web","title":"Define event types in Splunk Web (Knowledge Management 10.4)","note":"An event type search cannot include a pipe operator or a subsearch.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-04","type":"single","stem":"Event type priorities range from 1 to 10. Which value is the highest priority?","options":[{"id":"A","text":"1","correct":true,"why":"The documentation states plainly that 1 is the best priority and 10 is the worst. Lower number wins."},{"id":"B","text":"10","correct":false,"why":"This is the intuitive reading if you think of priority as a score, and it is the reverse of the documented scale."},{"id":"C","text":"0","correct":false,"why":"Zero is outside the documented range, which starts at 1."},{"id":"D","text":"5, as the midpoint and default","correct":false,"why":"A midpoint is not a priority ranking, and priority is optional rather than defaulting to the middle."}],"answer":["A"],"explanation":"Priority does two things: event types with a priority sort above those without and order among themselves by value, and only one event type colour displays per event, so the highest priority decides the colour.","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-05","T-06-06"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"authored","note":"The documentation's own example gives critical_disk_error priority 3 and a broad catch-all a worse number, which is a useful memory hook for the direction of the scale.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-type-priorities","title":"About event type priorities (Knowledge Management 10.4)","note":"Priority is 1 through 10, where 1 is best and 10 is worst.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-05","type":"single","stem":"An event matches three different event types. What does the `eventtype` field contain?","options":[{"id":"A","text":"All three names, as a multivalue field.","correct":true,"why":"A single event can match many event types, and eventtype behaves as a multivalue field when it does."},{"id":"B","text":"Only the highest-priority name.","correct":false,"why":"Priority orders the values and decides the displayed colour, but it does not discard the others."},{"id":"C","text":"Only the first name alphabetically.","correct":false,"why":"Alphabetical order plays no part in selecting a single winner, because there is no single winner."},{"id":"D","text":"The three names concatenated into one string.","correct":false,"why":"They are separate values in a multivalue field, not a joined string."}],"answer":["A"],"explanation":"eventtype is multivalue when several event types match. The values are ordered by priority score first, then alphabetically, and only one colour displays per event.","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-07"],"read":["topics/06-tags-and-event-types.md#result-contract"],"verdict":"authored","note":"Because eventtype is a field like any other, it can itself be tagged, which is how `eventtype=failed_login` ends up carrying a CIM tag such as authentication.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-types","title":"About event types (Knowledge Management 10.4)","note":"An event can match multiple event types; eventtype is multivalue in that case.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-06","type":"single","stem":"How does an event type differ from a report?","options":[{"id":"A","text":"An event type classifies matching events automatically at search time; a report is a saved search you run to get a result set.","correct":true,"why":"One is a passive classification applied to data, the other is an action that produces results on demand or on a schedule."},{"id":"B","text":"They are the same object under two names in the UI.","correct":false,"why":"They are separate knowledge objects with separate management pages and separate conf files."},{"id":"C","text":"An event type can be scheduled; a report cannot.","correct":false,"why":"Scheduling belongs to reports and alerts. An event type has no schedule."},{"id":"D","text":"A report classifies events; an event type returns a result set.","correct":false,"why":"The two roles are swapped here."}],"answer":["A"],"explanation":"An event type is a category that attaches itself to every matching event whenever a search runs. A report is a stored search that you execute. This is also why an event type definition cannot reference a report with savedsearch.","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-08"],"read":["topics/06-tags-and-event-types.md#what-it-is"],"verdict":"authored","note":"Reports are not on the SPLK-1002 blueprint in their own right. They appear here only as the thing an event type is contrasted with.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-types","title":"About event types (Knowledge Management 10.4)","note":"Event types categorise events at search time, unlike saved searches.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-07","type":"single","stem":"In the sequence of search-time operations, which comes last?","options":[{"id":"A","text":"Tags","correct":true,"why":"Tags are the ninth and final step, which is why a tag can be applied to an event type but an event type cannot be built on a tag."},{"id":"B","text":"Event types","correct":false,"why":"Event types are step eight, immediately before tags."},{"id":"C","text":"Lookups","correct":false,"why":"Lookups are step seven, before both event types and tags."},{"id":"D","text":"Calculated fields","correct":false,"why":"Calculated fields are step six, before lookups."}],"answer":["A"],"explanation":"The nine steps in order: field filters, EXTRACT-, REPORT-, KV_MODE, FIELDALIAS-, EVAL-, LOOKUP-, event types, tags. Most cross-section questions on this exam resolve to a position in this list.","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-09"],"read":["reference/knowledge-object-precedence.md"],"verdict":"authored","note":"Nine operations, not the six taught in most courses. The extra three are the distinct extraction mechanisms EXTRACT-, REPORT- and KV_MODE.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/the-sequence-of-search-time-operations","title":"The sequence of search-time operations (Knowledge Management 10.4)","note":"Tags are the final search-time operation.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-08","type":"single","stem":"Which statement about priority and colour is correct?","options":[{"id":"A","text":"They are properties of an event type, and an event type can itself be tagged.","correct":true,"why":"Priority and colour belong to the event type object. Because eventtype is a field, `eventtype=<name>` can then be tagged like any other pair."},{"id":"B","text":"They are properties of a tag.","correct":false,"why":"Tags have neither. They are a name attached to a field-value pair and carry no display attributes."},{"id":"C","text":"They are properties of both tags and event types.","correct":false,"why":"Only event types have them."},{"id":"D","text":"Colour belongs to the event type and priority belongs to the tag.","correct":false,"why":"Both belong to the event type. Splitting them between the two objects is a distractor pattern."}],"answer":["A"],"explanation":"Priority and colour are event type attributes. A statement pairing tags with priority or colour is wrong, but a statement saying you can tag an event type that has a priority and a colour is correct, which is a distinction worth reading carefully in exam wording.","sec":"6.2","secTitle":"Describe event types and their uses","grp":"6","traps":["T-06-13"],"read":["topics/06-tags-and-event-types.md#traps"],"verdict":"authored","note":"The printed Apress guide keys a question on this incorrectly, which is recorded in source-notes/apress-errata.md.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/event-types/about-event-type-priorities","title":"About event type priorities (Knowledge Management 10.4)","note":"Priority and colour are configured on the event type.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-09","type":"single","stem":"A host was renamed for an input, so historical events carry `host=old-name` and new events carry `host=new-name`. Both must be searchable together without editing the data. What is the standard remedy?","options":[{"id":"A","text":"Apply the same tag to both `host=old-name` and `host=new-name`, then search by tag.","correct":true,"why":"Tagging adds a shared searchable label to both pairs while leaving the underlying values untouched."},{"id":"B","text":"Create a field alias mapping old-name to new-name.","correct":false,"why":"Aliases map field names to other field names, not one value of a field to another value."},{"id":"C","text":"Reindex the historical data with the new host value.","correct":false,"why":"Reindexing is expensive and unnecessary when a search-time label solves it."},{"id":"D","text":"Define a calculated field that rewrites host on the older events.","correct":false,"why":"This would overwrite the real value, losing the information about which physical input produced the event."}],"answer":["A"],"explanation":"This is the canonical use of tags: one label spanning several values of the same field. It works retroactively because tags are applied at search time, and it never mutates the stored value.","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-14"],"read":["topics/06-tags-and-event-types.md#decision-rules"],"verdict":"authored","note":"The same shape of answer applies to normalising several source-specific values onto one CIM tag, which is where sections 6.0 and 10.0 meet.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in search (Knowledge Management 10.4)","note":"Tags let you group several field values under one searchable name.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-06-10","type":"multi","stem":"Which two statements about managing tags in Splunk Web are true? (Choose two.)","options":[{"id":"A","text":"Settings, Tags offers views by field-value pair, by tag name, and all unique tag objects.","correct":true,"why":"Three distinct views exist, each useful for a different task."},{"id":"B","text":"Disabling a tag from the List by tag name page disables it across all apps that contain it.","correct":true,"why":"That page operates on the tag name globally rather than on one field-value pairing."},{"id":"C","text":"Tags are defined in eventtypes.conf using the `tags` attribute.","correct":false,"why":"That attribute exists but the spec marks it deprecated and points to tags.conf. Tags on an event type live in tags.conf under `[eventtype=<name>]`."},{"id":"D","text":"A tag can only be applied to one field-value pair at a time.","correct":false,"why":"The same tag name can be applied to many pairs, which is what makes tags useful for normalisation."}],"answer":["A","B"],"explanation":"Three views, and a global effect when disabling by tag name. The conf file to know is tags.conf, with stanza headers of the form `[eventtype=<name>]` when tagging an event type.","sec":"6.1","secTitle":"Create and use tags","grp":"6","traps":["T-06-10","T-06-11"],"read":["topics/06-tags-and-event-types.md#syntax-and-options"],"verdict":"authored","note":"Knowing which conf file owns which object is reliably worth a mark: tags.conf for tags, eventtypes.conf for event types, props.conf for aliases and calculated fields, macros.conf for macros, workflow_actions.conf for workflow actions.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/tags/tag-field-value-pairs-in-search","title":"Tag field-value pairs in search (Knowledge Management 10.4)","note":"The three tag management views and their scope.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-06"],"authored":true},{"id":"sg-07-01","type":"single","stem":"Which character delimits a search macro reference?","options":[{"id":"A","text":"The backtick, as in `` `mymacro` ``","correct":true,"why":"The backtick shares a key with the tilde. It is the only delimiter that triggers macro expansion."},{"id":"B","text":"The single quotation mark, as in 'mymacro'","correct":false,"why":"Single quotes do not invoke a macro. The text is treated as an ordinary search term."},{"id":"C","text":"The double quotation mark, as in \"mymacro\"","correct":false,"why":"Double quotes also fail to expand, and in fact macros inside quoted values are explicitly not expanded."},{"id":"D","text":"The dollar sign, as in $mymacro$","correct":false,"why":"Dollar signs delimit argument tokens inside a macro definition, not the macro reference itself."}],"answer":["A"],"explanation":"Backticks invoke, dollar signs substitute. Two different jobs and two different characters, and mixing them up is the most common macro error.","sec":"7.2","secTitle":"Create and use a basic macro","grp":"7","traps":["T-07-01"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"authored","note":"The platform does not expand macros inside quoted values, so a backtick reference buried in a quoted string will not fire either.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/use-search-macros-in-searches","title":"Use search macros in searches (Knowledge Management 10.4)","note":"Macro references are enclosed in backtick characters.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-02","type":"single","stem":"A macro takes three arguments. What must it be named in Settings, and how is it invoked?","options":[{"id":"A","text":"Named `mymacro(3)`, invoked as `` `mymacro(a,b,c)` ``","correct":true,"why":"The stored name carries the argument count. The invocation carries the actual values."},{"id":"B","text":"Named `mymacro`, invoked as `` `mymacro(3)` ``","correct":false,"why":"This reverses the two. The number in the invocation would be read as a single argument value."},{"id":"C","text":"Named `mymacro(a,b,c)`, invoked as `` `mymacro(3)` ``","correct":false,"why":"Argument names go in the separate Arguments field, not into the macro name."},{"id":"D","text":"Named `mymacro`, invoked as `` `mymacro(a,b,c)` ``","correct":false,"why":"Calling with arguments when only a bare-name macro exists is an error rather than a call with arguments."}],"answer":["A"],"explanation":"The documentation is explicit: if your search macro includes two arguments, name it mymacro(2). `[foobar]` and `[foobar(1)]` are different macros, not one macro with an optional argument.","sec":"7.4","secTitle":"Add and use arguments with a macro","grp":"7","traps":["T-07-02","T-07-11"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"authored","note":"Because the count is part of the name, you can define several macros sharing a base name with different arity, and they coexist independently.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Management 10.4)","note":"Name a macro with its argument count, for example mymacro(2).","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-03","type":"single","stem":"How are argument names written in the Arguments field, and how are they referenced in the Definition?","options":[{"id":"A","text":"Bare and comma-delimited in Arguments, as `val, rate`; wrapped in dollar signs in the Definition, as `$val$`","correct":true,"why":"Arguments takes a comma-delimited string of names. The Definition references them with the dollar-sign token pattern."},{"id":"B","text":"Dollar-wrapped in both places","correct":false,"why":"Adding dollar signs in the Arguments field is a common error; that field wants bare names."},{"id":"C","text":"Bare in both places","correct":false,"why":"Without dollar signs the Definition would treat the name as literal search text and never substitute."},{"id":"D","text":"Backtick-wrapped in the Definition","correct":false,"why":"Backticks invoke other macros. They do not mark argument substitution."}],"answer":["A"],"explanation":"Two quoting rules pull in opposite directions here. Macros are not expanded inside quoted values, but the $<arg>$ pattern is replaced globally, including inside quoted strings.","sec":"7.3","secTitle":"Define arguments and variables for a macro","grp":"7","traps":["T-07-03","T-07-04"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"authored","note":"Argument names may contain only alphanumeric characters, underscores and hyphens, with no repeats. The manual separately warns against hyphens in macro names.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Management 10.4)","note":"Arguments is a comma-delimited string of argument names; the definition uses $arg$.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-04","type":"single","stem":"A macro has a validation expression, and a user supplies an argument that fails it. What does the user see?","options":[{"id":"A","text":"The validation error message, with the search never dispatched.","correct":true,"why":"Validation runs before dispatch, so the search does not execute at all and the configured error message is displayed."},{"id":"B","text":"Zero events, as though the search matched nothing.","correct":false,"why":"An empty result set would be indistinguishable from a genuine no-match. Validation is designed to be louder than that."},{"id":"C","text":"The search runs with the argument replaced by a null value.","correct":false,"why":"No substitution of a default happens. The search is stopped."},{"id":"D","text":"A warning in the job log, with the search running anyway.","correct":false,"why":"Failing validation blocks execution rather than annotating it."}],"answer":["A"],"explanation":"A Boolean validation expression succeeds on true and fails on false or NULL, with errormsg supplying the message. A non-Boolean validation expression inverts that: it succeeds on NULL and fails by returning the message itself.","sec":"7.3","secTitle":"Define arguments and variables for a macro","grp":"7","traps":["T-07-06","T-07-05"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"authored","note":"The two validation modes behaving oppositely is unusual enough to be examinable. Boolean: true is good. Non-Boolean: NULL is good.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf spec (Admin Manual 10.4)","note":"validation and errormsg settings, and the Boolean versus non-Boolean behaviour.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-05","type":"single","stem":"Where does macro expansion sit in the sequence of search-time operations?","options":[{"id":"A","text":"Nowhere in it; expansion is textual and happens before the search is parsed.","correct":true,"why":"The nine-step sequence contains no macro step. A macro is replaced with its text before parsing begins."},{"id":"B","text":"Between field aliases and calculated fields.","correct":false,"why":"That slot belongs to nothing; aliases at step 5 are followed directly by calculated fields at step 6."},{"id":"C","text":"Immediately after lookups.","correct":false,"why":"Step 7 is followed by event types. Macros are not part of this ordering at all."},{"id":"D","text":"Last, after tags.","correct":false,"why":"Tags are the final search-time operation, and macros are not a search-time knowledge object in this sense."}],"answer":["A"],"explanation":"A macro is a text substitution performed on the search string. By the time the nine search-time operations run, the macro has already been replaced and is indistinguishable from typed SPL.","sec":"7.1","secTitle":"Describe macros","grp":"7","traps":["T-07-08"],"read":["reference/knowledge-object-precedence.md"],"verdict":"authored","note":"This is why a macro can contain anything at all, including whole pipelines, while an event type definition cannot even contain a pipe.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros","title":"Search macros (Knowledge Management 10.4)","note":"Macros are reusable search string fragments expanded into the search.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-06","type":"single","stem":"A macro should encapsulate `| tstats count WHERE index=web BY _time`. How should the definition be written?","options":[{"id":"A","text":"Without the leading pipe, putting the pipe in front of the reference instead.","correct":true,"why":"The definition holds `tstats count WHERE index=web BY _time` and the search reads `` | `mymacro` ``. The pipe lives at the call site."},{"id":"B","text":"With the leading pipe, so the macro is self-contained.","correct":false,"why":"Keeping the pipe in the definition produces a doubled or misplaced pipe once the text is substituted."},{"id":"C","text":"With the leading pipe, and invoked without a preceding pipe.","correct":false,"why":"This is the documented mistake. The convention is the reverse."},{"id":"D","text":"A generating command cannot be placed in a macro at all.","correct":false,"why":"It can. Only the placement of the leading pipe needs care."}],"answer":["A"],"explanation":"Because expansion is textual, the surrounding pipe structure is your responsibility. Remove the leading pipe from the definition and write it in front of the backtick reference.","sec":"7.2","secTitle":"Create and use a basic macro","grp":"7","traps":["T-07-09"],"read":["topics/07-macros.md#worked-examples"],"verdict":"authored","note":"The same reasoning explains why a macro can sit mid-pipeline with further commands after it. Nothing about a macro has to end a search.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/search-macro-examples","title":"Search macro examples (Knowledge Management 10.4)","note":"Definitions omit the leading pipe; the reference carries it.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-07","type":"single","stem":"A two-argument macro `foobar(2)` is defined with arguments `foo` and `bar`. Which invocations are equivalent according to the documentation's own example?","options":[{"id":"A","text":"`` `foobar(1,2)` ``, `` `foobar(foo=1,bar=2)` `` and `` `foobar(bar=2,foo=1)` ``","correct":true,"why":"The macros.conf example states these three forms are equivalent, so arguments can be positional or named, and named arguments can be reordered."},{"id":"B","text":"Only `` `foobar(1,2)` ``, because macro arguments are strictly positional","correct":false,"why":"Named arguments are supported. This is the assumption the documentation's example specifically refutes."},{"id":"C","text":"Only the two named forms, because a two-argument macro requires named arguments","correct":false,"why":"The positional form works and is the most common in practice."},{"id":"D","text":"None; a macro can take at most one argument","correct":false,"why":"Macros routinely take several arguments; the count simply goes in the name."}],"answer":["A"],"explanation":"Positional and named invocation both work, and named arguments may appear in any order. This is easy to miss because most examples in circulation only ever show the positional form.","sec":"7.4","secTitle":"Add and use arguments with a macro","grp":"7","traps":["T-07-12"],"read":["topics/07-macros.md#worked-examples"],"verdict":"authored","note":"Sourced from macros.conf.example, which is shipped with the product and is the authority for this behaviour.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf spec (Admin Manual 10.4)","note":"Example showing positional and named invocation as equivalent.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-08","type":"single","stem":"What does `iseval = true` mean on a macro definition?","options":[{"id":"A","text":"The definition is an eval expression returning a string, and that string becomes the macro's expansion.","correct":true,"why":"The macro computes its own replacement text. The result is search text, not a field value."},{"id":"B","text":"The macro runs an eval command and adds a computed field to the results.","correct":false,"why":"No field is created. The eval expression produces the text that replaces the macro reference."},{"id":"C","text":"The macro may only be used inside an eval expression.","correct":false,"why":"There is no such placement restriction."},{"id":"D","text":"Argument validation is performed with eval syntax.","correct":false,"why":"That is what the separate validation setting does."}],"answer":["A"],"explanation":"iseval defaults to false. When set, the definition is evaluated as an eval expression and its returned string is substituted, which lets a macro build different search text depending on its arguments.","sec":"7.3","secTitle":"Define arguments and variables for a macro","grp":"7","traps":["T-07-13"],"read":["topics/07-macros.md#syntax-and-options"],"verdict":"authored","note":"Consistent with macros being textual: even an eval-backed macro produces text for the parser rather than data for the pipeline.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/macros.conf","title":"macros.conf spec (Admin Manual 10.4)","note":"iseval: the definition is an eval expression returning a string representing the expansion.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-09","type":"single","stem":"A macro is created in Search and Reporting and shared at app level. A colleague working in a different app cannot use it. Why?","options":[{"id":"A","text":"App-level sharing makes an object available only to users of that app; global use requires All apps.","correct":true,"why":"The object is bound to the app context it was created in until it is promoted to All apps."},{"id":"B","text":"Macros cannot be shared between users under any circumstances.","correct":false,"why":"They can be shared to an app or globally like other knowledge objects."},{"id":"C","text":"The colleague lacks the power role, which is required to invoke any macro.","correct":false,"why":"Roles govern who can share and promote, not who can invoke a macro that is already visible to them."},{"id":"D","text":"Macros require a restart before other users can see them.","correct":false,"why":"macros.conf is among the search-time files whose settings take effect without a restart."}],"answer":["A"],"explanation":"Permission scope is the usual explanation for it works for me but not for them. Promote to All apps for cross-app use. No restart is needed either way.","sec":"7.2","secTitle":"Create and use a basic macro","grp":"7","traps":["T-07-14","T-07-07"],"read":["topics/07-macros.md#traps"],"verdict":"authored","note":"The Admin Manual page on when a restart is required lists macros.conf among search-time files that take effect after an endpoint refresh.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/get-started-with-knowledge-objects/manage-knowledge-object-permissions","title":"Manage knowledge object permissions (Knowledge Management 10.4)","note":"App-level sharing limits visibility to that app until promoted globally.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-07-10","type":"multi","stem":"Which two statements about search macros are true? (Choose two.)","options":[{"id":"A","text":"A macro definition can contain a full pipeline including multiple commands.","correct":true,"why":"Because expansion is textual, anything valid as search text is valid in a definition."},{"id":"B","text":"A macro reference can be followed by further commands in the same search.","correct":true,"why":"Nothing requires a macro to end a search. It substitutes text and the pipeline continues."},{"id":"C","text":"A macro with arguments must also define a validation expression and an error message.","correct":false,"why":"Validation is optional. Arguments work without it."},{"id":"D","text":"Macros are configured under Settings, Fields alongside aliases and calculated fields.","correct":false,"why":"Macros have their own page under Settings, Advanced search, Search macros."}],"answer":["A","B"],"explanation":"A macro is text, so it composes freely: whole pipelines inside, more commands after. Validation is optional, and macros live under Advanced search rather than with the field-related objects.","sec":"7.1","secTitle":"Describe macros","grp":"7","traps":["T-07-16","T-07-17","T-07-18"],"read":["topics/07-macros.md#what-it-is"],"verdict":"authored","note":"Knowing the Settings path matters: Settings, Advanced search, Search macros. Distractors routinely place them under Fields.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/search-macros/define-search-macros-in-settings","title":"Define search macros in Settings (Knowledge Management 10.4)","note":"Navigation path and the optional nature of validation.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-07"],"authored":true},{"id":"sg-08-01","type":"single","stem":"How many values does the Action type setting of a workflow action have, and what are they?","options":[{"id":"A","text":"Two: link and search","correct":true,"why":"GET and POST are both link actions, separated by the Link method setting. In workflow_actions.conf the setting is `type` with values link or search."},{"id":"B","text":"Three: GET, POST and Search","correct":false,"why":"This mirrors the blueprint wording of objective 8.1 and is exactly why it is a good distractor. GET and POST are not action types."},{"id":"C","text":"Four: GET, POST, Search and Link","correct":false,"why":"Adding Link to the three does not fix the underlying error."},{"id":"D","text":"Two: GET and POST","correct":false,"why":"This drops the search action entirely, which is one of the two real types."}],"answer":["A"],"explanation":"The blueprint names three kinds of workflow action, but the configuration has two types. A GET and a POST are both `type = link`, distinguished by `link.method = get` or `post`.","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-01"],"read":["topics/08-workflow-actions.md#what-it-is"],"verdict":"authored","note":"Reading the blueprint wording as a configuration list is the mistake. Objective titles describe capabilities, not settings.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf spec (Admin Manual 10.4)","note":"type is link or search; link.method selects get or post.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-02","type":"single","stem":"A workflow action stanza sets `type = link` and `link.uri` but omits `link.method`. What happens?","options":[{"id":"A","text":"A GET is issued, because link.method defaults to get.","correct":true,"why":"The default makes the stanza valid and functional. Only type and label are required, plus link.uri for a link action."},{"id":"B","text":"Nothing happens; the action is inert without a method.","correct":false,"why":"The default supplies the method, so the action works."},{"id":"C","text":"The stanza is invalid and is ignored at load time.","correct":false,"why":"It is a complete and valid link action."},{"id":"D","text":"A POST is issued, because POST is the safer default.","correct":false,"why":"There is no safety-based default. GET is the documented one."}],"answer":["A"],"explanation":"Required settings are type and label, plus link.uri for a link action or search.search_string for a search action. Everything else has a default, and link.method defaults to get.","sec":"8.2","secTitle":"Create a GET workflow action","grp":"8","traps":["T-08-03"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"authored","note":"link.target defaults to blank, meaning a new window, and search.target works the same way.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf spec (Admin Manual 10.4)","note":"link.method default is get; link.target default is blank.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-03","type":"single","stem":"The \"Apply only to the following fields\" box is left empty. Where does the workflow action appear?","options":[{"id":"A","text":"Everywhere, because `fields` defaults to `*`.","correct":true,"why":"The wildcard matches all fields, so an unrestricted action is offered on every event and field menu it is eligible for."},{"id":"B","text":"Nowhere, because no field has been nominated.","correct":false,"why":"An empty restriction is not an empty allowlist. Restriction is opt-in."},{"id":"C","text":"Only on the event menu, never on field menus.","correct":false,"why":"That would be a display_location question, and its default is both."},{"id":"D","text":"Only on fields that are in Selected Fields.","correct":false,"why":"The sidebar's selection has no bearing on workflow action scope."}],"answer":["A"],"explanation":"Two independent defaults make a new action broadly visible: `fields` defaults to `*` and `display_location` defaults to `both`, so it appears in the event menu and in every field menu.","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-04","T-08-12"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"authored","note":"Scope is controlled by fields and eventtypes only. There is no sourcetype setting on the form or in the conf file.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/control-workflow-action-appearance-in-field-and-event-menus","title":"Control workflow action appearance (Knowledge Management 10.4)","note":"fields defaults to * and display_location defaults to both.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-04","type":"single","stem":"A workflow action sets `fields = src_ip, dest_ip`. When is it offered?","options":[{"id":"A","text":"Only when both fields are present on the event.","correct":true,"why":"The field list is a conjunction. Every field named must be present before the action applies."},{"id":"B","text":"When either field is present.","correct":false,"why":"Reading the list as a disjunction is the common error. It is an AND, not an OR."},{"id":"C","text":"When at least one field is present and the event has an event type.","correct":false,"why":"Event types are a separate, independent restriction under the eventtypes setting."},{"id":"D","text":"Always, because listing fields only affects the menu label.","correct":false,"why":"The field list genuinely restricts where the action appears."}],"answer":["A"],"explanation":"All listed fields must be present. The documented example `*, ip_client, ip_server` is explicit about this, which is also why including the wildcard alongside named fields does not loosen the requirement.","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-05"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"authored","note":"The `$@field_name$` and `$@field_value$` tokens only resolve from a field menu, so a generic per-field action has to be scoped with fields rather than left global.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/control-workflow-action-appearance-in-field-and-event-menus","title":"Control workflow action appearance (Knowledge Management 10.4)","note":"All fields in the list must be present for the action to apply.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-05","type":"single","stem":"How are POST arguments transmitted, compared with GET?","options":[{"id":"A","text":"HTTP-form encoded in the request body, so they do not appear in the URL or browser history.","correct":true,"why":"POST arguments are configured as link.postargs key and value pairs and are sent in the body rather than the query string."},{"id":"B","text":"Appended to the URI as query parameters, exactly like GET.","correct":false,"why":"That would make POST a GET with extra configuration, which is precisely the misconception."},{"id":"C","text":"Encrypted, which is why POST is preferred for sensitive values.","correct":false,"why":"Nothing about POST encrypts anything. Transport security depends entirely on whether the URI is https."},{"id":"D","text":"As HTTP headers rather than as a body or a query string.","correct":false,"why":"Headers are not where the postargs settings put values."}],"answer":["A"],"explanation":"POST guarantees placement, not confidentiality. Keeping a value out of the URL and out of browser history is a real benefit, but only https protects it in transit.","sec":"8.3","secTitle":"Create a POST workflow action","grp":"8","traps":["T-08-06","T-08-18"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"authored","note":"Encoding also differs by destination: values in link.uri are URI encoded automatically, POST argument values are HTTP-form encoded automatically.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-post-workflow-action","title":"Set up a POST workflow action (Knowledge Management 10.4)","note":"POST arguments are sent as form-encoded key-value pairs.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-06","type":"single","stem":"A search workflow action sets `search.earliest = -7d` and `search.preserve_timerange = true`. What time range does the secondary search use?","options":[{"id":"A","text":"The last seven days; preserve_timerange is ignored when earliest or latest is set.","correct":true,"why":"An explicit bound wins, and the preserve setting has no effect at all in that case."},{"id":"B","text":"The originating search's range, because preserve_timerange takes precedence.","correct":false,"why":"That would be true only if neither earliest nor latest were set."},{"id":"C","text":"The intersection of the two, so the narrower range applies.","correct":false,"why":"No intersection is computed. One setting simply overrides the other."},{"id":"D","text":"All time, because the conflicting settings cancel out.","correct":false,"why":"Nothing cancels. The explicit bound is used."}],"answer":["A"],"explanation":"To inherit the originating search's range, set preserve_timerange and leave both bounds unset. Setting either bound silently disables the preserve behaviour.","sec":"8.4","secTitle":"Create a Search workflow action","grp":"8","traps":["T-08-08"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"authored","note":"Two more search-action defaults: search.app defaults to the current app and search.view to the current view, so the secondary search opens wherever the analyst already was.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/set-up-a-search-workflow-action","title":"Set up a search workflow action (Knowledge Management 10.4)","note":"preserve_timerange is ignored if earliest or latest is specified.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-07","type":"single","stem":"Which setting supplies the text a searcher sees in the workflow action menu?","options":[{"id":"A","text":"Label, which also accepts `$field$` tokens","correct":true,"why":"Label is the menu text and is the field that supports token substitution, so a menu entry can include a value from the event."},{"id":"B","text":"Name, which becomes the stanza header","correct":false,"why":"Name is the internal identifier and becomes the stanza header in workflow_actions.conf. It is not what the searcher reads."},{"id":"C","text":"Both, since Name is shown when Label is empty","correct":false,"why":"There is no documented fallback of that kind. Label is a required setting."},{"id":"D","text":"link.uri, whose hostname is displayed","correct":false,"why":"The target URI is never used as the menu text."}],"answer":["A"],"explanation":"Name is internal, Label is what people see, and Label is where tokens work. A label can be static or include field values, so tokens are supported and never required.","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-10","T-08-16"],"read":["topics/08-workflow-actions.md#syntax-and-options"],"verdict":"authored","note":"No Splunk documentation forbids spaces in a workflow action name. The shipped workflow_actions.conf.example defines stanzas whose names contain spaces.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Management 10.4)","note":"Label is the menu text and supports field tokens; Name is the internal identifier.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-08","type":"single","stem":"What does a workflow action do to the events it appears on?","options":[{"id":"A","text":"Nothing. It creates no field and modifies no event; it fires only when a person clicks it.","correct":true,"why":"A workflow action is an interactive shortcut in Splunk Web. It has no effect on the data or the result set."},{"id":"B","text":"It adds a field holding the target URI.","correct":false,"why":"No field is created by a workflow action."},{"id":"C","text":"It triggers automatically whenever a matching event is returned.","correct":false,"why":"Automatic responses to conditions are alert actions on a saved search, not workflow actions."},{"id":"D","text":"It enriches the event with data retrieved from the target system.","correct":false,"why":"Nothing is retrieved back into the search. The action opens a link or launches a second search."}],"answer":["A"],"explanation":"Workflow actions are click-driven navigation, not data processing. If a question describes something happening automatically or a field appearing, the answer is an alert action or a lookup rather than a workflow action.","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-11"],"read":["topics/08-workflow-actions.md#what-it-is"],"verdict":"authored","note":"This is the conceptual question in 8.0 most likely to appear, because the other three sub-objectives are configuration detail.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/workflow-actions/about-workflow-actions-in-splunk-web","title":"About workflow actions in Splunk Web (Knowledge Management 10.4)","note":"Workflow actions create interactive links and searches from events and fields.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-08-09","type":"multi","stem":"Which two settings restrict where a workflow action appears? (Choose two.)","options":[{"id":"A","text":"`fields`","correct":true,"why":"Lists the fields that must all be present on the event. Defaults to the wildcard."},{"id":"B","text":"`eventtypes`","correct":true,"why":"Limits the action to events carrying the named event types, and is independent of the field restriction."},{"id":"C","text":"`sourcetype`","correct":false,"why":"There is no sourcetype setting in workflow_actions.conf and none on the form. Listing sourcetype under fields does not achieve it either."},{"id":"D","text":"`index`","correct":false,"why":"Index is not a scope for workflow actions any more than it is for props.conf settings."}],"answer":["A","B"],"explanation":"Scope is fields and eventtypes only, and display_location decides which menus it can appear in. Any answer naming a source type or an index as a workflow action scope is wrong on the configuration alone.","sec":"8.1","secTitle":"Describe the function of GET, POST, and Search workflow actions","grp":"8","traps":["T-08-17"],"read":["topics/08-workflow-actions.md#decision-rules"],"verdict":"authored","note":"Because eventtypes is a scope, tagging and event types feed directly into workflow action targeting, which is one of the few real cross-links between sections 6.0 and 8.0.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.0-configuration-file-reference/workflow_actions.conf","title":"workflow_actions.conf spec (Admin Manual 10.4)","note":"fields and eventtypes are the scoping settings; no sourcetype setting exists.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-08"],"authored":true},{"id":"sg-09-01","type":"single","stem":"What is the relationship between a data model and Pivot?","options":[{"id":"A","text":"The data model supplies the dataset; Pivot is the SPL-free interface that consumes it to build a report.","correct":true,"why":"Pivot cannot run without a data model. The model defines the structured dataset that Pivot then reports on."},{"id":"B","text":"Pivot supplies the dataset that the data model reports on.","correct":false,"why":"The dependency runs the other way, and this reversal is a documented trap."},{"id":"C","text":"They are independent features that happen to share a menu.","correct":false,"why":"Pivot has a hard dependency on a data model."},{"id":"D","text":"Pivot generates a data model automatically from any search.","correct":false,"why":"Saving a Pivot-built table from a non-transforming search does create a model behind the scenes, but that is a specific flow rather than the general relationship."}],"answer":["A"],"explanation":"A data model is a hierarchical, structured view of your data. Pivot is the interface that lets someone build reports from it without writing SPL. Model first, Pivot second.","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-01"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"authored","note":"The printed Apress guide states this backwards, which is recorded in source-notes/apress-errata.md.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/pivot-manual/10.4/pivot-overview/introduction-to-pivot","title":"Introduction to Pivot (Pivot Manual 10.4)","note":"Pivot reports are built on data model datasets.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-02","type":"single","stem":"How many dataset types does a data model support, and what are they?","options":[{"id":"A","text":"Four: event, search, transaction and child","correct":true,"why":"The documentation states datasets break down into four types, and child is one of them rather than a modifier of the other three."},{"id":"B","text":"Three: event, search and transaction","correct":false,"why":"This omits child datasets, which the docs list as a type in their own right."},{"id":"C","text":"Two: root and child","correct":false,"why":"Root is a position in the hierarchy rather than a type name, and it does not capture the event, search and transaction distinction."},{"id":"D","text":"Five: event, search, transaction, child and accelerated","correct":false,"why":"Acceleration is a property you enable, not a dataset type."}],"answer":["A"],"explanation":"The documented sentence is worth memorising: datasets break down into four types, event datasets, search datasets, transaction datasets and child datasets. A question offering three is the common trap.","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-22"],"read":["topics/09-data-models-and-pivot.md#what-it-is"],"verdict":"authored","note":"The transcribed practice bank keys this as three types. The fact-check corrected it against the docs, and the corrected version is what the simulator scores against.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/about-data-models","title":"About data models (Knowledge Management 10.4)","note":"\"Datasets break down into four types. These types are: Event datasets, search datasets, transaction datasets, and child datasets.\"","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-03","type":"single","stem":"A data model has been accelerated and now needs a new field. What must happen first?","options":[{"id":"A","text":"Turn off its acceleration; an accelerated data model cannot be edited.","correct":true,"why":"The documentation is explicit: after you accelerate a data model you cannot edit it, and making changes requires turning acceleration off."},{"id":"B","text":"Nothing; accelerated models can be edited and the summary rebuilds itself.","correct":false,"why":"Editing is blocked while acceleration is on, so no rebuild is triggered."},{"id":"C","text":"Clone the model, edit the clone, and delete the original.","correct":false,"why":"This works around a restriction that has a documented remedy, and cloning is separately discouraged in the CIM guidance."},{"id":"D","text":"Rebuild the summary manually, then edit.","correct":false,"why":"A manual rebuild does not unlock editing. Acceleration has to be turned off."}],"answer":["A"],"explanation":"Accelerated means uneditable, not permanent. Turn acceleration off, make the change, turn it back on. The summary is then rebuilt for the model as it now stands.","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-09-19"],"read":["topics/09-data-models-and-pivot.md#traps"],"verdict":"authored","note":"The transcribed practice bank keys this as create a new model. The docs give the turn-off-acceleration answer verbatim on the Manage data models page.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/manage-data-models","title":"Manage data models (Knowledge Management 10.4)","note":"\"After you accelerate a data model, you cannot edit it. To make changes to an accelerated data model, you must turn off its acceleration.\"","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-04","type":"single","stem":"Which dataset type can add auto-extracted fields?","options":[{"id":"A","text":"Root datasets only; child datasets inherit them.","correct":true,"why":"Auto-extracted fields are added at the root. Every other field type, including eval expression, lookup, regular expression and Geo IP, can be added at any level."},{"id":"B","text":"Any dataset, root or child.","correct":false,"why":"This is true of the other field types but not of auto-extracted fields."},{"id":"C","text":"Child datasets only.","correct":false,"why":"Children inherit rather than add auto-extracted fields."},{"id":"D","text":"Only transaction datasets.","correct":false,"why":"Transaction datasets are one root type among several and have no special claim here."}],"answer":["A"],"explanation":"Five field types exist: auto-extracted, eval expression, lookup, regular expression and Geo IP. Only the first is restricted to root datasets. Inheritance carries them down, and a child dataset inherits all constraints and all fields from every ancestor.","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-05","T-09-02"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"authored","note":"Inheritance is cumulative, so each level down returns strictly fewer events than its parent, never more.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/define-data-model-dataset-fields/define-dataset-fields","title":"Define dataset fields (Knowledge Management 10.4)","note":"Auto-extracted fields can only be added to root datasets.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-05","type":"single","stem":"What does marking a data model field as Required do?","options":[{"id":"A","text":"It filters out any event that does not have the field, acting as an additional constraint.","correct":true,"why":"Required is not documentation. It shrinks the dataset, so marking a sparse field Required can quietly remove most of your events."},{"id":"B","text":"It marks the field as important for whoever maintains the model.","correct":false,"why":"It has a real filtering effect rather than being advisory."},{"id":"C","text":"It makes Pivot require a value for the field before running a report.","correct":false,"why":"It is not a form validation. The filtering happens on the data, not on user input."},{"id":"D","text":"It forces the field to be indexed at index time.","correct":false,"why":"Data models are entirely search-time constructs."}],"answer":["A"],"explanation":"Required acts as another constraint on top of the formal constraints. Compare with Hidden, which suppresses the field only for Pivot users defining a report while leaving it fully present in the dataset and reachable from SPL.","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-06","T-09-07"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"authored","note":"Required and Hidden are frequently offered as each other's definition, so read the option carefully for which one filters and which one only affects the Pivot interface.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/define-data-model-dataset-fields/define-dataset-fields","title":"Define dataset fields (Knowledge Management 10.4)","note":"Required filters events lacking the field; Hidden affects the Pivot interface only.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-06","type":"single","stem":"Which statement about a root event dataset's constraint is correct?","options":[{"id":"A","text":"It looks like the first part of a search, before any pipe or additional commands.","correct":true,"why":"A constraint is a simple search expression. Anything needing a pipe requires a root search dataset instead."},{"id":"B","text":"It can include a pipe and a transforming command such as `stats count`.","correct":false,"why":"That is what a root search dataset is for. A root event dataset constraint cannot contain a pipe."},{"id":"C","text":"It must include at least one search macro.","correct":false,"why":"Macros are not required, and child dataset constraints cannot include them at all."},{"id":"D","text":"It is optional; a root event dataset with no constraint matches all events.","correct":false,"why":"The constraint is what defines which events belong to the dataset."}],"answer":["A"],"explanation":"Root event datasets take a simple search expression. Root search datasets take a full pipeline and are the escape hatch when you need commands, at the cost that acceleration only works if the search uses streaming commands.","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-09-08","T-09-15"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"authored","note":"Child dataset constraints cannot include search macros, and searches referencing such datasets fail rather than degrade.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/design-data-models","title":"Design data models (Knowledge Management 10.4)","note":"Constraints look like the first part of a search, before pipes and additional commands.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-07","type":"single","stem":"Which data model property can never be changed after the dataset is created?","options":[{"id":"A","text":"Dataset ID","correct":true,"why":"Dataset ID accepts only alphanumerics, underscores and hyphens, cannot contain spaces, and cannot be changed once set."},{"id":"B","text":"Dataset Name","correct":false,"why":"Dataset Name accepts any character except asterisks and can be edited freely."},{"id":"C","text":"The constraint","correct":false,"why":"Constraints are editable, provided the model is not accelerated at the time."},{"id":"D","text":"The parent dataset","correct":false,"why":"Hierarchy can be restructured while the model is editable."}],"answer":["A"],"explanation":"Name is a label and is editable. ID is an identifier and is permanent, with a restricted character set. This mirrors the Name versus Label distinction in workflow actions, where one is internal and one is presentational.","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-09-09"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"authored","note":"Being permanent, the Dataset ID is what SPL references, which is why `tstats` and `from` use it rather than the display name.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/build-a-data-model/design-data-models","title":"Design data models (Knowledge Management 10.4)","note":"Dataset ID cannot be changed after creation; Dataset Name can.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-08","type":"single","stem":"What is required before a data model can be accelerated?","options":[{"id":"A","text":"The model must be shared at app level or globally, and the user needs the `accelerate_datamodel` capability.","correct":true,"why":"Private data models cannot be accelerated, and the capability is a separate requirement on the user's role."},{"id":"B","text":"Nothing; any user can accelerate a model they own.","correct":false,"why":"Both a sharing requirement and a capability requirement stand in the way."},{"id":"C","text":"The model must contain at least one transaction dataset.","correct":false,"why":"Transaction datasets are not an acceleration requirement, and root search datasets built on transforming searches cannot be accelerated at all."},{"id":"D","text":"The underlying indexes must be summary indexes.","correct":false,"why":"Acceleration builds its own summaries; it does not require summary indexes as input."}],"answer":["A"],"explanation":"Acceleration also needs a suitable hierarchy: at least one root event hierarchy, or a root search hierarchy using only streaming commands. A root search dataset built on a transforming search cannot be accelerated.","sec":"9.3","secTitle":"Create a data model","grp":"9","traps":["T-09-14","T-09-04"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"authored","note":"Ad hoc acceleration, which Pivot uses on an unaccelerated model, lives in the search head dispatch directory and is deleted when you leave the Pivot Editor.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/use-data-summaries-to-accelerate-searches/accelerate-data-models","title":"Accelerate data models (Knowledge Management 10.4)","note":"Private data models cannot be accelerated; the accelerate_datamodel capability is required.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-09","type":"single","stem":"Which separator does `tstats` use between the data model and its root dataset?","options":[{"id":"A","text":"An equals sign, as in `FROM datamodel=Web.Web`","correct":true,"why":"tstats uses `FROM datamodel=<model>.<root_dataset>`. The `from` command is the one that uses a colon."},{"id":"B","text":"A colon, as in `FROM datamodel:Web.Web`","correct":false,"why":"The colon form belongs to `from datamodel:<model>.<dataset>`."},{"id":"C","text":"A dot, as in `FROM datamodel.Web.Web`","correct":false,"why":"The dot separates model from dataset, not the keyword from the model."},{"id":"D","text":"A space, as in `FROM datamodel Web.Web`","correct":false,"why":"Neither command uses a bare space here."}],"answer":["A"],"explanation":"tstats takes an equals sign, from takes a colon. Options that swap the two are the standard distractor pair, and both commands use a dot between the model and the dataset.","sec":"9.1","secTitle":"Describe the relationship between data models and pivot","grp":"9","traps":["T-09-10","T-09-11"],"read":["topics/09-data-models-and-pivot.md#syntax-and-options"],"verdict":"authored","note":"summariesonly defaults to false, so tstats runs over accelerated and unaccelerated models alike unless you restrict it.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/search/spl-search-reference/10.4/search-commands/tstats","title":"tstats command (SPL Search Reference 10.4)","note":"FROM datamodel=<model>.<dataset> syntax and the summariesonly default.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-09-10","type":"multi","stem":"Which two statements about data model field ordering and Geo IP fields are true? (Choose two.)","options":[{"id":"A","text":"Fields are processed from the top of the list downward, so a field reading another calculated field must sit below it.","correct":true,"why":"Order is functional rather than cosmetic. A field placed above its dependency evaluates against nothing."},{"id":"B","text":"Geo IP fields are added as Required and their types are predetermined.","correct":true,"why":"Neither the Required flag nor the types can be changed for Geo IP output fields."},{"id":"C","text":"Field order in the list is purely presentational.","correct":false,"why":"This is the belief the processing order refutes."},{"id":"D","text":"Geo IP fields can be marked Optional like any other calculated field.","correct":false,"why":"They cannot. Required is fixed for them."}],"answer":["A","B"],"explanation":"Two easily-missed mechanics. Ordering matters because fields evaluate top to bottom. Geo IP fields are constrained: fixed types, fixed Required flag, and they need an existing field of type ipv4 positioned above them.","sec":"9.2","secTitle":"Identify data model attributes","grp":"9","traps":["T-09-17","T-09-16"],"read":["topics/09-data-models-and-pivot.md#traps"],"verdict":"authored","note":"The ordering rule is the data model analogue of calculated fields not chaining within a props.conf stanza, though here order does help rather than being ignored.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/splunk-enterprise/manage-knowledge-objects/knowledge-management-manual/10.4/define-data-model-dataset-fields/define-dataset-fields","title":"Define dataset fields (Knowledge Management 10.4)","note":"Fields are processed in descending order; Geo IP fields are Required with predetermined types.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-09"],"authored":true},{"id":"sg-10-01","type":"single","stem":"When does the Common Information Model normalize data?","options":[{"id":"A","text":"At search time; it leaves the raw machine data intact.","correct":true,"why":"The CIM is a search-time schema. Installing the add-on reindexes nothing and modifies no stored event."},{"id":"B","text":"At index time, rewriting events into a common format.","correct":false,"why":"Nothing is rewritten. This misreads normalisation as transformation of stored data."},{"id":"C","text":"At ingest, before the data reaches the indexers.","correct":false,"why":"The add-on is not part of the ingest path at all."},{"id":"D","text":"On a schedule, as a summarisation job.","correct":false,"why":"Acceleration builds summaries on a schedule, but that is separate from normalisation and is off by default."}],"answer":["A"],"explanation":"Schema on the fly. The CIM defines expected field names and tags, and knowledge objects map your data onto them when a search runs. That is also why the add-on is installed on search heads only.","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-01","T-10-05"],"read":["topics/10-cim.md#what-it-is"],"verdict":"authored","note":"Search heads only, because the add-on contains only search-time knowledge objects. Answers naming indexers or forwarders are wrong for that reason.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/overview-of-the-splunk-common-information-model","title":"Overview of the Splunk CIM (CIM 8.6)","note":"The CIM is a search-time schema that leaves raw machine data intact.","primary":true}],"difficulty":"easy","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-02","type":"single","stem":"A fresh CIM add-on installation is complete. What is the acceleration state of its data models?","options":[{"id":"A","text":"Off for every model; you enable it per model on the CIM Setup page.","correct":true,"why":"All data models included in the CIM add-on have acceleration turned off by default."},{"id":"B","text":"On for every model, which is why the add-on speeds searches immediately.","correct":false,"why":"Nothing is accelerated on install, so no speed-up happens by itself."},{"id":"C","text":"On for the security models only.","correct":false,"why":"There is no partial default. All are off."},{"id":"D","text":"Determined automatically by data volume.","correct":false,"why":"Acceleration is an explicit administrative choice, never automatic."}],"answer":["A"],"explanation":"The practical consequence is that a `tstats summariesonly=true` search against a stock CIM model returns nothing, because no summary exists yet. That looks like broken data and is actually the default state.","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-02","T-09-03"],"read":["topics/10-cim.md#syntax-and-options"],"verdict":"authored","note":"Enabling acceleration is done per model on the CIM Setup page, where the Indexes allowlist for that model also lives.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/accelerate-cim-data-models","title":"Accelerate CIM data models (CIM 8.6)","note":"All CIM data models have acceleration turned off by default.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-03","type":"single","stem":"Events have been given correct CIM field names but no tags. What is the result?","options":[{"id":"A","text":"The events do not appear in the data model at all, because tags are what admit events to a dataset.","correct":true,"why":"Membership is decided by the constraint, which for CIM event datasets is a tag expression. Field names alone put the events nowhere."},{"id":"B","text":"They appear in the model but with null values.","correct":false,"why":"That is what happens when tags are correct and a field is missing, which is the opposite situation."},{"id":"C","text":"They appear, because field names are the constraint.","correct":false,"why":"Field names are the payload, not the admission criterion."},{"id":"D","text":"Splunk warns that the events are non-compliant.","correct":false,"why":"Nothing warns. Silence is precisely the difficulty with CIM compliance."}],"answer":["A"],"explanation":"Two separate obligations. Tags decide membership, fields carry the values. Correct fields without tags means no membership; correct tags with a missing field means membership with a null column and no warning.","sec":"10.3","secTitle":"Use the CIM Add-On to normalize data","grp":"10","traps":["T-10-03","T-CIM-08"],"read":["topics/10-cim.md#decision-rules"],"verdict":"authored","note":"Child datasets inherit the parent constraint, so the Web model's Proxy dataset needs both web and proxy, not proxy alone.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-to-normalize-data-at-search-time","title":"Use the CIM to normalize data at search time (CIM 8.6)","note":"Tags admit events into an event dataset; fields carry the normalised values.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-04","type":"single","stem":"What is the default state of the Indexes allowlist for a CIM data model?","options":[{"id":"A","text":"It searches all indexes, so the allowlist is a performance control rather than a prerequisite.","correct":true,"why":"By default each data model searches every index. Restricting it improves performance but is not required for the model to return data."},{"id":"B","text":"It is empty, so the model returns nothing until indexes are added.","correct":false,"why":"An empty allowlist would make the add-on inert on install, which is not the behaviour."},{"id":"C","text":"It contains only the main index.","correct":false,"why":"There is no such single-index default."},{"id":"D","text":"It updates automatically as new indexes are created.","correct":false,"why":"Once you set an allowlist, new indexes must be added by hand."}],"answer":["A"],"explanation":"All indexes by default. Setting the allowlist is the single highest-value CIM performance change, and the older documentation calls the same setting an index whitelist.","sec":"10.1","secTitle":"Describe the Splunk CIM","grp":"10","traps":["T-10-04","T-CIM-12"],"read":["topics/10-cim.md#syntax-and-options"],"verdict":"authored","note":"This guide previously asserted a `cim_<Model>_indexes` macro convention for index scoping. The fact-check found no CIM 8.6 page documenting it; the allowlist on the CIM Setup page is the mechanism.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/set-up-the-splunk-common-information-model-add-on","title":"Set up the Splunk CIM add-on (CIM 8.6)","note":"Each data model searches all indexes by default; the allowlist restricts it.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-05","type":"multi","stem":"Which two knowledge object types does the CIM add-on rely on to normalize data? (Choose two.)","options":[{"id":"A","text":"Field aliases","correct":true,"why":"Aliasing a source-specific field name onto the CIM name is the most common normalisation step."},{"id":"B","text":"Lookups","correct":true,"why":"Lookups map source-specific values onto the CIM's expected values, for example turning a numeric code into allowed or blocked."},{"id":"C","text":"Workflow actions","correct":false,"why":"Workflow actions are click-driven UI shortcuts and play no part in normalisation."},{"id":"D","text":"Search macros","correct":false,"why":"The add-on ships some macros, but they are not part of the documented normalisation set."}],"answer":["A","B"],"explanation":"The documented set is field aliases, field extractions and lookups, alongside the event types and tags that admit events to a dataset, plus calculated fields for derived values such as `bytes = bytes_in + bytes_out`.","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-10-19","T-CIM-16"],"read":["topics/10-cim.md#syntax-and-options"],"verdict":"authored","note":"The add-on does not ship tsidx summary files, custom visualizations, or a dashboard library. Column stores exist only once acceleration is enabled, and the one shipped dashboard is Data Model Audit.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/use-the-cim-to-normalize-data-at-search-time","title":"Use the CIM to normalize data at search time (CIM 8.6)","note":"Field aliases, field extractions, lookups, event types and tags are the normalisation objects.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-06","type":"single","stem":"A firewall event is normalized into Network Traffic with `action=denied`. What happens?","options":[{"id":"A","text":"Nothing rejects it, but it will never match content expecting the prescribed values.","correct":true,"why":"Expected values are not exhaustive or exclusive and nothing validates them. Network Traffic prescribes allowed, blocked and teardown."},{"id":"B","text":"The event is rejected from the data model.","correct":false,"why":"Membership is decided by tags. Field values do not gate admission."},{"id":"C","text":"Splunk maps it automatically to the nearest expected value.","correct":false,"why":"No automatic mapping exists. That is what a lookup in your add-on is for."},{"id":"D","text":"The search errors when the field is used.","correct":false,"why":"No error is raised. The failure is entirely silent."}],"answer":["A"],"explanation":"The consequence of an out-of-spec value is silence: the data is in the model, and every dashboard and correlation search looking for the prescribed value simply misses it. Intrusion Detection is stricter still, allowing only allowed and blocked.","sec":"10.3","secTitle":"Use the CIM Add-On to normalize data","grp":"10","traps":["T-10-10","T-CIM-02","T-CIM-03"],"read":["reference/cim-data-models.md"],"verdict":"authored","note":"In Change, action records what was attempted and status carries success or failure. Only in Authentication does action itself carry the outcome.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models/cim-fields-per-associated-data-model","title":"CIM fields per associated data model (CIM 8.6)","note":"Expected values per model; they are not exhaustive or exclusive.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-07","type":"single","stem":"Which command is shipped by the CIM add-on rather than being core SPL?","options":[{"id":"A","text":"`datamodelsimple`","correct":true,"why":"It is a custom command inside Splunk_SA_CIM and does not exist without the add-on installed."},{"id":"B","text":"`datamodel`","correct":false,"why":"Core SPL, available on any Splunk Enterprise installation."},{"id":"C","text":"`tstats`","correct":false,"why":"Core SPL, and the usual way to query an accelerated data model."},{"id":"D","text":"`pivot`","correct":false,"why":"Core SPL, and the command behind the Pivot interface."}],"answer":["A"],"explanation":"datamodel, tstats, pivot and from are all core. datamodelsimple is the odd one out, shipped inside Splunk_SA_CIM. A question asking which command depends on the add-on has exactly one answer.","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-10-09"],"read":["topics/10-cim.md#syntax-and-options"],"verdict":"authored","note":"The app identity is worth knowing too: the Splunk Common Information Model Add-on is app 1621, Splunk_SA_CIM. The Splunk Add-on Builder is a different app entirely.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/introduction/install-the-splunk-common-information-model-add-on","title":"Install the Splunk CIM add-on (CIM 8.6)","note":"Contents of Splunk_SA_CIM, including the datamodelsimple command.","primary":true}],"difficulty":"medium","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-08","type":"single","stem":"A custom field must be added to a CIM data model. What does the documentation recommend?","options":[{"id":"A","text":"Add the field to the model itself; cloning the model and keeping the original is not considered a best practice.","correct":true,"why":"The docs state cloning to preserve the original is not best practice, so the supported route is modifying the model."},{"id":"B","text":"Clone the model and extend the clone, keeping the original for reference.","correct":false,"why":"This is the approach the documentation explicitly discourages."},{"id":"C","text":"Create a new data model that inherits from the CIM model.","correct":false,"why":"Data models do not inherit from each other; inheritance exists between datasets within one model."},{"id":"D","text":"Add the field via props.conf on the source type instead of touching the model.","correct":false,"why":"That makes the field available on events but does not add it to the model's field list."}],"answer":["A"],"explanation":"Extend the model in place, and prefer not extending at all where the existing schema will do. Cloning leaves two models drifting apart, and acceleration then has to be paid for twice.","sec":"10.3","secTitle":"Use the CIM Add-On to normalize data","grp":"10","traps":["T-10-13"],"read":["topics/10-cim.md#decision-rules"],"verdict":"authored","note":"Remember that an accelerated model cannot be edited at all, so any extension starts by turning acceleration off.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/using-the-common-information-model/approaches-to-using-the-cim","title":"Approaches to using the CIM (CIM 8.6)","note":"Cloning a data model and keeping the original is not a best practice.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-10"],"authored":true},{"id":"sg-10-09","type":"single","stem":"Which CIM data model covers a DHCP lease assignment?","options":[{"id":"A","text":"Network Sessions","correct":true,"why":"Network Sessions covers DHCP, tagged network, session and dhcp, and also covers VPN tunnel establishment."},{"id":"B","text":"Network Traffic","correct":false,"why":"Network Traffic covers flows between hosts. The payload inside a VPN tunnel belongs here; establishing the session does not."},{"id":"C","text":"Network Resolution","correct":false,"why":"Network Resolution covers DNS, not address assignment."},{"id":"D","text":"Inventory","correct":false,"why":"Inventory describes what exists in the environment rather than session events."}],"answer":["A"],"explanation":"Session establishment versus traffic is the distinction. DHCP and VPN connection events are Network Sessions; the flows that follow are Network Traffic. Network Resolution is DNS.","sec":"10.2","secTitle":"List the knowledge objects included with the Splunk CIM Add-On","grp":"10","traps":["T-CIM-15","T-10-06"],"read":["reference/cim-data-models.md"],"verdict":"authored","note":"Two model names to keep current: the model is Inventory, not Compute Inventory, and Application State is deprecated in favour of Endpoint.","courseKey":[],"corrected":null,"docs":[{"url":"https://help.splunk.com/en/data-management/common-information-model/8.6/data-models","title":"Data models (CIM 8.6)","note":"Network Sessions covers DHCP and VPN session events.","primary":true}],"difficulty":"hard","issues":[],"block":null,"tests":["authored-10"],"authored":true}]};
